import type { BankQuestion } from "@/lib/bank";

/** Indian Economy Basics (Economy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"eco-basics-1","question":"GDP stands for:","options":["Gross Domestic Product","General Development Programme","Gross Development Product","Grand Domestic Production"],"answer":0,"explanation":"GDP is the total value of final goods and services produced within a country in a year.","difficulty":"easy","questionHi":"GDP का पूर्ण रूप क्या है?","optionsHi":["सकल घरेलू उत्पाद (Gross Domestic Product)","सामान्य विकास कार्यक्रम (General Development Programme)","सकल विकास उत्पाद (Gross Development Product)","भव्य घरेलू उत्पादन (Grand Domestic Production)"],"explanationHi":"GDP किसी देश की सीमाओं के भीतर एक वर्ष में उत्पादित सभी अंतिम वस्तुओं और सेवाओं का कुल मूल्य होता है।"},
  {"id":"eco-basics-2","question":"GST was implemented in India from:","options":["1 April 2016","1 July 2017","1 January 2018","1 April 2017"],"answer":1,"explanation":"GST came into force on 1 July 2017, launched at a special midnight session of Parliament under the 101st Constitutional Amendment. 1 April 2017, the originally targeted start of the financial year, is the usual trap.","difficulty":"easy","questionHi":"भारत में GST कब से लागू हुआ?","optionsHi":["1 अप्रैल 2016","1 जुलाई 2017","1 जनवरी 2018","1 अप्रैल 2017"],"explanationHi":"GST 1 जुलाई 2017 से लागू हुआ, जिसे 101वें संविधान संशोधन के अंतर्गत संसद के विशेष मध्यरात्रि सत्र में शुरू किया गया। 1 अप्रैल 2017, जो वित्त वर्ष की मूल रूप से लक्षित शुरुआत थी, आम जाल (भ्रम) है।"},
  {"id":"eco-basics-3","question":"The rate at which the RBI lends money to commercial banks is called the:","options":["Reverse repo rate","Repo rate","Bank rate","CRR"],"answer":1,"explanation":"The repo rate is the rate at which the RBI lends to banks against government securities.","difficulty":"moderate","questionHi":"वह दर जिस पर RBI वाणिज्यिक बैंकों को धन उधार देता है, कहलाती है:","optionsHi":["रिवर्स रेपो दर","रेपो दर","बैंक दर","CRR"],"explanationHi":"रेपो दर वह दर है जिस पर RBI सरकारी प्रतिभूतियों के बदले बैंकों को उधार देता है।"},
  {"id":"eco-basics-4","question":"NITI Aayog replaced which body?","options":["Finance Commission","Planning Commission","National Development Council","Election Commission"],"answer":1,"explanation":"NITI Aayog replaced the Planning Commission on 1 January 2015.","difficulty":"moderate","questionHi":"नीति आयोग ने किस निकाय का स्थान लिया?","optionsHi":["वित्त आयोग","योजना आयोग","राष्ट्रीय विकास परिषद","निर्वाचन आयोग"],"explanationHi":"नीति आयोग ने 1 जनवरी 2015 को योजना आयोग का स्थान लिया।"},
  {"id":"eco-basics-5","question":"The RBI was nationalised in:","options":["1935","1947","1949","1969"],"answer":2,"explanation":"The RBI began in 1935 as a shareholders' bank under the RBI Act, 1934 and was nationalised on 1 January 1949. 1969 is the year 14 major commercial banks were nationalised, the most common mix-up.","difficulty":"moderate","questionHi":"RBI का राष्ट्रीयकरण कब हुआ?","optionsHi":["1935","1947","1949","1969"],"explanationHi":"RBI की शुरुआत 1935 में RBI अधिनियम, 1934 के अंतर्गत अंशधारकों के बैंक के रूप में हुई और 1 जनवरी 1949 को इसका राष्ट्रीयकरण किया गया। 1969 वह वर्ष है जब 14 प्रमुख वाणिज्यिक बैंकों का राष्ट्रीयकरण हुआ, जो सबसे आम भ्रम है।"},
  {"id":"eco-basics-6","question":"GST was introduced through which Constitutional Amendment?","options":["100th","101st","102nd","103rd"],"answer":1,"explanation":"The 101st Constitutional Amendment Act, 2016 inserted Articles 246A and 279A (the GST Council) to enable GST. The 100th Amendment dealt with the India–Bangladesh land boundary, and the 102nd gave constitutional status to the NCBC.","difficulty":"hard","questionHi":"GST किस संविधान संशोधन के माध्यम से लागू किया गया?","optionsHi":["100वाँ","101वाँ","102वाँ","103वाँ"],"explanationHi":"101वें संविधान संशोधन अधिनियम, 2016 ने GST को संभव बनाने के लिए अनुच्छेद 246A और 279A (GST परिषद) जोड़े। 100वाँ संशोधन भारत-बांग्लादेश भूमि सीमा से संबंधित था, और 102वें ने NCBC को संवैधानिक दर्जा दिया।"},
  {"id":"eco-basics-7","question":"The rate at which the RBI borrows money from commercial banks is called the:","options":["Repo rate","Reverse repo rate","Bank rate","Marginal Standing Facility rate"],"answer":1,"explanation":"Under a reverse repo, banks park surplus funds with the RBI against government securities and earn interest. The repo rate is the opposite (the RBI lends to banks), as are the bank rate and the MSF rate; since 2022 the collateral-free SDF is the floor of the corridor.","difficulty":"hard","questionHi":"वह दर जिस पर RBI वाणिज्यिक बैंकों से धन उधार लेता है, कहलाती है:","optionsHi":["रेपो दर","रिवर्स रेपो दर","बैंक दर","सीमांत स्थायी सुविधा (MSF) दर"],"explanationHi":"रिवर्स रेपो में बैंक अपनी अधिशेष निधि सरकारी प्रतिभूतियों के बदले RBI के पास रखते हैं और ब्याज कमाते हैं। रेपो दर इसके विपरीत है (RBI बैंकों को उधार देता है), और बैंक दर तथा MSF दर भी ऐसी ही हैं; 2022 से बिना गिरवी वाली SDF गलियारे की निचली सीमा है।"},
  {"id":"eco-basics-8","question":"Which of the following is an indirect tax?","options":["Income tax","Corporate tax","GST","Wealth tax"],"answer":2,"explanation":"GST is levied on goods and services and passed on to the consumer, so it is indirect.","difficulty":"hard","questionHi":"निम्नलिखित में से कौन-सा एक अप्रत्यक्ष कर है?","optionsHi":["आयकर","निगम कर","GST","संपत्ति कर"],"explanationHi":"GST वस्तुओं और सेवाओं पर लगाया जाता है और उपभोक्ता पर डाल दिया जाता है, इसलिए यह अप्रत्यक्ष कर है।"},
  {"id":"eco-basics-9","question":"The Fiscal Responsibility and Budget Management (FRBM) Act was enacted in:","options":["1991","2003","2005","2016"],"answer":1,"explanation":"The FRBM Act, 2003 set targets for reducing the fiscal deficit.","difficulty":"very-hard","questionHi":"राजकोषीय उत्तरदायित्व और बजट प्रबंधन (FRBM) अधिनियम कब अधिनियमित किया गया?","optionsHi":["1991","2003","2005","2016"],"explanationHi":"FRBM अधिनियम, 2003 ने राजकोषीय घाटे को कम करने के लक्ष्य तय किए।"},
  {"id":"eco-basics-10","question":"Who was the first Governor of the Reserve Bank of India?","options":["C. D. Deshmukh","Sir Osborne Smith","James Braid Taylor","Benegal Rama Rau"],"answer":1,"explanation":"Sir Osborne Smith was the first Governor (1935–37); C. D. Deshmukh was the first Indian Governor.","difficulty":"very-hard","questionHi":"भारतीय रिज़र्व बैंक के पहले गवर्नर कौन थे?","optionsHi":["सी. डी. देशमुख","सर ऑस्बॉर्न स्मिथ","जेम्स ब्रेड टेलर","बेनेगल रामा राव"],"explanationHi":"सर ऑस्बॉर्न स्मिथ पहले गवर्नर (1935–37) थे; सी. डी. देशमुख पहले भारतीय गवर्नर थे।"},
  {"id":"eco-basics-11","question":"The Minimum Support Price (MSP) for crops is recommended by the:","options":["National Institution for Transforming India (NITI Aayog)","Commission for Agricultural Costs and Prices (CACP)","Food Corporation of India (FCI)","Ministry of Finance, Department of Expenditure"],"answer":1,"explanation":"The CACP recommends MSPs; the Cabinet Committee on Economic Affairs approves them. The FCI procures grain at those prices but does not set them.","difficulty":"very-hard","questionHi":"फसलों का न्यूनतम समर्थन मूल्य (MSP) किसके द्वारा अनुशंसित किया जाता है?","optionsHi":["भारत परिवर्तन हेतु राष्ट्रीय संस्थान (नीति आयोग)","कृषि लागत एवं मूल्य आयोग (CACP)","भारतीय खाद्य निगम (FCI)","वित्त मंत्रालय, व्यय विभाग"],"explanationHi":"CACP MSP की अनुशंसा करता है; आर्थिक मामलों की मंत्रिमंडलीय समिति इन्हें अनुमोदित करती है। FCI इन कीमतों पर अनाज खरीदता है, पर उन्हें तय नहीं करता।"},
  {"id":"eco-basics-12","question":"The Reserve Bank of India was established in:","options":["1921","1935","1947","1949"],"answer":1,"explanation":"The RBI started on 1 April 1935 under the RBI Act, 1934, and was nationalised in 1949.","difficulty":"easy","source":"SSC CGL · IBPS PO","questionHi":"भारतीय रिज़र्व बैंक की स्थापना कब हुई?","optionsHi":["1921","1935","1947","1949"],"explanationHi":"RBI ने 1 अप्रैल 1935 को RBI अधिनियम, 1934 के अंतर्गत कार्य शुरू किया, और 1949 में इसका राष्ट्रीयकरण हुआ।"},
  {"id":"eco-basics-13","question":"Inflation measured on the basis of the wholesale price of goods uses the index:","options":["CPI","WPI","GDP deflator","PPI"],"answer":1,"explanation":"WPI tracks wholesale prices; CPI tracks retail prices paid by consumers.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"वस्तुओं के थोक मूल्य के आधार पर मापी जाने वाली मुद्रास्फीति किस सूचकांक का उपयोग करती है?","optionsHi":["CPI","WPI","GDP अपस्फीतिकारक","PPI"],"explanationHi":"WPI थोक कीमतों को मापता है; CPI उपभोक्ताओं द्वारा चुकाई गई खुदरा कीमतों को मापता है।"},
  {"id":"eco-basics-14","question":"The rate at which the RBI lends short-term funds to commercial banks against securities is the:","options":["Reverse repo rate","Repo rate","Bank rate","CRR"],"answer":1,"explanation":"Repo is the RBI’s lending rate; reverse repo is what it pays banks for their deposits.","difficulty":"moderate","source":"IBPS PO · SBI PO","questionHi":"वह दर जिस पर RBI प्रतिभूतियों के बदले वाणिज्यिक बैंकों को अल्पकालिक धन उधार देता है, कहलाती है:","optionsHi":["रिवर्स रेपो दर","रेपो दर","बैंक दर","CRR"],"explanationHi":"रेपो RBI की उधार देने की दर है; रिवर्स रेपो वह दर है जो वह बैंकों को उनकी जमाओं के लिए देता है।"},
  {"id":"eco-basics-15","question":"Which of these is NOT a direct tax?","options":["Personal income tax","Corporation tax on company profits","Goods and Services Tax","Wealth tax (abolished in 2015)"],"answer":2,"explanation":"GST is an indirect tax: it is collected by the seller and its burden passes to the consumer. Income tax, corporation tax and the wealth tax (abolished from 2015–16) fall on the person who pays them, so they are direct taxes.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"निम्नलिखित में से कौन-सा प्रत्यक्ष कर नहीं है?","optionsHi":["व्यक्तिगत आयकर","कंपनी के लाभ पर निगम कर","वस्तु एवं सेवा कर","संपत्ति कर (2015 में समाप्त)"],"explanationHi":"GST एक अप्रत्यक्ष कर है: इसे विक्रेता वसूलता है और इसका बोझ उपभोक्ता पर चला जाता है। आयकर, निगम कर और संपत्ति कर (2015–16 से समाप्त) उसी व्यक्ति पर पड़ते हैं जो इन्हें चुकाता है, इसलिए ये प्रत्यक्ष कर हैं।"},
  {"id":"eco-basics-16","question":"The “Hindu rate of growth”, describing India’s slow growth before the 1980s, was coined by:","options":["Amartya Sen","Raj Krishna","C. Rangarajan","Jagdish Bhagwati"],"answer":1,"explanation":"Economist Raj Krishna used the phrase for the roughly 3.5% growth of 1950–80.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"1980 के दशक से पहले भारत की धीमी वृद्धि का वर्णन करने वाला शब्द “हिंदू वृद्धि दर” किसने गढ़ा?","optionsHi":["अमर्त्य सेन","राज कृष्ण","सी. रंगराजन","जगदीश भगवती"],"explanationHi":"अर्थशास्त्री राज कृष्ण ने 1950–80 की लगभग 3.5% की वृद्धि के लिए इस शब्द का प्रयोग किया।"},
  {"id":"eco-basics-17","question":"Fiscal deficit equals:","options":["Revenue expenditure − revenue receipts","Total expenditure − non-debt receipts","Total expenditure − total receipts including borrowings","Primary deficit − interest payments"],"answer":1,"explanation":"Fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts), i.e. the government's borrowing requirement. Revenue expenditure − revenue receipts is the revenue deficit; including borrowings makes the gap zero, and FD = primary deficit + interest, not minus.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO","questionHi":"राजकोषीय घाटा किसके बराबर होता है?","optionsHi":["राजस्व व्यय − राजस्व प्राप्तियाँ","कुल व्यय − गैर-ऋण प्राप्तियाँ","कुल व्यय − उधारियों सहित कुल प्राप्तियाँ","प्राथमिक घाटा − ब्याज भुगतान"],"explanationHi":"राजकोषीय घाटा = कुल व्यय − (राजस्व प्राप्तियाँ + गैर-ऋण पूँजीगत प्राप्तियाँ), अर्थात सरकार की उधार की आवश्यकता। राजस्व व्यय − राजस्व प्राप्तियाँ राजस्व घाटा है; उधारियों को शामिल करने पर अंतर शून्य हो जाता है, और FD = प्राथमिक घाटा + ब्याज, न कि घटा।"},
  {"id":"eco-basics-18","question":"Consider: 1. The repo rate is a quantitative tool of credit control. 2. Raising the CRR increases money supply. 3. Open market operations mean buying and selling government securities. Which are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"A higher CRR locks up more bank money with the RBI and reduces money supply.","difficulty":"hard","questionHi":"विचार कीजिए: 1. रेपो दर साख नियंत्रण का एक मात्रात्मक उपकरण है। 2. CRR बढ़ाने से मुद्रा आपूर्ति बढ़ती है। 3. खुले बाजार की क्रियाओं का अर्थ सरकारी प्रतिभूतियों की खरीद और बिक्री है। कौन-से कथन सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"उच्च CRR बैंकों के अधिक धन को RBI के पास रोक देता है और मुद्रा आपूर्ति को घटाता है।"},
  {"id":"eco-basics-19","question":"GDP at market price minus depreciation equals:","options":["GNP at market price","NDP at market price","NNP at factor cost","GDP at factor cost"],"answer":1,"explanation":"Subtracting depreciation turns “gross” into “net”: NDP at market price.","difficulty":"hard","questionHi":"बाजार कीमत पर GDP में से मूल्यह्रास घटाने पर क्या प्राप्त होता है?","optionsHi":["बाजार कीमत पर GNP","बाजार कीमत पर NDP","साधन लागत पर NNP","साधन लागत पर GDP"],"explanationHi":"मूल्यह्रास घटाने से “सकल” “शुद्ध” बन जाता है: बाजार कीमत पर NDP।"},
  {"id":"eco-basics-20","question":"If net factor income from abroad is negative, then:","options":["GNP > GDP","GNP < GDP","GNP = GDP","NNP > GNP"],"answer":1,"explanation":"GNP = GDP + net factor income from abroad, so a negative NFIA makes GNP smaller.","difficulty":"very-hard","questionHi":"यदि विदेशों से शुद्ध साधन आय ऋणात्मक हो, तो:","optionsHi":["GNP > GDP","GNP < GDP","GNP = GDP","NNP > GNP"],"explanationHi":"GNP = GDP + विदेशों से शुद्ध साधन आय, इसलिए ऋणात्मक NFIA GNP को छोटा कर देती है।"},
  {"id":"eco-basics-21","question":"Fiscal deficit minus interest payments is called the:","options":["Revenue deficit","Primary deficit","Effective revenue deficit","Budget deficit"],"answer":1,"explanation":"Primary deficit shows borrowing needed for current spending other than interest.","difficulty":"very-hard","questionHi":"राजकोषीय घाटे में से ब्याज भुगतान घटाने पर क्या कहलाता है?","optionsHi":["राजस्व घाटा","प्राथमिक घाटा","प्रभावी राजस्व घाटा","बजट घाटा"],"explanationHi":"प्राथमिक घाटा ब्याज के अलावा वर्तमान खर्च के लिए आवश्यक उधारी को दर्शाता है।"},
  {"id":"eco-basics-22","question":"How many of these statements are correct? I. GST came into force on 1 July 2017. II. The GST Council is chaired by the Union Finance Minister. III. Alcohol for human consumption is outside GST. IV. Crude petroleum is currently taxed under GST.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Crude, diesel, petrol, natural gas and ATF are not yet taxed under GST.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. GST 1 जुलाई 2017 को लागू हुआ। II. GST परिषद की अध्यक्षता केंद्रीय वित्त मंत्री करते हैं। III. मानव उपभोग के लिए शराब GST से बाहर है। IV. कच्चा पेट्रोलियम वर्तमान में GST के अंतर्गत कराधीन है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। कच्चा तेल, डीजल, पेट्रोल, प्राकृतिक गैस और ATF पर अभी GST नहीं लगता।"},
  {"id":"eco-basics-23","question":"How many of these statements are correct? I. Stagflation means high inflation with stagnant growth. II. Deflation is a fall in the general price level. III. Disinflation means the general price level is falling.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Disinflation is a fall in the rate of inflation; prices still rise, just more slowly.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. स्टैगफ्लेशन का अर्थ उच्च मुद्रास्फीति के साथ ठहरी हुई वृद्धि है। II. अपस्फीति सामान्य मूल्य स्तर में गिरावट है। III. विस्फीति का अर्थ है कि सामान्य मूल्य स्तर गिर रहा है।","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"केवल I और II। विस्फीति मुद्रास्फीति की दर में गिरावट है; कीमतें फिर भी बढ़ती हैं, बस धीमी गति से।"},
  {"id":"eco-basics-24","question":"How many of these statements are correct? I. GDP at factor cost = GDP at market prices − net indirect taxes. II. NNP = GNP − depreciation. III. GNP = GDP + net factor income from abroad.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"GDP at factor cost = GDP at market prices − (indirect taxes − subsidies); NNP = GNP − depreciation; GNP = GDP + net factor income from abroad. All three identities hold, so 'Only two' (usually from doubting the net-indirect-tax step) is the trap.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. साधन लागत पर GDP = बाजार कीमतों पर GDP − शुद्ध अप्रत्यक्ष कर। II. NNP = GNP − मूल्यह्रास। III. GNP = GDP + विदेशों से शुद्ध साधन आय।","optionsHi":["केवल एक","केवल दो","तीनों","कोई नहीं"],"explanationHi":"साधन लागत पर GDP = बाजार कीमतों पर GDP − (अप्रत्यक्ष कर − सब्सिडी); NNP = GNP − मूल्यह्रास; GNP = GDP + विदेशों से शुद्ध साधन आय। तीनों सर्वसमिकाएँ सही हैं, इसलिए ‘केवल दो’ (प्रायः शुद्ध अप्रत्यक्ष कर वाले चरण पर संदेह से) जाल है।"},
  {"id":"eco-basics-25","question":"Which measure of money supply is called “broad money”?","options":["M1","M2","M3","M4"],"answer":2,"explanation":"M3 (M1 plus time deposits with banks) is broad money; M1 is narrow money.","difficulty":"very-hard","questionHi":"मुद्रा आपूर्ति के किस माप को “व्यापक मुद्रा” कहा जाता है?","optionsHi":["M1","M2","M3","M4"],"explanationHi":"M3 (M1 और बैंकों में सावधि जमाएँ) व्यापक मुद्रा है; M1 संकीर्ण मुद्रा है।"},
  {"id":"eco-basics-26","question":"If the RBI raises the cash reserve ratio, what follows?","options":["The money multiplier falls","The money multiplier rises","Banks have more funds to lend","The repo rate falls automatically"],"answer":0,"explanation":"The money multiplier is roughly 1 ÷ reserve ratio, so a higher CRR shrinks it and leaves banks less to lend.","difficulty":"very-hard","questionHi":"यदि RBI नकद आरक्षित अनुपात बढ़ाता है, तो क्या होता है?","optionsHi":["मुद्रा गुणक घटता है","मुद्रा गुणक बढ़ता है","बैंकों के पास उधार देने के लिए अधिक धन होता है","रेपो दर अपने आप घट जाती है"],"explanationHi":"मुद्रा गुणक लगभग 1 ÷ आरक्षित अनुपात होता है, इसलिए उच्च CRR इसे घटाता है और बैंकों के पास उधार देने के लिए कम धन बचता है।"},
  {"id":"eco-basics-27","question":"How many of these statements are correct? I. Revenue deficit = revenue expenditure − revenue receipts. II. Effective revenue deficit = revenue deficit − grants given for the creation of capital assets. III. Disinvestment proceeds are capital receipts. IV. Interest payments are capital expenditure.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Interest payments create no asset, so they are revenue expenditure.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO","questionHi":"इनमें से कितने कथन सही हैं? I. राजस्व घाटा = राजस्व व्यय − राजस्व प्राप्तियाँ। II. प्रभावी राजस्व घाटा = राजस्व घाटा − पूँजीगत परिसंपत्तियों के सृजन के लिए दिए गए अनुदान। III. विनिवेश से प्राप्त आय पूँजीगत प्राप्तियाँ हैं। IV. ब्याज भुगतान पूँजीगत व्यय हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। ब्याज भुगतान से कोई परिसंपत्ति नहीं बनती, इसलिए वे राजस्व व्यय हैं।"},
  {"id":"eco-basics-28","question":"Banks must hold reserves equal to 20% of deposits. If the central bank adds ₹1,000 crore of fresh reserves to the system, the maximum increase in deposits under the simple multiplier is:","options":["₹5,000 crore","₹2,000 crore","₹1,200 crore","₹20,000 crore"],"answer":0,"explanation":"Deposit multiplier = 1 ÷ reserve ratio = 1 ÷ 0.2 = 5, so ₹1,000 crore can support ₹5,000 crore of deposits.","difficulty":"very-hard","source":"IBPS PO · UPSC Prelims","questionHi":"बैंकों को जमाओं के 20% के बराबर आरक्षित निधि रखनी होती है। यदि केंद्रीय बैंक प्रणाली में ₹1,000 करोड़ की नई आरक्षित निधि जोड़ता है, तो सरल गुणक के अंतर्गत जमाओं में अधिकतम वृद्धि होगी:","optionsHi":["₹5,000 करोड़","₹2,000 करोड़","₹1,200 करोड़","₹20,000 करोड़"],"explanationHi":"जमा गुणक = 1 ÷ आरक्षित अनुपात = 1 ÷ 0.2 = 5, इसलिए ₹1,000 करोड़ ₹5,000 करोड़ की जमाओं को सहारा दे सकते हैं।"},
  {"id":"eco-basics-29","question":"The headquarters of NITI Aayog is located in:","options":["Mumbai","New Delhi","Kolkata","Hyderabad"],"answer":1,"explanation":"NITI Aayog, which replaced the Planning Commission on 1 January 2015, is headquartered in New Delhi with the Prime Minister as its chairperson.","difficulty":"easy","source":"SSC CGL · UPSC Prelims","questionHi":"नीति आयोग का मुख्यालय कहाँ स्थित है?","optionsHi":["मुंबई","नई दिल्ली","कोलकाता","हैदराबाद"],"explanationHi":"नीति आयोग, जिसने 1 जनवरी 2015 को योजना आयोग का स्थान लिया, का मुख्यालय नई दिल्ली में है और प्रधानमंत्री इसके अध्यक्ष हैं।"},
  {"id":"eco-basics-30","question":"The Union Budget of India is presented in the Lok Sabha by the:","options":["President of India","Prime Minister","Finance Minister","RBI Governor"],"answer":2,"explanation":"Under Article 112 the President causes the Annual Financial Statement to be laid before Parliament, but it is the Union Finance Minister who presents it in the Lok Sabha. The President's role is formal, which makes it the tempting wrong option.","difficulty":"easy","source":"SSC CGL · UPSC Prelims","questionHi":"भारत का केंद्रीय बजट लोकसभा में किसके द्वारा प्रस्तुत किया जाता है?","optionsHi":["भारत के राष्ट्रपति","प्रधानमंत्री","वित्त मंत्री","RBI गवर्नर"],"explanationHi":"अनुच्छेद 112 के अंतर्गत राष्ट्रपति वार्षिक वित्तीय विवरण को संसद के समक्ष रखवाते हैं, परंतु इसे लोकसभा में केंद्रीय वित्त मंत्री प्रस्तुत करते हैं। राष्ट्रपति की भूमिका औपचारिक है, इसलिए यह आकर्षक गलत विकल्प बन जाता है।"},
  {"id":"eco-basics-31","question":"Per capita income of a country is obtained by dividing its national income by its:","options":["Area","Labour force","Population","Number of households"],"answer":2,"explanation":"Per capita income = national income ÷ total population; it is an average and says nothing about how income is distributed.","difficulty":"easy","source":"SSC CGL · UPSC Prelims","questionHi":"किसी देश की प्रति व्यक्ति आय उसकी राष्ट्रीय आय को किससे भाग देकर प्राप्त की जाती है?","optionsHi":["क्षेत्रफल","श्रम बल","जनसंख्या","परिवारों की संख्या"],"explanationHi":"प्रति व्यक्ति आय = राष्ट्रीय आय ÷ कुल जनसंख्या; यह एक औसत है और आय के वितरण के बारे में कुछ नहीं बताती।"},
  {"id":"eco-basics-32","question":"Which sector contributes the largest share to India’s GDP?","options":["Agriculture","Manufacturing","Services","Mining"],"answer":2,"explanation":"The services (tertiary) sector contributes well over half of India’s gross value added, while agriculture employs the most people but contributes under a fifth of GDP.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"कौन-सा क्षेत्र भारत के GDP में सबसे बड़ा योगदान देता है?","optionsHi":["कृषि","विनिर्माण","सेवा","खनन"],"explanationHi":"सेवा (तृतीयक) क्षेत्र भारत के सकल मूल्य वर्धन में आधे से कहीं अधिक योगदान देता है, जबकि कृषि सबसे अधिक लोगों को रोजगार देती है पर GDP में पाँचवें हिस्से से भी कम योगदान देती है।"},
  {"id":"eco-basics-33","question":"The Consumer Price Index (Combined) used by the RBI for inflation targeting is released by the:","options":["Reserve Bank of India","National Statistical Office","Office of the Economic Adviser, DPIIT","NITI Aayog"],"answer":1,"explanation":"CPI (Combined) is published monthly by the NSO under the Ministry of Statistics; the WPI is released by the Office of the Economic Adviser, DPIIT.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"RBI द्वारा मुद्रास्फीति लक्ष्य निर्धारण के लिए प्रयुक्त उपभोक्ता मूल्य सूचकांक (संयुक्त) किसके द्वारा जारी किया जाता है?","optionsHi":["भारतीय रिज़र्व बैंक","राष्ट्रीय सांख्यिकी कार्यालय","आर्थिक सलाहकार कार्यालय, DPIIT","नीति आयोग"],"explanationHi":"CPI (संयुक्त) सांख्यिकी मंत्रालय के अंतर्गत NSO द्वारा मासिक रूप से प्रकाशित किया जाता है; WPI आर्थिक सलाहकार कार्यालय, DPIIT द्वारा जारी किया जाता है।"},
  {"id":"eco-basics-34","question":"Under the flexible inflation targeting framework, the RBI’s inflation target is:","options":["2% with a band of ±1%","4% with a band of ±2%","6% with a band of ±2%","5% with no band"],"answer":1,"explanation":"The RBI Act (amended 2016) sets a CPI inflation target of 4% with a tolerance band of 2% to 6%, reviewed every five years by the Government.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"लचीले मुद्रास्फीति लक्ष्य निर्धारण ढाँचे के अंतर्गत RBI का मुद्रास्फीति लक्ष्य है:","optionsHi":["2%, ±1% के दायरे के साथ","4%, ±2% के दायरे के साथ","6%, ±2% के दायरे के साथ","5%, बिना किसी दायरे के"],"explanationHi":"RBI अधिनियम (2016 में संशोधित) 4% का CPI मुद्रास्फीति लक्ष्य तय करता है, जिसमें 2% से 6% की सहनशीलता सीमा है, और सरकार द्वारा हर पाँच वर्ष में इसकी समीक्षा की जाती है।"},
  {"id":"eco-basics-35","question":"The Monetary Policy Committee of the RBI consists of how many members?","options":["5","3","6","21"],"answer":2,"explanation":"The MPC has six members: the Governor (chair), the Deputy Governor in charge of monetary policy, one RBI officer and three external members nominated by the Centre. 3 counts only the external members, 5 is the Finance Commission's size, and 21 is the RBI Central Board.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"RBI की मौद्रिक नीति समिति में कितने सदस्य होते हैं?","optionsHi":["5","3","6","21"],"explanationHi":"MPC में छह सदस्य होते हैं: गवर्नर (अध्यक्ष), मौद्रिक नीति के प्रभारी उप-गवर्नर, RBI का एक अधिकारी और केंद्र द्वारा नामित तीन बाहरी सदस्य। 3 केवल बाहरी सदस्यों की संख्या है, 5 वित्त आयोग का आकार है, और 21 RBI का केंद्रीय बोर्ड है।"},
  {"id":"eco-basics-36","question":"Under Article 280 of the Constitution, a Finance Commission is constituted by the President every:","options":["3 years","5 years","7 years","10 years"],"answer":1,"explanation":"A Finance Commission is set up every fifth year (or earlier) to recommend how tax proceeds are shared between the Union and the States.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"संविधान के अनुच्छेद 280 के अंतर्गत राष्ट्रपति द्वारा वित्त आयोग का गठन कितने वर्षों में किया जाता है?","optionsHi":["3 वर्ष","5 वर्ष","7 वर्ष","10 वर्ष"],"explanationHi":"वित्त आयोग प्रत्येक पाँचवें वर्ष (या उससे पहले) गठित किया जाता है, जो संघ और राज्यों के बीच कर आय के बँटवारे की अनुशंसा करता है।"},
  {"id":"eco-basics-37","question":"Disguised unemployment in India is most commonly found in:","options":["The IT sector","Agriculture","Banking","Manufacturing"],"answer":1,"explanation":"In disguised unemployment more people are engaged than needed, so removing some would not reduce output; this is typical of family farms in rural India.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"भारत में प्रच्छन्न बेरोजगारी सबसे अधिक पाई जाती है:","optionsHi":["IT क्षेत्र में","कृषि में","बैंकिंग में","विनिर्माण में"],"explanationHi":"प्रच्छन्न बेरोजगारी में आवश्यकता से अधिक लोग काम में लगे होते हैं, इसलिए कुछ को हटाने से उत्पादन नहीं घटता; यह ग्रामीण भारत के पारिवारिक खेतों की विशेषता है।"},
  {"id":"eco-basics-38","question":"If nominal GDP grew by 10% in a year and the GDP deflator rose by 4%, real GDP grew by approximately:","options":["4%","6%","10%","14%"],"answer":1,"explanation":"Real growth ≈ nominal growth − inflation (deflator) = 10% − 4% ≈ 6%. Exactly, 1.10/1.04 − 1 ≈ 5.8%.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"यदि किसी वर्ष में सांकेतिक GDP में 10% की वृद्धि हुई और GDP अपस्फीतिकारक में 4% की वृद्धि हुई, तो वास्तविक GDP में लगभग कितनी वृद्धि हुई?","optionsHi":["4%","6%","10%","14%"],"explanationHi":"वास्तविक वृद्धि ≈ सांकेतिक वृद्धि − मुद्रास्फीति (अपस्फीतिकारक) = 10% − 4% ≈ 6%। सटीक रूप से, 1.10/1.04 − 1 ≈ 5.8%।"},
  {"id":"eco-basics-39","question":"Which of the following is a capital receipt of the Government of India?","options":["Corporation tax","Dividends from public-sector enterprises","Recovery of loans given to States","Interest received on loans"],"answer":2,"explanation":"Capital receipts either create a liability (borrowings) or reduce an asset (loan recoveries, disinvestment). Taxes, dividends and interest are revenue receipts.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सी भारत सरकार की पूँजीगत प्राप्ति है?","optionsHi":["निगम कर","सार्वजनिक क्षेत्र के उद्यमों से लाभांश","राज्यों को दिए गए ऋणों की वसूली","ऋणों पर प्राप्त ब्याज"],"explanationHi":"पूँजीगत प्राप्तियाँ या तो देयता उत्पन्न करती हैं (उधारियाँ) या परिसंपत्ति घटाती हैं (ऋण वसूली, विनिवेश)। कर, लाभांश और ब्याज राजस्व प्राप्तियाँ हैं।"},
  {"id":"eco-basics-40","question":"“Core inflation” is headline inflation with which items excluded?","options":["Housing and clothing","Food and fuel","Services and imports","Education and health"],"answer":1,"explanation":"Core inflation strips out the volatile food and fuel components to show the underlying trend in prices.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"“कोर मुद्रास्फीति” वह मुख्य मुद्रास्फीति है जिसमें किन मदों को बाहर रखा जाता है?","optionsHi":["आवास और वस्त्र","खाद्य और ईंधन","सेवाएँ और आयात","शिक्षा और स्वास्थ्य"],"explanationHi":"कोर मुद्रास्फीति अस्थिर खाद्य और ईंधन घटकों को हटाकर कीमतों की अंतर्निहित प्रवृत्ति दिखाती है।"},
  {"id":"eco-basics-41","question":"The Marginal Standing Facility (MSF) rate is normally kept at:","options":["25 basis points below the repo rate","Equal to the repo rate","25 basis points above the repo rate","100 basis points above the repo rate"],"answer":2,"explanation":"The MSF rate, at which banks borrow overnight from the RBI in an emergency against SLR securities, forms the ceiling of the LAF corridor, 25 bps above the repo rate; the SDF rate is 25 bps below.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"सीमांत स्थायी सुविधा (MSF) दर सामान्यतः किस स्तर पर रखी जाती है?","optionsHi":["रेपो दर से 25 आधार अंक कम","रेपो दर के बराबर","रेपो दर से 25 आधार अंक अधिक","रेपो दर से 100 आधार अंक अधिक"],"explanationHi":"MSF दर वह दर है जिस पर बैंक आपात स्थिति में SLR प्रतिभूतियों के बदले RBI से रातोंरात उधार लेते हैं; यह LAF गलियारे की ऊपरी सीमा बनाती है, जो रेपो दर से 25 आधार अंक अधिक होती है; SDF दर 25 आधार अंक कम होती है।"},
  {"id":"eco-basics-42","question":"Which RBI facility absorbs surplus liquidity from banks without the RBI giving any collateral?","options":["Repo","Reverse repo","Standing Deposit Facility","Marginal Standing Facility"],"answer":2,"explanation":"The SDF, introduced in April 2022, lets banks park funds with the RBI without the RBI providing securities, unlike the reverse repo; it is the floor of the LAF corridor.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"RBI की कौन-सी सुविधा RBI द्वारा कोई गिरवी (संपार्श्विक) दिए बिना बैंकों से अधिशेष तरलता सोख लेती है?","optionsHi":["रेपो","रिवर्स रेपो","स्थायी जमा सुविधा (SDF)","सीमांत स्थायी सुविधा (MSF)"],"explanationHi":"अप्रैल 2022 में शुरू की गई SDF, रिवर्स रेपो के विपरीत, बैंकों को RBI के पास धन रखने देती है जिसके बदले RBI को प्रतिभूतियाँ नहीं देनी पड़तीं; यह LAF गलियारे की निचली सीमा है।"},
  {"id":"eco-basics-43","question":"The Phillips curve shows the relationship between:","options":["Inflation and unemployment","Savings and investment","Interest rate and money demand","Tax rate and tax revenue"],"answer":0,"explanation":"The Phillips curve shows an inverse relationship between inflation and unemployment; the tax rate–revenue relation is the Laffer curve.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"फिलिप्स वक्र किसके बीच संबंध दर्शाता है?","optionsHi":["मुद्रास्फीति और बेरोजगारी","बचत और निवेश","ब्याज दर और मुद्रा की माँग","कर दर और कर राजस्व"],"explanationHi":"फिलिप्स वक्र मुद्रास्फीति और बेरोजगारी के बीच व्युत्क्रम संबंध दर्शाता है; कर दर और राजस्व का संबंध लैफर वक्र दिखाता है।"},
  {"id":"eco-basics-44","question":"The Lorenz curve is used to measure:","options":["Economic growth","Income inequality","Price elasticity","Balance of payments"],"answer":1,"explanation":"The Lorenz curve plots cumulative income against cumulative population; the farther it lies from the 45° line, the greater the inequality (summarised by the Gini coefficient).","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"लॉरेंज वक्र का उपयोग किसे मापने के लिए किया जाता है?","optionsHi":["आर्थिक वृद्धि","आय की असमानता","कीमत लोच","भुगतान संतुलन"],"explanationHi":"लॉरेंज वक्र संचयी आय को संचयी जनसंख्या के सापेक्ष दर्शाता है; यह 45° रेखा से जितना दूर होता है, असमानता उतनी अधिक होती है (जिसे गिनी गुणांक में संक्षेपित किया जाता है)।"},
  {"id":"eco-basics-45","question":"Which of the following is recorded in the current account of India’s balance of payments?","options":["Foreign direct investment","Remittances from Indians abroad","External commercial borrowings by firms","Portfolio investment by FIIs"],"answer":1,"explanation":"The current account covers trade in goods and services, income and transfers such as remittances; FDI, FPI and borrowings are capital (financial) account items.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"निम्नलिखित में से क्या भारत के भुगतान संतुलन के चालू खाते में दर्ज किया जाता है?","optionsHi":["प्रत्यक्ष विदेशी निवेश","विदेश में रहने वाले भारतीयों से प्राप्त प्रेषण","फर्मों द्वारा बाह्य वाणिज्यिक उधारियाँ","FII द्वारा पोर्टफोलियो निवेश"],"explanationHi":"चालू खाते में वस्तुओं और सेवाओं का व्यापार, आय तथा प्रेषण जैसे अंतरण शामिल होते हैं; FDI, FPI और उधारियाँ पूँजी (वित्तीय) खाते की मदें हैं।"},
  {"id":"eco-basics-46","question":"By the expenditure method, with private consumption ₹60 lakh crore, investment ₹20 lakh crore, government spending ₹15 lakh crore, exports ₹10 lakh crore and imports ₹15 lakh crore, GDP is:","options":["₹120 lakh crore","₹90 lakh crore","₹100 lakh crore","₹110 lakh crore"],"answer":1,"explanation":"GDP = C + I + G + (X − M) = 60 + 20 + 15 + (10 − 15) = 90 lakh crore; adding imports instead of subtracting gives the wrong 120.","difficulty":"hard","source":"SSC CGL · UPSC Prelims","questionHi":"व्यय विधि से, निजी उपभोग ₹60 लाख करोड़, निवेश ₹20 लाख करोड़, सरकारी व्यय ₹15 लाख करोड़, निर्यात ₹10 लाख करोड़ और आयात ₹15 लाख करोड़ होने पर GDP है:","optionsHi":["₹120 लाख करोड़","₹90 लाख करोड़","₹100 लाख करोड़","₹110 लाख करोड़"],"explanationHi":"GDP = C + I + G + (X − M) = 60 + 20 + 15 + (10 − 15) = 90 लाख करोड़; आयात को घटाने के बजाय जोड़ने पर गलत उत्तर 120 आता है।"},
  {"id":"eco-basics-47","question":"How many of these statements are correct? I. The repo rate is the rate at which the RBI lends to banks against government securities. II. The reverse repo rate is higher than the repo rate. III. The bank rate is currently aligned with the MSF rate. IV. CRR is maintained by banks in the form of government securities.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong: the reverse repo rate is below the repo rate. IV is wrong: CRR is cash kept with the RBI; it is the SLR that is held in government securities.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"इनमें से कितने कथन सही हैं? I. रेपो दर वह दर है जिस पर RBI सरकारी प्रतिभूतियों के बदले बैंकों को उधार देता है। II. रिवर्स रेपो दर रेपो दर से अधिक होती है। III. बैंक दर वर्तमान में MSF दर के अनुरूप है। IV. CRR बैंकों द्वारा सरकारी प्रतिभूतियों के रूप में रखा जाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। II गलत है: रिवर्स रेपो दर रेपो दर से कम होती है। IV गलत है: CRR RBI के पास रखी गई नकदी है; सरकारी प्रतिभूतियों के रूप में तो SLR रखा जाता है।"},
  {"id":"eco-basics-48","question":"Assertion (A): A rise in the Statutory Liquidity Ratio reduces the lending capacity of banks. Reason (R): SLR requires banks to hold a prescribed share of their net demand and time liabilities in liquid assets such as government securities.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Money locked in SLR assets cannot be lent, so raising the SLR directly shrinks the funds available for credit; R states exactly that mechanism.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"अभिकथन (A): सांविधिक तरलता अनुपात (SLR) में वृद्धि से बैंकों की उधार देने की क्षमता घटती है। कारण (R): SLR के अनुसार बैंकों को अपनी निवल माँग और सावधि देयताओं का एक निर्धारित हिस्सा सरकारी प्रतिभूतियों जैसी तरल परिसंपत्तियों में रखना होता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"SLR परिसंपत्तियों में बँधा धन उधार नहीं दिया जा सकता, इसलिए SLR बढ़ाने से ऋण के लिए उपलब्ध निधि सीधे घटती है; R ठीक यही तंत्र बताता है।"},
  {"id":"eco-basics-49","question":"Match the budget concept with its definition: 1. Revenue deficit 2. Fiscal deficit 3. Primary deficit 4. Effective revenue deficit; a. Fiscal deficit minus interest payments b. Revenue deficit minus grants for creation of capital assets c. Revenue expenditure minus revenue receipts d. Total expenditure minus total non-borrowing receipts","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"Revenue deficit = revenue expenditure − revenue receipts; fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts); primary deficit = fiscal deficit − interest; effective revenue deficit = revenue deficit − grants-in-aid for capital assets.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"बजट की अवधारणा का उसकी परिभाषा से मिलान कीजिए: 1. राजस्व घाटा 2. राजकोषीय घाटा 3. प्राथमिक घाटा 4. प्रभावी राजस्व घाटा; a. राजकोषीय घाटे में से ब्याज भुगतान घटाना b. राजस्व घाटे में से पूँजीगत परिसंपत्तियों के सृजन हेतु अनुदान घटाना c. राजस्व व्यय में से राजस्व प्राप्तियाँ घटाना d. कुल व्यय में से कुल गैर-उधार प्राप्तियाँ घटाना","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-c, 2-d, 3-b, 4-a"],"explanationHi":"राजस्व घाटा = राजस्व व्यय − राजस्व प्राप्तियाँ; राजकोषीय घाटा = कुल व्यय − (राजस्व प्राप्तियाँ + गैर-ऋण पूँजीगत प्राप्तियाँ); प्राथमिक घाटा = राजकोषीय घाटा − ब्याज; प्रभावी राजस्व घाटा = राजस्व घाटा − पूँजीगत परिसंपत्तियों के लिए सहायता अनुदान।"},
  {"id":"eco-basics-50","question":"A government has revenue receipts of ₹20 lakh crore, non-debt capital receipts of ₹2 lakh crore, total expenditure of ₹30 lakh crore and interest payments of ₹8 lakh crore. Its primary deficit is:","options":["₹8 lakh crore","₹10 lakh crore","₹2 lakh crore","Zero"],"answer":3,"explanation":"Fiscal deficit = 30 − (20 + 2) = ₹8 lakh crore; primary deficit = fiscal deficit − interest = 8 − 8 = 0. Forgetting the non-debt capital receipts gives the wrong ₹2 lakh crore.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"किसी सरकार की राजस्व प्राप्तियाँ ₹20 लाख करोड़, गैर-ऋण पूँजीगत प्राप्तियाँ ₹2 लाख करोड़, कुल व्यय ₹30 लाख करोड़ और ब्याज भुगतान ₹8 लाख करोड़ हैं। उसका प्राथमिक घाटा है:","optionsHi":["₹8 लाख करोड़","₹10 लाख करोड़","₹2 लाख करोड़","शून्य"],"explanationHi":"राजकोषीय घाटा = 30 − (20 + 2) = ₹8 लाख करोड़; प्राथमिक घाटा = राजकोषीय घाटा − ब्याज = 8 − 8 = 0। गैर-ऋण पूँजीगत प्राप्तियों को भूल जाने पर गलत उत्तर ₹2 लाख करोड़ आता है।"},
  {"id":"eco-basics-51","question":"How many of these statements about GST are correct? I. The GST Council is a constitutional body under Article 279A. II. In the Council, the Centre’s vote has a weight of one-third and the States together two-thirds. III. GST compensation to States was guaranteed for five years from 1 July 2017. IV. Petrol and diesel are taxed under GST at 28%.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (decisions need a three-fourths weighted majority). IV is wrong: petrol, diesel, ATF, natural gas and crude are outside GST until the Council decides otherwise.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"GST के बारे में इनमें से कितने कथन सही हैं? I. GST परिषद अनुच्छेद 279A के अंतर्गत एक संवैधानिक निकाय है। II. परिषद में केंद्र के मत का भार एक-तिहाई और सभी राज्यों का मिलाकर दो-तिहाई होता है। III. राज्यों को GST क्षतिपूर्ति 1 जुलाई 2017 से पाँच वर्ष के लिए सुनिश्चित की गई थी। IV. पेट्रोल और डीजल पर GST के अंतर्गत 28% कर लगता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं (निर्णयों के लिए तीन-चौथाई भारित बहुमत आवश्यक है)। IV गलत है: जब तक परिषद अन्यथा निर्णय नहीं लेती, पेट्रोल, डीजल, ATF, प्राकृतिक गैस और कच्चा तेल GST से बाहर हैं।"},
  {"id":"eco-basics-52","question":"Which of the following is NOT included in the M1 measure of money supply?","options":["Currency with the public","Demand deposits with banks","Time deposits with banks","Other deposits with the RBI"],"answer":2,"explanation":"M1 (narrow money) = currency with the public + demand deposits + other deposits with the RBI. Time deposits enter only M3 (broad money).","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"निम्नलिखित में से कौन-सा मुद्रा आपूर्ति के M1 माप में शामिल नहीं है?","optionsHi":["जनता के पास मुद्रा","बैंकों में माँग जमाएँ","बैंकों में सावधि जमाएँ","RBI के पास अन्य जमाएँ"],"explanationHi":"M1 (संकीर्ण मुद्रा) = जनता के पास मुद्रा + माँग जमाएँ + RBI के पास अन्य जमाएँ। सावधि जमाएँ केवल M3 (व्यापक मुद्रा) में आती हैं।"},
  {"id":"eco-basics-53","question":"Arrange these events in chronological order: 1. Formation of the State Bank of India 2. Nationalisation of the RBI 3. Launch of the First Five-Year Plan 4. Setting up of the Planning Commission","options":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","4, 3, 2, 1"],"answer":0,"explanation":"RBI nationalised on 1 January 1949; Planning Commission set up in March 1950; First Plan began in April 1951; SBI formed on 1 July 1955.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इन घटनाओं को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. भारतीय स्टेट बैंक का गठन 2. RBI का राष्ट्रीयकरण 3. प्रथम पंचवर्षीय योजना का आरंभ 4. योजना आयोग की स्थापना","optionsHi":["2, 4, 3, 1","4, 2, 3, 1","2, 3, 4, 1","4, 3, 2, 1"],"explanationHi":"RBI का राष्ट्रीयकरण 1 जनवरी 1949 को; योजना आयोग की स्थापना मार्च 1950 में; प्रथम योजना अप्रैल 1951 में शुरू हुई; SBI का गठन 1 जुलाई 1955 को हुआ।"},
  {"id":"eco-basics-54","question":"How many of these statements are correct? I. Frictional unemployment occurs when workers are temporarily between jobs. II. Structural unemployment arises from a mismatch between workers’ skills and available jobs. III. Cyclical unemployment rises during a recession. IV. In disguised unemployment the marginal productivity of the extra workers is zero.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are standard definitions: frictional (search time), structural (skill mismatch), cyclical (demand downturn) and disguised (surplus labour with zero marginal product).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. घर्षणात्मक बेरोजगारी तब होती है जब श्रमिक अस्थायी रूप से एक नौकरी से दूसरी नौकरी के बीच होते हैं। II. संरचनात्मक बेरोजगारी श्रमिकों के कौशल और उपलब्ध नौकरियों के बीच बेमेल से उत्पन्न होती है। III. चक्रीय बेरोजगारी मंदी के दौरान बढ़ती है। IV. प्रच्छन्न बेरोजगारी में अतिरिक्त श्रमिकों की सीमांत उत्पादकता शून्य होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों मानक परिभाषाएँ हैं: घर्षणात्मक (खोज में लगने वाला समय), संरचनात्मक (कौशल का बेमेल), चक्रीय (माँग में गिरावट) और प्रच्छन्न (शून्य सीमांत उत्पादकता वाला अतिरिक्त श्रम)।"},
  {"id":"eco-basics-55","question":"Assertion (A): During a period of high inflation, borrowers gain at the expense of lenders. Reason (R): Inflation reduces the real value of the money that is repaid.","options":["A is true but R is false","Both A and R are true but R does not explain A","Both A and R are true and R explains A","A is false but R is true"],"answer":2,"explanation":"A fixed sum repaid later buys less after inflation, so the lender receives less real value and the borrower effectively repays less; R is precisely the reason.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"अभिकथन (A): उच्च मुद्रास्फीति की अवधि में उधार लेने वालों को उधार देने वालों की कीमत पर लाभ होता है। कारण (R): मुद्रास्फीति चुकाई गई धनराशि के वास्तविक मूल्य को घटा देती है।","optionsHi":["A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बाद में चुकाई गई निश्चित राशि मुद्रास्फीति के बाद कम खरीद पाती है, इसलिए उधार देने वाले को कम वास्तविक मूल्य मिलता है और उधार लेने वाला प्रभावी रूप से कम चुकाता है; R ठीक यही कारण है।"},
  {"id":"eco-basics-56","question":"A country’s GDP at market prices is ₹500 lakh crore, net factor income from abroad is −₹20 lakh crore, depreciation is ₹50 lakh crore and net indirect taxes are ₹30 lakh crore. Its national income (NNP at factor cost) is:","options":["₹400 lakh crore","₹440 lakh crore","₹460 lakh crore","₹480 lakh crore"],"answer":0,"explanation":"GNP = 500 − 20 = 480; NNP at market prices = 480 − 50 = 430; NNP at factor cost = 430 − 30 = 400 lakh crore.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"किसी देश का बाजार कीमतों पर GDP ₹500 लाख करोड़ है, विदेशों से शुद्ध साधन आय −₹20 लाख करोड़ है, मूल्यह्रास ₹50 लाख करोड़ है और शुद्ध अप्रत्यक्ष कर ₹30 लाख करोड़ हैं। उसकी राष्ट्रीय आय (साधन लागत पर NNP) है:","optionsHi":["₹400 लाख करोड़","₹440 लाख करोड़","₹460 लाख करोड़","₹480 लाख करोड़"],"explanationHi":"GNP = 500 − 20 = 480; बाजार कीमतों पर NNP = 480 − 50 = 430; साधन लागत पर NNP = 430 − 30 = 400 लाख करोड़।"},
  {"id":"eco-basics-57","question":"How many of these statements are correct? I. The Fifteenth Finance Commission recommended devolving 41% of the divisible pool of central taxes to the States. II. Corporation tax is a direct tax. III. Customs duty collected by the Union forms part of the divisible pool shared with States. IV. Cesses levied by the Union are part of the divisible pool.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: cesses and surcharges are retained wholly by the Centre and are excluded from the pool shared under Article 270.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. पंद्रहवें वित्त आयोग ने केंद्रीय करों के विभाज्य पूल का 41% राज्यों को हस्तांतरित करने की अनुशंसा की। II. निगम कर एक प्रत्यक्ष कर है। III. संघ द्वारा वसूला गया सीमा शुल्क राज्यों के साथ साझा किए जाने वाले विभाज्य पूल का भाग है। IV. संघ द्वारा लगाए गए उपकर विभाज्य पूल का भाग हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: उपकर और अधिभार पूरी तरह केंद्र के पास रहते हैं और अनुच्छेद 270 के अंतर्गत साझा किए जाने वाले पूल से बाहर रखे जाते हैं।"},
  {"id":"eco-basics-58","question":"Match the publication with the body that releases it: 1. Human Development Report 2. World Economic Outlook 3. Global Competitiveness Report 4. Ease of Doing Business (till 2021); a. World Bank b. IMF c. UNDP d. World Economic Forum","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-a, 3-d, 4-b","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-d, 4-a"],"answer":0,"explanation":"HDR and the HDI come from UNDP, the World Economic Outlook from the IMF, the Global Competitiveness Report from the WEF, and the (discontinued) Doing Business rankings were the World Bank’s.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"प्रकाशन का उसे जारी करने वाले निकाय से मिलान कीजिए: 1. मानव विकास रिपोर्ट 2. विश्व आर्थिक परिदृश्य 3. वैश्विक प्रतिस्पर्धात्मकता रिपोर्ट 4. कारोबार सुगमता (2021 तक); a. विश्व बैंक b. IMF c. UNDP d. विश्व आर्थिक मंच","optionsHi":["1-c, 2-b, 3-d, 4-a","1-c, 2-a, 3-d, 4-b","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-d, 4-a"],"explanationHi":"HDR और HDI UNDP से, विश्व आर्थिक परिदृश्य IMF से, वैश्विक प्रतिस्पर्धात्मकता रिपोर्ट WEF से आती हैं, और (बंद की जा चुकी) कारोबार सुगमता रैंकिंग विश्व बैंक की थीं।"},
  {"id":"eco-basics-59","question":"The economic reforms India began in 1991 are often summed up as “LPG”, which stands for:","options":["Liberalisation, Privatisation and Globalisation","Licensing, Privatisation and Globalisation","Liberalisation, Planning and Globalisation","Liberalisation, Public-sector expansion and Globalisation"],"answer":0,"explanation":"The 1991 reforms (PM P. V. Narasimha Rao, Finance Minister Manmohan Singh) liberalised industry and trade, opened the public sector to private players and integrated India with the world economy.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"भारत में 1991 में शुरू हुए आर्थिक सुधारों को प्रायः “LPG” कहकर संक्षेप में बताया जाता है, जिसका अर्थ है:","optionsHi":["उदारीकरण, निजीकरण और वैश्वीकरण","लाइसेंसिंग, निजीकरण और वैश्वीकरण","उदारीकरण, नियोजन और वैश्वीकरण","उदारीकरण, सार्वजनिक क्षेत्र का विस्तार और वैश्वीकरण"],"explanationHi":"1991 के सुधारों (प्रधानमंत्री पी. वी. नरसिम्हा राव, वित्त मंत्री मनमोहन सिंह) ने उद्योग और व्यापार का उदारीकरण किया, सार्वजनिक क्षेत्र को निजी खिलाड़ियों के लिए खोला और भारत को विश्व अर्थव्यवस्था से जोड़ा।"},
  {"id":"eco-basics-60","question":"Which body regulates the securities (stock) market in India?","options":["RBI","SEBI","IRDAI","PFRDA"],"answer":1,"explanation":"SEBI, set up in 1988 and given statutory powers in 1992, regulates stock exchanges and securities. IRDAI regulates insurance and PFRDA pensions.","difficulty":"easy","source":"SSC GD · RRB Group D","questionHi":"भारत में प्रतिभूति (शेयर) बाजार का विनियमन कौन-सा निकाय करता है?","optionsHi":["RBI","SEBI","IRDAI","PFRDA"],"explanationHi":"SEBI, जिसकी स्थापना 1988 में हुई और 1992 में वैधानिक शक्तियाँ मिलीं, शेयर बाजारों और प्रतिभूतियों का विनियमन करता है। IRDAI बीमा का और PFRDA पेंशन का विनियमन करता है।"},
  {"id":"eco-basics-61","question":"India’s First Five-Year Plan (1951–56) gave the highest priority to:","options":["Heavy and basic capital-goods industries","Defence and border infrastructure","Agriculture, including irrigation","Export promotion to earn foreign exchange"],"answer":2,"explanation":"The First Plan, based on the Harrod–Domar model, focused on agriculture and irrigation after Partition-era food shortages. Heavy industry was the focus of the Second Plan.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"भारत की प्रथम पंचवर्षीय योजना (1951–56) ने सर्वाधिक प्राथमिकता किसे दी?","optionsHi":["भारी और बुनियादी पूँजीगत माल उद्योग","रक्षा और सीमा अवसंरचना","कृषि, सिंचाई सहित","विदेशी मुद्रा अर्जित करने के लिए निर्यात संवर्धन"],"explanationHi":"प्रथम योजना, जो हैरोड–डोमर मॉडल पर आधारित थी, ने विभाजन के समय की खाद्य कमी के बाद कृषि और सिंचाई पर ध्यान दिया। भारी उद्योग द्वितीय योजना का केंद्र था।"},
  {"id":"eco-basics-62","question":"The Second Five-Year Plan, which stressed rapid industrialisation through heavy industries, was based on the model of:","options":["Roy Harrod and Evsey Domar","P. C. Mahalanobis","D. R. Gadgil","W. Arthur Lewis"],"answer":1,"explanation":"The Second Plan (1956–61) followed the Mahalanobis model of building capital-goods industries. The Harrod–Domar model underlay the First Plan.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"द्वितीय पंचवर्षीय योजना, जिसमें भारी उद्योगों के माध्यम से तीव्र औद्योगीकरण पर बल दिया गया, किसके मॉडल पर आधारित थी?","optionsHi":["रॉय हैरोड और एवसी डोमर","पी. सी. महालनोबिस","डी. आर. गाडगिल","डब्ल्यू. आर्थर लुईस"],"explanationHi":"द्वितीय योजना (1956–61) पूँजीगत माल उद्योग खड़े करने के महालनोबिस मॉडल पर चली। हैरोड–डोमर मॉडल प्रथम योजना का आधार था।"},
  {"id":"eco-basics-63","question":"A Gini coefficient of 0 indicates:","options":["Perfect inequality, with one person holding all income","Zero inflation over the reference year","Zero growth in real GDP per capita","Perfect equality of income"],"answer":3,"explanation":"The Gini coefficient runs from 0 (everyone has the same income) to 1 (one person has all the income); it is derived from the Lorenz curve.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"गिनी गुणांक का 0 होना दर्शाता है:","optionsHi":["पूर्ण असमानता, जिसमें एक व्यक्ति के पास सारी आय हो","संदर्भ वर्ष में शून्य मुद्रास्फीति","प्रति व्यक्ति वास्तविक GDP में शून्य वृद्धि","आय की पूर्ण समानता"],"explanationHi":"गिनी गुणांक 0 (सभी की आय समान) से 1 (एक व्यक्ति के पास सारी आय) तक होता है; यह लॉरेंज वक्र से निकाला जाता है।"},
  {"id":"eco-basics-64","question":"Which organisation replaced the General Agreement on Tariffs and Trade (GATT) in 1995?","options":["International Monetary Fund (IMF)","World Bank (IBRD)","World Trade Organization","UN Conference on Trade and Development"],"answer":2,"explanation":"The WTO came into being on 1 January 1995 after the Uruguay Round, replacing GATT (1947). The IMF and World Bank date from the 1944 Bretton Woods conference.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"1995 में टैरिफ एवं व्यापार पर सामान्य समझौते (GATT) का स्थान किस संगठन ने लिया?","optionsHi":["अंतर्राष्ट्रीय मुद्रा कोष (IMF)","विश्व बैंक (IBRD)","विश्व व्यापार संगठन","संयुक्त राष्ट्र व्यापार एवं विकास सम्मेलन"],"explanationHi":"WTO उरुग्वे दौर के बाद 1 जनवरी 1995 को अस्तित्व में आया और इसने GATT (1947) का स्थान लिया। IMF और विश्व बैंक 1944 के ब्रेटन वुड्स सम्मेलन की देन हैं।"},
  {"id":"eco-basics-65","question":"Inflation caused by a rise in the prices of raw materials, wages or fuel is called:","options":["Demand-pull inflation","Cost-push inflation","Stagflation","Deflation"],"answer":1,"explanation":"When production costs rise, firms raise prices: cost-push inflation. Demand-pull inflation comes from too much demand chasing limited goods.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"कच्चे माल, मजदूरी या ईंधन की कीमतों में वृद्धि से उत्पन्न मुद्रास्फीति कहलाती है:","optionsHi":["माँग-जनित मुद्रास्फीति","लागत-जनित मुद्रास्फीति","स्टैगफ्लेशन","अपस्फीति"],"explanationHi":"जब उत्पादन लागत बढ़ती है तो फर्में कीमतें बढ़ा देती हैं: लागत-जनित मुद्रास्फीति। माँग-जनित मुद्रास्फीति सीमित वस्तुओं के पीछे बहुत अधिक माँग से उत्पन्न होती है।"},
  {"id":"eco-basics-66","question":"Gresham’s law in economics states that:","options":["Good money drives bad money out of circulation","Bad money drives good money out of circulation","Supply creates its own demand","The quantity of money determines the price level"],"answer":1,"explanation":"When two forms of money of the same face value circulate, people hoard the more valuable (good) one and spend the debased (bad) one. “Supply creates its own demand” is Say’s law.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अर्थशास्त्र में ग्रेशम का नियम कहता है कि:","optionsHi":["अच्छी मुद्रा बुरी मुद्रा को चलन से बाहर कर देती है","बुरी मुद्रा अच्छी मुद्रा को चलन से बाहर कर देती है","पूर्ति अपनी माँग स्वयं उत्पन्न करती है","मुद्रा की मात्रा मूल्य स्तर को निर्धारित करती है"],"explanationHi":"जब समान अंकित मूल्य वाली मुद्रा के दो रूप चलन में होते हैं, तो लोग अधिक मूल्यवान (अच्छी) मुद्रा को जमा कर लेते हैं और खोटी (बुरी) मुद्रा को खर्च करते हैं। “पूर्ति अपनी माँग स्वयं उत्पन्न करती है” सेय का नियम है।"},
  {"id":"eco-basics-67","question":"Goods whose demand rises when their price rises, typically cheap staple foods consumed by very poor households, are called:","options":["Veblen goods","Giffen goods","Normal goods","Complementary goods"],"answer":1,"explanation":"Giffen goods are inferior staples: a price rise makes the poor too poor to afford better food, so they buy more of the staple. Veblen goods also defy the law of demand, but they are luxury status goods.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"वे वस्तुएँ जिनकी कीमत बढ़ने पर माँग बढ़ती है, जो प्रायः बहुत गरीब परिवारों द्वारा उपभोग किए जाने वाले सस्ते मुख्य खाद्य पदार्थ होते हैं, कहलाती हैं:","optionsHi":["वेब्लेन वस्तुएँ","गिफिन वस्तुएँ","सामान्य वस्तुएँ","पूरक वस्तुएँ"],"explanationHi":"गिफिन वस्तुएँ निकृष्ट मुख्य खाद्य पदार्थ होती हैं: कीमत बढ़ने से गरीब बेहतर भोजन खरीदने में असमर्थ हो जाते हैं, इसलिए वे उस मुख्य खाद्य को और अधिक खरीदते हैं। वेब्लेन वस्तुएँ भी माँग के नियम का उल्लंघन करती हैं, परंतु वे प्रतिष्ठा-सूचक विलासिता की वस्तुएँ हैं।"},
  {"id":"eco-basics-68","question":"A devaluation of the rupee generally makes:","options":["Exports cheaper abroad and imports costlier at home","Both exports and imports cheaper for Indian traders","Exports costlier abroad and imports cheaper at home","No change, since prices adjust at once to offset it"],"answer":0,"explanation":"After devaluation a dollar buys more rupees, so Indian goods become cheaper abroad while foreign goods cost more rupees at home.","difficulty":"hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"रुपये के अवमूल्यन से सामान्यतः:","optionsHi":["निर्यात विदेश में सस्ते और आयात देश में महँगे हो जाते हैं","निर्यात और आयात दोनों भारतीय व्यापारियों के लिए सस्ते हो जाते हैं","निर्यात विदेश में महँगे और आयात देश में सस्ते हो जाते हैं","कोई परिवर्तन नहीं होता, क्योंकि कीमतें तुरंत समायोजित होकर इसे संतुलित कर देती हैं"],"explanationHi":"अवमूल्यन के बाद एक डॉलर से अधिक रुपये मिलते हैं, इसलिए भारतीय वस्तुएँ विदेश में सस्ती हो जाती हैं जबकि विदेशी वस्तुओं के लिए देश में अधिक रुपये देने पड़ते हैं।"},
  {"id":"eco-basics-69","question":"The official poverty estimate of 21.9% for India in 2011–12 was based on the methodology of which committee?","options":["Lakdawala Committee","Rangarajan Committee","Alagh Committee","Tendulkar Committee"],"answer":3,"explanation":"The Planning Commission’s 2011–12 estimate of 21.9% used the Tendulkar methodology. The Rangarajan Committee (2014) proposed a higher line giving 29.5%, but it was not formally adopted.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"2011–12 में भारत के लिए 21.9% का आधिकारिक गरीबी अनुमान किस समिति की कार्यप्रणाली पर आधारित था?","optionsHi":["लकड़ावाला समिति","रंगराजन समिति","अलघ समिति","तेंदुलकर समिति"],"explanationHi":"योजना आयोग के 2011–12 के 21.9% के अनुमान में तेंदुलकर कार्यप्रणाली का उपयोग हुआ था। रंगराजन समिति (2014) ने ऊँची रेखा का प्रस्ताव दिया जिससे 29.5% आता था, परंतु उसे औपचारिक रूप से अपनाया नहीं गया।"},
  {"id":"eco-basics-70","question":"The term “twin deficit” refers to an economy running:","options":["A revenue deficit and a primary deficit in the same year","A fiscal deficit and a current account deficit together","A trade deficit and a services deficit together","A budget deficit in two consecutive financial years"],"answer":1,"explanation":"Twin deficits mean the government spends more than it earns (fiscal deficit) while the country spends more abroad than it earns (current account deficit).","difficulty":"hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"“जुड़वाँ घाटा” शब्द ऐसी अर्थव्यवस्था को संदर्भित करता है जिसमें एक साथ चल रहा हो:","optionsHi":["एक ही वर्ष में राजस्व घाटा और प्राथमिक घाटा","राजकोषीय घाटा और चालू खाता घाटा साथ-साथ","व्यापार घाटा और सेवा घाटा साथ-साथ","लगातार दो वित्त वर्षों में बजट घाटा"],"explanationHi":"जुड़वाँ घाटे का अर्थ है कि सरकार अपनी आय से अधिक खर्च करती है (राजकोषीय घाटा) और साथ ही देश विदेश में अपनी कमाई से अधिक खर्च करता है (चालू खाता घाटा)।"},
  {"id":"eco-basics-71","question":"In Indian planning, the period of “Plan Holiday”, when annual plans replaced a five-year plan, was:","options":["1962–65","1985–87","1966–69","1978–80"],"answer":2,"explanation":"After the Third Plan (1961–66), war and drought led to three annual plans in 1966–69. 1978–80 was the Janata government’s “rolling plan”, a different arrangement.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारतीय नियोजन में “योजना अवकाश” की अवधि, जब पंचवर्षीय योजना की जगह वार्षिक योजनाएँ चलीं, थी:","optionsHi":["1962–65","1985–87","1966–69","1978–80"],"explanationHi":"तृतीय योजना (1961–66) के बाद युद्ध और सूखे के कारण 1966–69 में तीन वार्षिक योजनाएँ चलीं। 1978–80 जनता सरकार की “अनवरत योजना” थी, जो एक भिन्न व्यवस्था थी।"},
  {"id":"eco-basics-72","question":"In India, an investment of 10% or more of the post-issue equity of a listed company by a foreign investor is classified as:","options":["Foreign portfolio investment","Foreign direct investment","External commercial borrowing","A non-resident deposit"],"answer":1,"explanation":"Following the Mayaram Committee, the 10% line separates FDI (a lasting interest) from FPI (below 10% in a listed company).","difficulty":"hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"भारत में किसी विदेशी निवेशक द्वारा सूचीबद्ध कंपनी की निर्गम-पश्चात इक्विटी के 10% या अधिक में किया गया निवेश किस रूप में वर्गीकृत किया जाता है?","optionsHi":["विदेशी पोर्टफोलियो निवेश","प्रत्यक्ष विदेशी निवेश","बाह्य वाणिज्यिक उधारी","अनिवासी जमा"],"explanationHi":"मयाराम समिति के बाद, 10% की सीमा FDI (स्थायी हित) को FPI (सूचीबद्ध कंपनी में 10% से कम) से अलग करती है।"},
  {"id":"eco-basics-73","question":"How many of these are direct taxes in India? I. Corporation tax II. Customs duty III. Securities transaction tax IV. Capital gains tax","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Corporation tax, securities transaction tax and capital gains tax are direct taxes administered by the CBDT. Customs duty is an indirect tax under the CBIC. STT is the usual trap.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इनमें से कितने भारत में प्रत्यक्ष कर हैं? I. निगम कर II. सीमा शुल्क III. प्रतिभूति लेनदेन कर IV. पूँजीगत लाभ कर","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"निगम कर, प्रतिभूति लेनदेन कर और पूँजीगत लाभ कर प्रत्यक्ष कर हैं जिनका प्रशासन CBDT करता है। सीमा शुल्क CBIC के अंतर्गत एक अप्रत्यक्ष कर है। STT आम जाल है।"},
  {"id":"eco-basics-74","question":"Assertion (A): Indirect taxes are generally regressive. Reason (R): An indirect tax on a good is the same for every buyer, so it takes a larger share of a poor person’s income than of a rich person’s.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Everyone pays the same tax on, say, a packet of salt, which is a bigger fraction of a low income. R correctly explains why A is true.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): अप्रत्यक्ष कर सामान्यतः प्रतिगामी होते हैं। कारण (R): किसी वस्तु पर अप्रत्यक्ष कर प्रत्येक खरीदार के लिए समान होता है, इसलिए वह गरीब व्यक्ति की आय का अमीर व्यक्ति की आय की तुलना में बड़ा हिस्सा लेता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"नमक के एक पैकेट जैसी वस्तु पर सब समान कर देते हैं, जो कम आय का बड़ा अंश होता है। R सही ढंग से बताता है कि A सत्य क्यों है।"},
  {"id":"eco-basics-75","question":"Match the term with its meaning: 1. Demand-pull inflation 2. Cost-push inflation 3. Stagflation 4. Disinflation; a. A fall in the rate of inflation b. Excess aggregate demand pushing up prices c. Rising input costs pushing up prices d. High inflation along with stagnant output","options":["1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-b, 2-d, 3-c, 4-a"],"answer":0,"explanation":"Disinflation means prices still rise but more slowly; it differs from deflation, where the price level itself falls.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"शब्द का उसके अर्थ से मिलान कीजिए: 1. माँग-जनित मुद्रास्फीति 2. लागत-जनित मुद्रास्फीति 3. स्टैगफ्लेशन 4. विस्फीति; a. मुद्रास्फीति की दर में गिरावट b. अतिरिक्त समग्र माँग द्वारा कीमतों का बढ़ना c. बढ़ती आगत लागतों द्वारा कीमतों का बढ़ना d. ठहरे हुए उत्पादन के साथ उच्च मुद्रास्फीति","optionsHi":["1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-b, 2-d, 3-c, 4-a"],"explanationHi":"विस्फीति का अर्थ है कि कीमतें अब भी बढ़ती हैं पर धीमी गति से; यह अपस्फीति से भिन्न है, जिसमें मूल्य स्तर स्वयं गिरता है।"},
  {"id":"eco-basics-76","question":"Nominal GDP rises from ₹200 lakh crore to ₹264 lakh crore in a year while the GDP deflator rises from 100 to 120. The growth of real GDP is:","options":["32%","12%","10%","20%"],"answer":2,"explanation":"Real GDP in the second year = 264 ÷ 1.20 = ₹220 lakh crore. Growth = (220 − 200) ÷ 200 = 10%. 32% is the nominal growth and 12% is the trap of simple subtraction (32 − 20).","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims","questionHi":"एक वर्ष में सांकेतिक GDP ₹200 लाख करोड़ से बढ़कर ₹264 लाख करोड़ हो जाती है, जबकि GDP अपस्फीतिकारक 100 से बढ़कर 120 हो जाता है। वास्तविक GDP की वृद्धि है:","optionsHi":["32%","12%","10%","20%"],"explanationHi":"दूसरे वर्ष में वास्तविक GDP = 264 ÷ 1.20 = ₹220 लाख करोड़। वृद्धि = (220 − 200) ÷ 200 = 10%। 32% सांकेतिक वृद्धि है और 12% सीधे घटाने (32 − 20) का जाल है।"},
  {"id":"eco-basics-77","question":"How many of these statements about MGNREGA are correct? I. It was enacted in 2005. II. It guarantees 100 days of wage employment in a financial year to every rural household whose adults volunteer for unskilled manual work. III. At least one-third of the beneficiaries are to be women. IV. Unemployment allowance is paid by the Central Government.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: the unemployment allowance is the liability of the State Government, while the Centre bears the full cost of unskilled wages.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"MGNREGA के बारे में इनमें से कितने कथन सही हैं? I. यह 2005 में अधिनियमित हुआ। II. यह प्रत्येक ग्रामीण परिवार को, जिसके वयस्क सदस्य अकुशल शारीरिक कार्य करने के इच्छुक हों, एक वित्त वर्ष में 100 दिन के मजदूरी रोजगार की गारंटी देता है। III. कम से कम एक-तिहाई लाभार्थी महिलाएँ होनी चाहिए। IV. बेरोजगारी भत्ता केंद्र सरकार देती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: बेरोजगारी भत्ता राज्य सरकार का दायित्व है, जबकि अकुशल मजदूरी की पूरी लागत केंद्र वहन करता है।"},
  {"id":"eco-basics-78","question":"Which of the following is NOT recorded in the current account of India’s balance of payments?","options":["Export of software services","Remittances from Indians working abroad","Foreign direct investment inflows","Interest paid on external loans"],"answer":2,"explanation":"The current account covers goods, services, primary income (such as interest) and transfers (such as remittances). FDI is an investment flow recorded in the capital/financial account.","difficulty":"very-hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"निम्नलिखित में से क्या भारत के भुगतान संतुलन के चालू खाते में दर्ज नहीं किया जाता?","optionsHi":["सॉफ्टवेयर सेवाओं का निर्यात","विदेश में कार्यरत भारतीयों से प्राप्त प्रेषण","प्रत्यक्ष विदेशी निवेश का अंतर्वाह","बाह्य ऋणों पर चुकाया गया ब्याज"],"explanationHi":"चालू खाते में वस्तुएँ, सेवाएँ, प्राथमिक आय (जैसे ब्याज) और अंतरण (जैसे प्रेषण) शामिल होते हैं। FDI एक निवेश प्रवाह है जो पूँजी/वित्तीय खाते में दर्ज होता है।"},
  {"id":"eco-basics-79","question":"Arrange in chronological order: 1. Establishment of the WTO 2. Bretton Woods conference 3. Launch of GST in India 4. India’s new economic policy (LPG reforms)","options":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"answer":0,"explanation":"Bretton Woods 1944 → LPG reforms 1991 → WTO 1995 → GST 2017.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. WTO की स्थापना 2. ब्रेटन वुड्स सम्मेलन 3. भारत में GST का आरंभ 4. भारत की नई आर्थिक नीति (LPG सुधार)","optionsHi":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"explanationHi":"ब्रेटन वुड्स 1944 → LPG सुधार 1991 → WTO 1995 → GST 2017।"},
  {"id":"eco-basics-80","question":"Assertion (A): A cut in the cash reserve ratio increases the lending capacity of banks. Reason (R): The RBI pays banks a high rate of interest on their CRR balances.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: a lower CRR frees deposits for lending. R is false: the RBI pays no interest on CRR balances, which is why banks prefer a lower CRR.","difficulty":"very-hard","source":"IBPS PO · SBI PO · UPSC Prelims","questionHi":"अभिकथन (A): नकद आरक्षित अनुपात में कटौती से बैंकों की उधार देने की क्षमता बढ़ती है। कारण (R): RBI बैंकों को उनके CRR शेष पर उच्च ब्याज दर देता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A सत्य है: कम CRR जमाओं को उधार देने के लिए मुक्त करता है। R असत्य है: RBI CRR शेष पर कोई ब्याज नहीं देता, इसीलिए बैंक कम CRR को पसंद करते हैं।"},
  {"id":"eco-basics-81","question":"How many of these statements are correct? I. Firms under perfect competition are price takers. II. A monopolist is always a price taker. III. Under oligopoly, each firm takes its decisions independently of its rivals. IV. Products under monopolistic competition are differentiated.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and IV are correct. A monopolist is a price maker, and oligopolists are interdependent: each watches and reacts to its few rivals.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. पूर्ण प्रतिस्पर्धा में फर्में कीमत स्वीकारक होती हैं। II. एकाधिकारी सदैव कीमत स्वीकारक होता है। III. अल्पाधिकार में प्रत्येक फर्म अपने प्रतिद्वंद्वियों से स्वतंत्र होकर निर्णय लेती है। IV. एकाधिकारी प्रतिस्पर्धा में उत्पाद विभेदित होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और IV सही हैं। एकाधिकारी कीमत निर्धारक होता है, और अल्पाधिकारी एक-दूसरे पर निर्भर होते हैं: प्रत्येक अपने थोड़े-से प्रतिद्वंद्वियों पर नजर रखता है और प्रतिक्रिया देता है।"},
  {"id":"eco-basics-82","question":"If the marginal propensity to consume is 0.8, an increase in investment of ₹100 crore will raise national income by:","options":["₹80 crore","₹125 crore","₹500 crore","₹400 crore"],"answer":2,"explanation":"Investment multiplier = 1 ÷ (1 − MPC) = 1 ÷ 0.2 = 5. Increase in income = 5 × 100 = ₹500 crore.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"यदि सीमांत उपभोग प्रवृत्ति 0.8 है, तो ₹100 करोड़ के निवेश में वृद्धि से राष्ट्रीय आय में कितनी वृद्धि होगी?","optionsHi":["₹80 करोड़","₹125 करोड़","₹500 करोड़","₹400 करोड़"],"explanationHi":"निवेश गुणक = 1 ÷ (1 − MPC) = 1 ÷ 0.2 = 5। आय में वृद्धि = 5 × 100 = ₹500 करोड़।"},
  {"id":"eco-basics-83","question":"How many of the following are used in calculating UNDP’s Human Development Index? I. Life expectancy at birth II. Mean years of schooling III. Expected years of schooling IV. Gross national income per capita (PPP) V. Poverty headcount ratio","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"HDI combines health (life expectancy), education (mean and expected years of schooling) and standard of living (GNI per capita at PPP). Poverty is measured separately by the Multidimensional Poverty Index.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"निम्नलिखित में से कितने UNDP के मानव विकास सूचकांक की गणना में प्रयुक्त होते हैं? I. जन्म के समय जीवन प्रत्याशा II. विद्यालयी शिक्षा के औसत वर्ष III. विद्यालयी शिक्षा के अपेक्षित वर्ष IV. प्रति व्यक्ति सकल राष्ट्रीय आय (PPP) V. गरीबी गणना अनुपात","optionsHi":["केवल दो","केवल तीन","केवल चार","सभी पाँच"],"explanationHi":"HDI स्वास्थ्य (जीवन प्रत्याशा), शिक्षा (विद्यालयी शिक्षा के औसत और अपेक्षित वर्ष) तथा जीवन स्तर (PPP पर प्रति व्यक्ति GNI) को मिलाता है। गरीबी को बहुआयामी गरीबी सूचकांक द्वारा अलग से मापा जाता है।"},
  {"id":"eco-basics-84","question":"Agriculture, fishing, forestry and mining belong to which sector of the economy?","options":["Secondary sector","Tertiary sector","Quaternary sector","Primary sector"],"answer":3,"explanation":"The primary sector draws goods directly from nature. Manufacturing and construction form the secondary sector, and services such as banking and transport the tertiary sector.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"कृषि, मत्स्य पालन, वानिकी और खनन अर्थव्यवस्था के किस क्षेत्र से संबंधित हैं?","optionsHi":["द्वितीयक क्षेत्र","तृतीयक क्षेत्र","चतुर्थक क्षेत्र","प्राथमिक क्षेत्र"],"explanationHi":"प्राथमिक क्षेत्र वस्तुएँ सीधे प्रकृति से प्राप्त करता है। विनिर्माण और निर्माण द्वितीयक क्षेत्र बनाते हैं, और बैंकिंग व परिवहन जैसी सेवाएँ तृतीयक क्षेत्र।"},
  {"id":"eco-basics-85","question":"According to the law of demand, other things remaining the same, when the price of a good falls its quantity demanded:","options":["Falls","Stays the same","First falls and then rises","Rises"],"answer":3,"explanation":"Price and quantity demanded move in opposite directions, so the demand curve slopes downward. Giffen goods are the rare exception.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"माँग के नियम के अनुसार, अन्य बातें समान रहने पर, जब किसी वस्तु की कीमत गिरती है तो उसकी माँगी गई मात्रा:","optionsHi":["घटती है","समान रहती है","पहले घटती है और फिर बढ़ती है","बढ़ती है"],"explanationHi":"कीमत और माँगी गई मात्रा विपरीत दिशाओं में चलती हैं, इसलिए माँग वक्र नीचे की ओर ढलान वाला होता है। गिफिन वस्तुएँ दुर्लभ अपवाद हैं।"},
  {"id":"eco-basics-86","question":"The Economic Survey of India, presented just before the Union Budget, is prepared under the guidance of the:","options":["Comptroller and Auditor General","Governor of the RBI","Chairman of NITI Aayog","Chief Economic Adviser"],"answer":3,"explanation":"The Economic Division of the Department of Economic Affairs (Ministry of Finance) prepares the Survey under the Chief Economic Adviser, and the Finance Minister tables it in Parliament.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"केंद्रीय बजट से ठीक पहले प्रस्तुत किया जाने वाला भारत का आर्थिक सर्वेक्षण किसके मार्गदर्शन में तैयार किया जाता है?","optionsHi":["नियंत्रक एवं महालेखा परीक्षक","RBI के गवर्नर","नीति आयोग के अध्यक्ष","मुख्य आर्थिक सलाहकार"],"explanationHi":"आर्थिक कार्य विभाग (वित्त मंत्रालय) का आर्थिक प्रभाग मुख्य आर्थिक सलाहकार के अंतर्गत सर्वेक्षण तैयार करता है, और वित्त मंत्री इसे संसद में प्रस्तुत करते हैं।"},
  {"id":"eco-basics-87","question":"Engel’s law states that as a household’s income rises:","options":["The share of income spent on food falls","The demand for luxuries falls","The share of income that is saved falls","The amount spent on food in rupees falls"],"answer":0,"explanation":"The amount spent on food may still rise, but it rises more slowly than income, so the share of income going to food falls. This is why a falling food share is used as a sign of rising living standards.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"एंजेल का नियम कहता है कि जैसे-जैसे परिवार की आय बढ़ती है:","optionsHi":["खाद्य पर खर्च होने वाली आय का हिस्सा घटता है","विलासिता की वस्तुओं की माँग घटती है","बचाई जाने वाली आय का हिस्सा घटता है","खाद्य पर रुपयों में किया गया खर्च घटता है"],"explanationHi":"खाद्य पर खर्च की राशि फिर भी बढ़ सकती है, परंतु वह आय से धीमी गति से बढ़ती है, इसलिए खाद्य पर जाने वाली आय का हिस्सा घटता है। इसीलिए खाद्य के घटते हिस्से को जीवन स्तर में सुधार का संकेत माना जाता है।"},
  {"id":"eco-basics-88","question":"A vertical demand curve shows that the price elasticity of demand is:","options":["Equal to one","Zero","Infinite","Greater than one"],"answer":1,"explanation":"A vertical curve means the same quantity is bought at every price, so demand is perfectly inelastic (elasticity zero). A horizontal demand curve is the one with infinite elasticity.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"ऊर्ध्वाधर माँग वक्र दर्शाता है कि माँग की कीमत लोच है:","optionsHi":["एक के बराबर","शून्य","अनंत","एक से अधिक"],"explanationHi":"ऊर्ध्वाधर वक्र का अर्थ है कि हर कीमत पर समान मात्रा खरीदी जाती है, इसलिए माँग पूर्णतः बेलोचदार है (लोच शून्य)। क्षैतिज माँग वक्र की लोच अनंत होती है।"},
  {"id":"eco-basics-89","question":"The opportunity cost of a choice is:","options":["The value of the next best alternative given up","The total value of all the alternatives given up","The extra cost of producing one more unit of output","The money paid for the chosen item"],"answer":0,"explanation":"Opportunity cost is the value of the best option forgone, not of all options. The cost of one more unit is marginal cost.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"किसी चयन की अवसर लागत है:","optionsHi":["छोड़े गए अगले सर्वोत्तम विकल्प का मूल्य","छोड़े गए सभी विकल्पों का कुल मूल्य","उत्पादन की एक और इकाई बनाने की अतिरिक्त लागत","चुनी गई वस्तु के लिए चुकाया गया धन"],"explanationHi":"अवसर लागत छोड़े गए सर्वोत्तम विकल्प का मूल्य है, सभी विकल्पों का नहीं। एक और इकाई की लागत सीमांत लागत है।"},
  {"id":"eco-basics-90","question":"A good whose demand falls when consumers’ income rises is called a:","options":["Normal good","Complementary good","Luxury good","Inferior good"],"answer":3,"explanation":"With higher income people switch from inferior goods (for example coarse grains) to better substitutes. For normal and luxury goods demand rises with income. A Giffen good is a special kind of inferior good.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"वह वस्तु जिसकी माँग उपभोक्ताओं की आय बढ़ने पर घटती है, कहलाती है:","optionsHi":["सामान्य वस्तु","पूरक वस्तु","विलासिता की वस्तु","निकृष्ट वस्तु"],"explanationHi":"आय बढ़ने पर लोग निकृष्ट वस्तुओं (जैसे मोटे अनाज) से बेहतर स्थानापन्न वस्तुओं की ओर चले जाते हैं। सामान्य और विलासिता की वस्तुओं की माँग आय के साथ बढ़ती है। गिफिन वस्तु एक विशेष प्रकार की निकृष्ट वस्तु है।"},
  {"id":"eco-basics-91","question":"In India, fiscal policy (decisions on taxation and government spending) is decided by the:","options":["NITI Aayog","Securities and Exchange Board of India","Reserve Bank of India's Monetary Policy Committee","Union Government, via the Finance Ministry"],"answer":3,"explanation":"Fiscal policy is set by the government and voted through the Budget. Monetary policy (interest rates and money supply) is the RBI’s job, and NITI Aayog is a policy think tank.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"भारत में राजकोषीय नीति (कराधान और सरकारी व्यय संबंधी निर्णय) कौन तय करता है?","optionsHi":["नीति आयोग","भारतीय प्रतिभूति और विनिमय बोर्ड","भारतीय रिज़र्व बैंक की मौद्रिक नीति समिति","केंद्र सरकार, वित्त मंत्रालय के माध्यम से"],"explanationHi":"राजकोषीय नीति सरकार तय करती है और बजट के माध्यम से पारित की जाती है। मौद्रिक नीति (ब्याज दरें और मुद्रा आपूर्ति) RBI का कार्य है, और नीति आयोग एक नीतिगत थिंक टैंक है।"},
  {"id":"eco-basics-92","question":"The term ‘demographic dividend’ refers to:","options":["Profits earned from population-control programmes","Extra tax revenue that a growing population brings","Remittances sent home by emigrant workers","Growth potential from a large working-age share"],"answer":3,"explanation":"When the share of people aged about 15–64 is high and dependants are few, more workers and savings can speed growth, if there are jobs and skills for them. India is in this phase now.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL","questionHi":"‘जनांकिकीय लाभांश’ शब्द का अर्थ है:","optionsHi":["जनसंख्या नियंत्रण कार्यक्रमों से अर्जित लाभ","बढ़ती जनसंख्या से मिलने वाला अतिरिक्त कर राजस्व","प्रवासी श्रमिकों द्वारा घर भेजा गया प्रेषण","कार्यशील आयु वर्ग के बड़े हिस्से से मिलने वाली संवृद्धि की संभावना"],"explanationHi":"जब लगभग 15–64 वर्ष आयु के लोगों का हिस्सा अधिक और आश्रित कम होते हैं, तो अधिक श्रमिक और बचत वृद्धि को गति दे सकते हैं, बशर्ते उनके लिए रोजगार और कौशल हों। भारत अभी इसी चरण में है।"},
  {"id":"eco-basics-93","question":"The price of a good rises from ₹10 to ₹12 and its quantity demanded falls from 100 units to 90 units. The price elasticity of demand (in absolute value) is:","options":["0.2","0.5","1.0","2.0"],"answer":1,"explanation":"Change in quantity = −10/100 = −10%; change in price = 2/10 = 20%. Elasticity = 10% ÷ 20% = 0.5, so demand is inelastic. Inverting the ratio gives the trap answer 2.0.","difficulty":"hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"किसी वस्तु की कीमत ₹10 से बढ़कर ₹12 हो जाती है और उसकी माँगी गई मात्रा 100 इकाई से घटकर 90 इकाई रह जाती है। माँग की कीमत लोच (निरपेक्ष मान में) है:","optionsHi":["0.2","0.5","1.0","2.0"],"explanationHi":"मात्रा में परिवर्तन = −10/100 = −10%; कीमत में परिवर्तन = 2/10 = 20%। लोच = 10% ÷ 20% = 0.5, अतः माँग बेलोचदार है। अनुपात को उलट देने पर जाल वाला उत्तर 2.0 आता है।"},
  {"id":"eco-basics-94","question":"Under the GST rate rationalisation that took effect on 22 September 2025, the main GST slabs became:","options":["5%, 12%, 18% and 28%, plus compensation cess","5% and 18%, plus a special 40% rate","12% and 28% only, with cess on luxury goods","A single standard rate of 18% on all goods"],"answer":1,"explanation":"The GST Council in September 2025 cut the four main slabs (5, 12, 18, 28%) to two, 5% and 18%, and set a special 40% rate for items such as tobacco products and luxury goods.","difficulty":"hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"22 सितंबर 2025 से प्रभावी GST दर युक्तिकरण के अंतर्गत मुख्य GST स्लैब हो गए:","optionsHi":["5%, 12%, 18% और 28%, साथ में क्षतिपूर्ति उपकर","5% और 18%, साथ में विशेष 40% की दर","केवल 12% और 28%, विलासिता की वस्तुओं पर उपकर के साथ","सभी वस्तुओं पर 18% की एकल मानक दर"],"explanationHi":"सितंबर 2025 में GST परिषद ने चार मुख्य स्लैब (5, 12, 18, 28%) घटाकर दो, 5% और 18%, कर दिए और तंबाकू उत्पादों व विलासिता की वस्तुओं जैसी मदों के लिए विशेष 40% की दर तय की।"},
  {"id":"eco-basics-95","question":"‘Crowding out’ in economics means that:","options":["Government borrowing lifts interest rates, cutting private investment","Large firms use their scale to drive small firms out of business","Cheap imports push domestic producers out of the home market","Rural workers migrate to cities faster than new jobs are created there"],"answer":0,"explanation":"When the government borrows heavily from the market it competes with private borrowers for loanable funds, pushing up interest rates so that some private investment is dropped.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"अर्थशास्त्र में ‘क्राउडिंग आउट’ (भीड़ बाहर करना) का अर्थ है कि:","optionsHi":["सरकारी उधारी ब्याज दरें बढ़ाकर निजी निवेश घटा देती है","बड़ी फर्में अपने पैमाने के बल पर छोटी फर्मों को व्यवसाय से बाहर कर देती हैं","सस्ते आयात घरेलू उत्पादकों को घरेलू बाजार से बाहर कर देते हैं","ग्रामीण श्रमिक नई नौकरियाँ बनने से अधिक तेजी से शहरों की ओर पलायन करते हैं"],"explanationHi":"जब सरकार बाजार से भारी उधार लेती है तो वह ऋण योग्य निधि के लिए निजी उधारकर्ताओं से प्रतिस्पर्धा करती है, जिससे ब्याज दरें बढ़ जाती हैं और कुछ निजी निवेश छोड़ दिए जाते हैं।"},
  {"id":"eco-basics-96","question":"A ‘liquidity trap’ is a situation in which:","options":["Inflation is so high that people refuse to hold money at all","The government cannot find buyers for its bonds at any yield","Banks hold too little cash to meet a sudden rush of depositors' withdrawals","Interest rates are near zero, so extra money fails to raise spending"],"answer":3,"explanation":"Keynes described how, near a zero interest rate, people prefer to hold any extra money, so monetary policy loses its power and fiscal policy is needed. A bank running short of cash is a liquidity crisis, a different idea.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"‘तरलता जाल’ वह स्थिति है जिसमें:","optionsHi":["मुद्रास्फीति इतनी अधिक होती है कि लोग मुद्रा रखने से ही मना कर देते हैं","सरकार को अपने बॉन्डों के लिए किसी भी प्रतिफल पर खरीदार नहीं मिलते","जमाकर्ताओं की अचानक निकासी की भीड़ के लिए बैंकों के पास नकदी बहुत कम होती है","ब्याज दरें शून्य के निकट होती हैं, इसलिए अतिरिक्त मुद्रा व्यय नहीं बढ़ा पाती"],"explanationHi":"कीन्स ने बताया कि शून्य ब्याज दर के निकट लोग कोई भी अतिरिक्त मुद्रा अपने पास रखना पसंद करते हैं, इसलिए मौद्रिक नीति अपनी शक्ति खो देती है और राजकोषीय नीति की आवश्यकता पड़ती है। नकदी की कमी से जूझता बैंक तरलता संकट है, जो एक भिन्न अवधारणा है।"},
  {"id":"eco-basics-97","question":"The ‘paradox of thrift’ suggests that if all households try to save more at the same time:","options":["Interest rates will rise, since consumers borrow less","Total savings will rise in proportion to the higher saving rate","Investment will rise automatically, as banks lend out the extra deposits","Aggregate demand and income may fall, so total savings may not rise"],"answer":3,"explanation":"Higher saving means lower consumption, which cuts demand, output and income; with lower income, total saving may stay the same or even fall. What is prudent for one family can hurt the economy as a whole.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"‘मितव्ययिता का विरोधाभास’ सुझाता है कि यदि सभी परिवार एक ही समय में अधिक बचत करने का प्रयास करें, तो:","optionsHi":["ब्याज दरें बढ़ेंगी, क्योंकि उपभोक्ता कम उधार लेते हैं","कुल बचत ऊँची बचत दर के अनुपात में बढ़ेगी","निवेश स्वतः बढ़ेगा, क्योंकि बैंक अतिरिक्त जमाओं को उधार दे देंगे","समग्र माँग और आय घट सकती है, इसलिए कुल बचत नहीं भी बढ़ सकती"],"explanationHi":"अधिक बचत का अर्थ कम उपभोग है, जो माँग, उत्पादन और आय को घटाता है; आय कम होने पर कुल बचत समान रह सकती है या घट भी सकती है। एक परिवार के लिए जो विवेकपूर्ण है, वह पूरी अर्थव्यवस्था को हानि पहुँचा सकता है।"},
  {"id":"eco-basics-98","question":"A fixed deposit pays 7% interest a year while consumer price inflation is 9%. The approximate real rate of return is:","options":["16%","7%","2%","−2%"],"answer":3,"explanation":"Real return ≈ nominal rate − inflation = 7% − 9% = −2%. The depositor’s money buys less at the end of the year than at the start, even though it has earned interest.","difficulty":"hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"एक सावधि जमा पर प्रति वर्ष 7% ब्याज मिलता है जबकि उपभोक्ता कीमत मुद्रास्फीति 9% है। लगभग वास्तविक प्रतिफल दर क्या है?","optionsHi":["16%","7%","2%","−2%"],"explanationHi":"वास्तविक प्रतिफल ≈ सांकेतिक दर − मुद्रास्फीति = 7% − 9% = −2%। ब्याज कमाने के बावजूद जमाकर्ता का धन वर्ष के अंत में शुरुआत की तुलना में कम खरीद पाता है।"},
  {"id":"eco-basics-99","question":"According to the Periodic Labour Force Survey (PLFS) 2023–24, which sector employs the largest share of India’s workforce?","options":["Construction","Manufacturing (organised and unorganised)","Services, including trade and transport","Agriculture and allied activities"],"answer":3,"explanation":"Agriculture employs about 46% of workers even though it contributes less than a fifth of GVA, while services contribute the largest share of output. This gap is the root of disguised unemployment in farming.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"आवधिक श्रम बल सर्वेक्षण (PLFS) 2023–24 के अनुसार, कौन-सा क्षेत्र भारत के कार्यबल का सबसे बड़ा हिस्सा नियोजित करता है?","optionsHi":["निर्माण","विनिर्माण (संगठित और असंगठित)","सेवाएँ, व्यापार और परिवहन सहित","कृषि और संबद्ध गतिविधियाँ"],"explanationHi":"कृषि लगभग 46% श्रमिकों को रोजगार देती है, जबकि वह GVA में पाँचवें हिस्से से कम योगदान देती है और उत्पादन में सबसे बड़ा हिस्सा सेवाओं का है। यही अंतर कृषि में प्रच्छन्न बेरोजगारी की जड़ है।"},
  {"id":"eco-basics-100","question":"In the Union Budget 2025–26, the Government of India set its fiscal deficit target at:","options":["4.4% of GDP","6.4% of GDP","3.0% of GDP","5.9% of GDP"],"answer":0,"explanation":"The Budget for 2025–26 aimed at a fiscal deficit of 4.4% of GDP, down from 4.8% (revised estimate) in 2024–25. 5.9% and 6.4% were the targets of 2023–24 and 2022–23.","difficulty":"hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"केंद्रीय बजट 2025–26 में भारत सरकार ने अपना राजकोषीय घाटा लक्ष्य कितना निर्धारित किया?","optionsHi":["GDP का 4.4%","GDP का 6.4%","GDP का 3.0%","GDP का 5.9%"],"explanationHi":"2025–26 के बजट में राजकोषीय घाटा GDP का 4.4% रखने का लक्ष्य था, जो 2024–25 के 4.8% (संशोधित अनुमान) से कम है। 5.9% और 6.4% क्रमशः 2023–24 और 2022–23 के लक्ष्य थे।"},
  {"id":"eco-basics-101","question":"‘Hot money’ refers to:","options":["Cash reserves the RBI keeps aside for financial emergencies","Short-term capital that moves across borders chasing higher returns","Income earned from illegal activities and kept hidden from the tax authorities","Counterfeit currency notes circulating in the economy"],"answer":1,"explanation":"Hot money is mainly short-term portfolio flows that rush in when interest rates or returns are attractive and leave just as fast, which can destabilise exchange rates. Black money is the term for illegal income.","difficulty":"hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"‘हॉट मनी’ से तात्पर्य है:","optionsHi":["वित्तीय आपात स्थितियों के लिए RBI द्वारा अलग रखा गया नकद भंडार","ऊँचे प्रतिफल की तलाश में सीमाओं के पार जाने वाली अल्पकालिक पूँजी","अवैध गतिविधियों से अर्जित आय जिसे कर अधिकारियों से छिपाकर रखा जाता है","अर्थव्यवस्था में चलन में जाली नोट"],"explanationHi":"हॉट मनी मुख्यतः अल्पकालिक पोर्टफोलियो प्रवाह है जो ब्याज दरें या प्रतिफल आकर्षक होने पर तेजी से आता है और उतनी ही तेजी से निकल जाता है, जिससे विनिमय दरें अस्थिर हो सकती हैं। अवैध आय के लिए शब्द काला धन है।"},
  {"id":"eco-basics-102","question":"How many of these statements about price elasticity of demand are correct? I. Demand for necessities tends to be inelastic. II. A good with many close substitutes has elastic demand. III. If demand is elastic, a cut in price raises total expenditure on the good. IV. Elasticity is the same at every point on a straight-line, downward-sloping demand curve.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: on a straight-line demand curve elasticity falls from very high near the price axis to zero at the quantity axis, being 1 at the midpoint, even though the slope is constant.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"माँग की कीमत लोच के बारे में इनमें से कितने कथन सही हैं? I. अनिवार्य वस्तुओं की माँग बेलोचदार होती है। II. जिस वस्तु के कई निकट स्थानापन्न हों, उसकी माँग लोचदार होती है। III. यदि माँग लोचदार है, तो कीमत घटाने से उस वस्तु पर कुल व्यय बढ़ता है। IV. सरल रेखीय, नीचे की ओर ढलान वाले माँग वक्र के प्रत्येक बिंदु पर लोच समान होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: सरल रेखीय माँग वक्र पर ढलान स्थिर होने के बावजूद लोच कीमत अक्ष के निकट बहुत अधिक से घटकर मात्रा अक्ष पर शून्य हो जाती है, और मध्य बिंदु पर 1 होती है।"},
  {"id":"eco-basics-103","question":"Assertion (A): Under a progressive income tax, the average tax rate rises as income rises. Reason (R): Under a progressive tax, the marginal tax rate is lower than the average tax rate.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true but R is false. In a progressive system the marginal rate (on the last rupee) is higher than the average rate, and it is exactly this that pulls the average rate up as income grows.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): प्रगतिशील आयकर में, आय बढ़ने के साथ औसत कर दर बढ़ती है। कारण (R): प्रगतिशील कर में सीमांत कर दर औसत कर दर से कम होती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A सत्य है पर R असत्य है। प्रगतिशील प्रणाली में सीमांत दर (अंतिम रुपये पर) औसत दर से अधिक होती है, और ठीक यही आय बढ़ने पर औसत दर को ऊपर खींचती है।"},
  {"id":"eco-basics-104","question":"Match the economist with the idea: 1. Adam Smith 2. J. M. Keynes 3. Thomas Malthus 4. David Ricardo; a. Comparative advantage b. Population tends to outgrow the food supply c. Effective demand determines output and employment d. The ‘invisible hand’ of the market","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-c, 3-a, 4-b"],"answer":1,"explanation":"Smith (Wealth of Nations, 1776) wrote of the invisible hand, Keynes (General Theory, 1936) of effective demand, Malthus of population outrunning food, and Ricardo of comparative advantage in trade.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अर्थशास्त्री का उसके विचार से मिलान कीजिए: 1. एडम स्मिथ 2. जे. एम. कीन्स 3. थॉमस माल्थस 4. डेविड रिकार्डो; a. तुलनात्मक लाभ b. जनसंख्या खाद्य आपूर्ति से आगे बढ़ने की प्रवृत्ति रखती है c. प्रभावी माँग उत्पादन और रोजगार को निर्धारित करती है d. बाजार का ‘अदृश्य हाथ’","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-c, 3-a, 4-b"],"explanationHi":"स्मिथ (वेल्थ ऑफ नेशंस, 1776) ने अदृश्य हाथ, कीन्स (जनरल थ्योरी, 1936) ने प्रभावी माँग, माल्थस ने खाद्य से आगे निकलती जनसंख्या, और रिकार्डो ने व्यापार में तुलनात्मक लाभ के बारे में लिखा।"},
  {"id":"eco-basics-105","question":"In a two-sector economy, consumption is C = 100 + 0.75Y and investment is fixed at ₹150 crore (all figures in ₹ crore). The equilibrium level of national income is:","options":["₹1,000 crore","₹250 crore","₹1,333 crore","₹600 crore"],"answer":0,"explanation":"At equilibrium Y = C + I = 100 + 0.75Y + 150, so 0.25Y = 250 and Y = ₹1,000 crore (autonomous spending 250 × multiplier 4). Dividing by the MPC instead of the MPS gives ₹1,333 crore, ₹250 crore forgets the multiplier, and ₹600 crore multiplies only investment.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"द्वि-क्षेत्रीय अर्थव्यवस्था में उपभोग C = 100 + 0.75Y है और निवेश ₹150 करोड़ पर स्थिर है (सभी आँकड़े ₹ करोड़ में)। राष्ट्रीय आय का संतुलन स्तर है:","optionsHi":["₹1,000 करोड़","₹250 करोड़","₹1,333 करोड़","₹600 करोड़"],"explanationHi":"संतुलन पर Y = C + I = 100 + 0.75Y + 150, अतः 0.25Y = 250 और Y = ₹1,000 करोड़ (स्वायत्त व्यय 250 × गुणक 4)। MPS के बजाय MPC से भाग देने पर ₹1,333 करोड़ आता है, ₹250 करोड़ में गुणक भूल जाया जाता है, और ₹600 करोड़ में केवल निवेश को गुणा किया जाता है।"},
  {"id":"eco-basics-106","question":"Arrange these in chronological order: 1. Nationalisation of 14 major commercial banks 2. Industrial Policy Resolution adopted 3. FEMA enacted to replace FERA 4. High-yielding varieties programme that began the Green Revolution","options":["4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1","2, 4, 1, 3"],"answer":3,"explanation":"The Industrial Policy Resolution came in 1956, the high-yielding varieties programme in 1966, bank nationalisation in July 1969, and the Foreign Exchange Management Act in 1999.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"इन्हें कालक्रम के अनुसार व्यवस्थित कीजिए: 1. 14 प्रमुख वाणिज्यिक बैंकों का राष्ट्रीयकरण 2. औद्योगिक नीति प्रस्ताव अपनाया गया 3. FERA के स्थान पर FEMA अधिनियमित 4. उच्च उपज किस्म कार्यक्रम, जिसने हरित क्रांति की शुरुआत की","optionsHi":["4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1","2, 4, 1, 3"],"explanationHi":"औद्योगिक नीति प्रस्ताव 1956 में आया, उच्च उपज किस्म कार्यक्रम 1966 में, बैंक राष्ट्रीयकरण जुलाई 1969 में, और विदेशी मुद्रा प्रबंधन अधिनियम 1999 में।"},
  {"id":"eco-basics-107","question":"How many of these statements about price indices in India are correct? I. The Wholesale Price Index does not cover services. II. The Consumer Price Index covers both goods and services. III. The GDP deflator covers all goods and services produced in the country. IV. The Wholesale Price Index is compiled and released by the RBI.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: the WPI is released by the Office of the Economic Adviser in the Department for Promotion of Industry and Internal Trade, while CPI is released by the National Statistics Office.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"भारत में मूल्य सूचकांकों के बारे में इनमें से कितने कथन सही हैं? I. थोक मूल्य सूचकांक में सेवाएँ शामिल नहीं होतीं। II. उपभोक्ता मूल्य सूचकांक में वस्तुएँ और सेवाएँ दोनों शामिल होती हैं। III. GDP अपस्फीतिकारक में देश में उत्पादित सभी वस्तुएँ और सेवाएँ शामिल होती हैं। IV. थोक मूल्य सूचकांक का संकलन और प्रकाशन RBI करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: WPI उद्योग संवर्धन और आंतरिक व्यापार विभाग के आर्थिक सलाहकार कार्यालय द्वारा जारी किया जाता है, जबकि CPI राष्ट्रीय सांख्यिकी कार्यालय द्वारा जारी किया जाता है।"},
  {"id":"eco-basics-108","question":"Which of the following would NOT be counted in India’s GDP for the year?","options":["Value of new houses built during the year","Salary paid to a government-school teacher","Value of wheat a farmer grows and keeps for his own family","Price received for selling a five-year-old car"],"answer":3,"explanation":"GDP counts only goods and services produced in the year, so the resale of a used car is excluded (only a dealer’s commission would count). Production for own use, like the farmer’s wheat, is imputed and included.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"निम्नलिखित में से क्या वर्ष के लिए भारत के GDP में नहीं गिना जाएगा?","optionsHi":["वर्ष के दौरान बने नए मकानों का मूल्य","सरकारी विद्यालय के शिक्षक को दिया गया वेतन","किसान द्वारा उगाए और अपने परिवार के लिए रखे गए गेहूँ का मूल्य","पाँच वर्ष पुरानी कार को बेचने पर प्राप्त कीमत"],"explanationHi":"GDP में केवल उसी वर्ष उत्पादित वस्तुएँ और सेवाएँ गिनी जाती हैं, इसलिए पुरानी कार की पुनर्विक्री शामिल नहीं होती (केवल डीलर का कमीशन गिना जाएगा)। स्व-उपभोग के लिए उत्पादन, जैसे किसान का गेहूँ, आरोपित करके शामिल किया जाता है।"},
  {"id":"eco-basics-109","question":"Assertion (A): After a devaluation, a country’s trade balance often worsens at first before it improves. Reason (R): Import bills rise at once because of the higher prices, while export and import volumes take time to adjust.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"This is the J-curve effect: in the short run contracts are fixed and demand is inelastic, so the higher rupee cost of imports widens the deficit; later, cheaper exports and costlier imports change volumes and the balance improves. R explains A.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"अभिकथन (A): अवमूल्यन के बाद किसी देश का व्यापार संतुलन प्रायः पहले बिगड़ता है और फिर सुधरता है। कारण (R): ऊँची कीमतों के कारण आयात बिल तुरंत बढ़ जाता है, जबकि निर्यात और आयात की मात्रा को समायोजित होने में समय लगता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"यह J-वक्र प्रभाव है: अल्पकाल में अनुबंध निश्चित और माँग बेलोचदार होती है, इसलिए आयात की ऊँची रुपया लागत घाटे को बढ़ाती है; बाद में सस्ते निर्यात और महँगे आयात मात्राओं को बदलते हैं और संतुलन सुधरता है। R, A की व्याख्या करता है।"},
  {"id":"eco-basics-110","question":"Match the committee with its subject: 1. Rangarajan Committee (2014) 2. Raja Chelliah Committee (1991) 3. Malhotra Committee (1993) 4. Abid Hussain Committee (1997); a. Small-scale industries b. Insurance sector reforms c. Tax reforms d. Measurement of poverty","options":["1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":0,"explanation":"Rangarajan reviewed poverty estimation, Raja Chelliah recommended tax reforms in 1991, R. N. Malhotra opened up insurance (leading to IRDA), and Abid Hussain studied small-scale industries.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"समिति का उसके विषय से मिलान कीजिए: 1. रंगराजन समिति (2014) 2. राजा चेलैया समिति (1991) 3. मल्होत्रा समिति (1993) 4. आबिद हुसैन समिति (1997); a. लघु उद्योग b. बीमा क्षेत्र सुधार c. कर सुधार d. गरीबी का मापन","optionsHi":["1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"explanationHi":"रंगराजन ने गरीबी आकलन की समीक्षा की, राजा चेलैया ने 1991 में कर सुधारों की अनुशंसा की, आर. एन. मल्होत्रा ने बीमा क्षेत्र को खोला (जिससे IRDA बना), और आबिद हुसैन ने लघु उद्योगों का अध्ययन किया।"},
  {"id":"eco-basics-111","question":"In a year, nominal GDP grows by 12%, the GDP deflator rises by 5% and population grows by 2%. The approximate growth in real per capita income is:","options":["3%","7%","5%","10%"],"answer":2,"explanation":"Real GDP growth ≈ 12% − 5% = 7%; real per capita growth ≈ 7% − 2% = 5%. Stopping at 7% forgets population, and 10% wrongly ignores inflation.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · RBI Grade B","questionHi":"एक वर्ष में सांकेतिक GDP 12% बढ़ता है, GDP अपस्फीतिकारक 5% बढ़ता है और जनसंख्या 2% बढ़ती है। वास्तविक प्रति व्यक्ति आय में लगभग कितनी वृद्धि हुई?","optionsHi":["3%","7%","5%","10%"],"explanationHi":"वास्तविक GDP वृद्धि ≈ 12% − 5% = 7%; वास्तविक प्रति व्यक्ति वृद्धि ≈ 7% − 2% = 5%। 7% पर रुक जाने में जनसंख्या भूल जाया जाता है, और 10% गलत ढंग से मुद्रास्फीति की उपेक्षा करता है।"},
  {"id":"eco-basics-112","question":"How many of these statements about the Union Budget are correct? I. Article 112 of the Constitution requires an Annual Financial Statement to be laid before Parliament. II. A Money Bill can be introduced only in the Lok Sabha. III. The Consolidated Fund of India is provided for in Article 266. IV. The Contingency Fund of India is placed at the disposal of the Finance Minister.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: under Article 267 the Contingency Fund is at the disposal of the President, who can advance money from it for unforeseen spending pending Parliament’s approval.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"केंद्रीय बजट के बारे में इनमें से कितने कथन सही हैं? I. संविधान का अनुच्छेद 112 वार्षिक वित्तीय विवरण को संसद के समक्ष रखना आवश्यक बनाता है। II. धन विधेयक केवल लोकसभा में प्रस्तुत किया जा सकता है। III. भारत की संचित निधि का प्रावधान अनुच्छेद 266 में है। IV. भारत की आकस्मिकता निधि वित्त मंत्री के व्ययनाधीन रखी जाती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: अनुच्छेद 267 के अंतर्गत आकस्मिकता निधि राष्ट्रपति के व्ययनाधीन होती है, जो संसद की स्वीकृति लंबित रहने तक अप्रत्याशित व्यय के लिए उससे धन अग्रिम दे सकते हैं।"},
  {"id":"eco-basics-113","question":"Assertion (A): A large fiscal deficit financed by borrowing directly from the central bank tends to be inflationary. Reason (R): Such monetisation of the deficit increases the base money in the economy.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"When the central bank buys government debt with newly created money, reserve (base) money rises and, through the money multiplier, broad money rises too; more money chasing the same goods pushes up prices. So R explains A.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"अभिकथन (A): केंद्रीय बैंक से सीधे उधार लेकर वित्तपोषित किया गया बड़ा राजकोषीय घाटा मुद्रास्फीतिकारी होता है। कारण (R): घाटे का ऐसा मौद्रीकरण अर्थव्यवस्था में आधार मुद्रा को बढ़ाता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, परंतु R, A की व्याख्या नहीं करता","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"जब केंद्रीय बैंक नई बनाई गई मुद्रा से सरकारी ऋण खरीदता है, तो आरक्षित (आधार) मुद्रा बढ़ती है और मुद्रा गुणक के माध्यम से व्यापक मुद्रा भी बढ़ती है; उन्हीं वस्तुओं के पीछे अधिक मुद्रा कीमतों को ऊपर धकेलती है। अतः R, A की व्याख्या करता है।"},
  {"id":"eco-basics-114","question":"The basic economic problem of choice arises because:","options":["The central bank keeps printing more money every year","Resources are limited while human wants are unlimited","Prices of most goods keep rising over time","Governments collect taxes on income and spending"],"answer":1,"explanation":"Scarcity of land, labour and capital relative to wants forces every society to decide what to produce, how and for whom.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"चयन की मूल आर्थिक समस्या उत्पन्न होती है क्योंकि:","optionsHi":["केंद्रीय बैंक हर वर्ष अधिक मुद्रा छापता रहता है","संसाधन सीमित हैं जबकि मानवीय आवश्यकताएँ असीमित हैं","अधिकांश वस्तुओं की कीमतें समय के साथ बढ़ती रहती हैं","सरकारें आय और व्यय पर कर वसूलती हैं"],"explanationHi":"आवश्यकताओं की तुलना में भूमि, श्रम और पूँजी की दुर्लभता प्रत्येक समाज को यह तय करने को बाध्य करती है कि क्या उत्पादित करें, कैसे और किसके लिए।"},
  {"id":"eco-basics-115","question":"A market with only one seller of a product that has no close substitutes is called:","options":["Monopoly","Oligopoly","Perfect competition","Monopsony"],"answer":0,"explanation":"A monopolist controls the whole supply and can set the price. Monopsony is the opposite case: a single buyer.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"ऐसा बाजार जिसमें किसी उत्पाद का केवल एक विक्रेता हो और उसका कोई निकट स्थानापन्न न हो, कहलाता है:","optionsHi":["एकाधिकार","अल्पाधिकार","पूर्ण प्रतिस्पर्धा","एकाधिक्रेता (क्रेता एकाधिकार)"],"explanationHi":"एकाधिकारी पूरी आपूर्ति को नियंत्रित करता है और कीमत तय कर सकता है। क्रेता एकाधिकार इसके विपरीत स्थिति है: एकमात्र खरीदार।"},
  {"id":"eco-basics-116","question":"A market dominated by a few large sellers, each of whose pricing decisions affects the others, is called:","options":["Monopolistic competition","Perfect competition","Oligopoly","Monopoly"],"answer":2,"explanation":"In an oligopoly, such as telecom or aviation, a handful of firms watch and react to one another's moves. Monopolistic competition has many sellers of differentiated goods.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"कुछ बड़े विक्रेताओं के प्रभुत्व वाला बाजार, जिसमें प्रत्येक की मूल्य निर्धारण संबंधी निर्णय दूसरों को प्रभावित करते हैं, कहलाता है:","optionsHi":["एकाधिकारी प्रतिस्पर्धा","पूर्ण प्रतिस्पर्धा","अल्पाधिकार","एकाधिकार"],"explanationHi":"अल्पाधिकार में, जैसे दूरसंचार या विमानन में, मुट्ठी भर फर्में एक-दूसरे की चालों पर नजर रखती हैं और प्रतिक्रिया देती हैं। एकाधिकारी प्रतिस्पर्धा में विभेदित वस्तुओं के कई विक्रेता होते हैं।"},
  {"id":"eco-basics-117","question":"If the price of petrol rises sharply, the demand for petrol cars is likely to:","options":["Rise, because cars and petrol are substitutes","Stay unchanged","Rise, because cars become cheaper","Fall, because cars and petrol are complements"],"answer":3,"explanation":"Complements are used together, so a costlier complement makes the other good less attractive. With substitutes such as tea and coffee, a price rise of one raises demand for the other.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"यदि पेट्रोल की कीमत तेज़ी से बढ़ती है, तो पेट्रोल कारों की माँग संभवतः:","optionsHi":["बढ़ेगी, क्योंकि कारें और पेट्रोल स्थानापन्न हैं","अपरिवर्तित रहेगी","बढ़ेगी, क्योंकि कारें सस्ती हो जाती हैं","घटेगी, क्योंकि कारें और पेट्रोल पूरक हैं"],"explanationHi":"पूरक वस्तुओं का उपयोग साथ-साथ होता है, इसलिए एक पूरक के महँगे होने पर दूसरी वस्तु कम आकर्षक हो जाती है। चाय और कॉफी जैसी स्थानापन्न वस्तुओं में एक की कीमत बढ़ने पर दूसरी की माँग बढ़ती है।"},
  {"id":"eco-basics-118","question":"To avoid double counting while measuring GDP, statisticians count:","options":["Only final goods and services, or the value added at each stage","The value of all goods sold, including raw materials and intermediates","Only goods exported, since they are sold for foreign exchange","Only goods and services produced by the government sector"],"answer":0,"explanation":"Counting both wheat and the bread made from it would count the wheat twice. Using final goods or summing value added at each stage gives the same, correct total.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"GDP मापते समय दोहरी गणना से बचने के लिए सांख्यिकीविद् गिनते हैं:","optionsHi":["केवल अंतिम वस्तुएँ और सेवाएँ, या प्रत्येक चरण पर मूल्य वर्धन","बेची गई सभी वस्तुओं का मूल्य, कच्चे माल और मध्यवर्ती वस्तुओं सहित","केवल निर्यात की गई वस्तुएँ, क्योंकि वे विदेशी मुद्रा के लिए बेची जाती हैं","केवल सरकारी क्षेत्र द्वारा उत्पादित वस्तुएँ और सेवाएँ"],"explanationHi":"गेहूँ और उससे बनी रोटी (ब्रेड) दोनों को गिनने पर गेहूँ दो बार गिना जाएगा। अंतिम वस्तुओं का उपयोग करने या प्रत्येक चरण के मूल्य वर्धन को जोड़ने से एक ही, सही कुल प्राप्त होता है।"},
  {"id":"eco-basics-119","question":"A thirsty person gets less and less extra satisfaction from each additional glass of water. This illustrates the:","options":["Law of demand","Law of diminishing marginal utility","Law of supply","Law of variable proportions (diminishing returns)"],"answer":1,"explanation":"Marginal utility, the satisfaction from one more unit, falls as consumption rises. This is one reason why demand curves slope downward.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"एक प्यासे व्यक्ति को पानी के प्रत्येक अतिरिक्त गिलास से कम-से-कम अतिरिक्त संतुष्टि मिलती जाती है। यह किसका उदाहरण है?","optionsHi":["माँग का नियम","ह्रासमान सीमांत उपयोगिता का नियम","पूर्ति का नियम","परिवर्ती अनुपातों का नियम (ह्रासमान प्रतिफल)"],"explanationHi":"सीमांत उपयोगिता, यानी एक और इकाई से मिलने वाली संतुष्टि, उपभोग बढ़ने पर घटती है। माँग वक्रों के नीचे की ओर ढलान वाले होने का यह एक कारण है।"},
  {"id":"eco-basics-120","question":"Old-age pensions and scholarships paid by the government are NOT included in national income because they:","options":["Are too small a share of GDP to be worth counting","Are paid in cash rather than in kind to the recipients","Are transfers with no current production in return","Are already counted once in India's exports"],"answer":2,"explanation":"Transfer payments merely move income from taxpayers to recipients; no good or service is produced for them, so including them would overstate output.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"सरकार द्वारा दी जाने वाली वृद्धावस्था पेंशन और छात्रवृत्तियाँ राष्ट्रीय आय में शामिल नहीं की जातीं क्योंकि वे:","optionsHi":["GDP का इतना छोटा हिस्सा हैं कि गिनने योग्य नहीं","प्राप्तकर्ताओं को वस्तु के रूप में नहीं, बल्कि नकद में दी जाती हैं","अंतरण भुगतान हैं जिनके बदले कोई चालू उत्पादन नहीं होता","भारत के निर्यात में पहले ही एक बार गिनी जा चुकी हैं"],"explanationHi":"अंतरण भुगतान केवल करदाताओं से प्राप्तकर्ताओं तक आय का स्थानांतरण करते हैं; उनके बदले कोई वस्तु या सेवा उत्पादित नहीं होती, इसलिए उन्हें शामिल करने से उत्पादन बढ़ा-चढ़ाकर दिखेगा।"},
  {"id":"eco-basics-121","question":"A farmer sells wheat worth ₹100 to a miller (with no inputs bought), the miller sells flour worth ₹150 to a baker, and the baker sells bread worth ₹220 to consumers. How much do these transactions add to GDP?","options":["₹470","₹370","₹120","₹220"],"answer":3,"explanation":"Value added is ₹100 + ₹50 + ₹70 = ₹220, which equals the value of the final good, bread. Adding all sales (₹470) double-counts the wheat and flour.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक किसान ₹100 का गेहूँ एक चक्की वाले को बेचता है (कोई आगत नहीं खरीदी गई), चक्की वाला ₹150 का आटा एक बेकर को बेचता है, और बेकर ₹220 की रोटी (ब्रेड) उपभोक्ताओं को बेचता है। ये लेनदेन GDP में कितना जोड़ते हैं?","optionsHi":["₹470","₹370","₹120","₹220"],"explanationHi":"मूल्य वर्धन ₹100 + ₹50 + ₹70 = ₹220 है, जो अंतिम वस्तु, ब्रेड, के मूल्य के बराबर है। सभी बिक्रियाँ जोड़ने (₹470) पर गेहूँ और आटे की दोहरी गणना हो जाती है।"},
  {"id":"eco-basics-122","question":"If the government fixes a maximum price (price ceiling) below the market equilibrium price, the most likely result is:","options":["A shortage, often accompanied by rationing or black markets","A surplus of the good, since sellers cannot raise their price","No change, because the market price is already below the ceiling","A rise in the quantity supplied as producers chase the fixed price"],"answer":0,"explanation":"At the lower price buyers want more and sellers offer less, so demand exceeds supply. A price floor above equilibrium, by contrast, creates a surplus.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"यदि सरकार बाजार संतुलन कीमत से नीचे अधिकतम कीमत (कीमत सीमा) तय कर दे, तो सबसे संभावित परिणाम है:","optionsHi":["कमी, जिसके साथ प्रायः राशनिंग या कालाबाजारी होती है","वस्तु का अधिशेष, क्योंकि विक्रेता अपनी कीमत नहीं बढ़ा सकते","कोई परिवर्तन नहीं, क्योंकि बाजार कीमत पहले से ही सीमा से नीचे है","पूर्ति की मात्रा में वृद्धि, क्योंकि उत्पादक निर्धारित कीमत के पीछे दौड़ते हैं"],"explanationHi":"कम कीमत पर खरीदार अधिक चाहते हैं और विक्रेता कम देते हैं, इसलिए माँग पूर्ति से अधिक हो जाती है। इसके विपरीत, संतुलन से ऊपर न्यूनतम कीमत (कीमत तल) अधिशेष उत्पन्न करती है।"},
  {"id":"eco-basics-123","question":"Luxury goods whose demand rises as their price rises, because a high price signals status, are called:","options":["Giffen goods","Veblen goods","Inferior goods","Normal necessities"],"answer":1,"explanation":"Veblen goods, such as designer watches, are prized for conspicuous consumption. Giffen goods are cheap staples of the very poor whose demand rises with price for a different reason.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"विलासिता की वे वस्तुएँ जिनकी माँग कीमत बढ़ने पर बढ़ती है, क्योंकि ऊँची कीमत प्रतिष्ठा का संकेत देती है, कहलाती हैं:","optionsHi":["गिफिन वस्तुएँ","वेब्लेन वस्तुएँ","निकृष्ट वस्तुएँ","सामान्य अनिवार्य वस्तुएँ"],"explanationHi":"डिजाइनर घड़ियों जैसी वेब्लेन वस्तुएँ दिखावटी उपभोग के लिए बहुमूल्य मानी जाती हैं। गिफिन वस्तुएँ बहुत गरीबों के सस्ते मुख्य खाद्य हैं जिनकी माँग किसी भिन्न कारण से कीमत के साथ बढ़ती है।"},
  {"id":"eco-basics-124","question":"The cross-price elasticity of demand between two goods is negative. The two goods are most likely:","options":["Substitutes","Unrelated","Complements","Both inferior goods"],"answer":2,"explanation":"Negative cross elasticity means a rise in the price of one lowers demand for the other, as with printers and ink cartridges. Substitutes have positive cross elasticity.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"दो वस्तुओं के बीच माँग की आड़ी कीमत लोच ऋणात्मक है। ये दोनों वस्तुएँ सबसे संभावित रूप से हैं:","optionsHi":["स्थानापन्न","असंबंधित","पूरक","दोनों निकृष्ट वस्तुएँ"],"explanationHi":"ऋणात्मक आड़ी लोच का अर्थ है कि एक की कीमत बढ़ने से दूसरी की माँग घटती है, जैसे प्रिंटर और स्याही कार्ट्रिज। स्थानापन्न वस्तुओं की आड़ी लोच धनात्मक होती है।"},
  {"id":"eco-basics-125","question":"A factory dumps waste into a river, hurting fishermen downstream who receive no compensation. Economists call this a:","options":["Positive externality","Public good","Merit good","Negative externality"],"answer":3,"explanation":"A negative externality is a cost imposed on third parties outside the market. A corrective (Pigouvian) tax or regulation makes the polluter bear that cost.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"एक कारखाना नदी में कचरा बहाता है, जिससे नीचे की ओर के मछुआरों को हानि होती है और उन्हें कोई क्षतिपूर्ति नहीं मिलती। अर्थशास्त्री इसे कहते हैं:","optionsHi":["धनात्मक बाह्यता","सार्वजनिक वस्तु","योग्यता वस्तु","ऋणात्मक बाह्यता"],"explanationHi":"ऋणात्मक बाह्यता बाजार के बाहर के तीसरे पक्षों पर थोपी गई लागत है। सुधारात्मक (पिगू) कर या विनियमन प्रदूषक को वह लागत वहन करवाता है।"},
  {"id":"eco-basics-126","question":"Goods like primary education and vaccination, which society considers so valuable that they would be under-consumed if left to the market, are called:","options":["Merit goods","Demerit goods","Giffen goods","Inferior goods"],"answer":0,"explanation":"Merit goods create benefits beyond the individual buyer, so governments subsidise or provide them. Demerit goods, such as tobacco, are over-consumed and often taxed.","difficulty":"hard","source":"UPSC Prelims · IBPS PO","questionHi":"प्राथमिक शिक्षा और टीकाकरण जैसी वस्तुएँ, जिन्हें समाज इतना मूल्यवान मानता है कि बाजार पर छोड़ने से उनका उपभोग कम होगा, कहलाती हैं:","optionsHi":["योग्यता वस्तुएँ","अयोग्यता वस्तुएँ","गिफिन वस्तुएँ","निकृष्ट वस्तुएँ"],"explanationHi":"योग्यता वस्तुएँ व्यक्तिगत खरीदार से परे भी लाभ उत्पन्न करती हैं, इसलिए सरकारें उन पर सब्सिडी देती हैं या उन्हें उपलब्ध कराती हैं। तंबाकू जैसी अयोग्यता वस्तुओं का अत्यधिक उपभोग होता है और उन पर प्रायः कर लगाया जाता है।"},
  {"id":"eco-basics-127","question":"How many of these statements about price controls are correct? I. A price ceiling below the equilibrium price creates a shortage. II. A minimum support price above the market price can lead to large government stocks. III. Rationing often accompanies a binding price ceiling. IV. A price floor fixed below the equilibrium price changes the market outcome.","options":["Only three","Only one","Only two","All four"],"answer":0,"explanation":"I, II and III are correct. A floor below equilibrium is non-binding: the market price already exceeds it, so nothing changes, and IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कीमत नियंत्रण के बारे में इनमें से कितने कथन सही हैं? I. संतुलन कीमत से नीचे की कीमत सीमा कमी उत्पन्न करती है। II. बाजार कीमत से ऊपर का न्यूनतम समर्थन मूल्य सरकार के पास बड़े भंडार का कारण बन सकता है। III. बाध्यकारी कीमत सीमा के साथ प्रायः राशनिंग होती है। IV. संतुलन कीमत से नीचे तय किया गया कीमत तल बाजार के परिणाम को बदल देता है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। संतुलन से नीचे का तल बाध्यकारी नहीं होता: बाजार कीमत पहले से उससे ऊपर होती है, इसलिए कुछ नहीं बदलता, और IV गलत है।"},
  {"id":"eco-basics-128","question":"Match the market form with its feature. A. Perfect competition  B. Monopoly  C. Monopolistic competition  D. Oligopoly; 1. Many sellers of differentiated products such as toothpaste brands  2. A few interdependent sellers  3. A single seller with no close substitutes  4. Many sellers of an identical product, each a price taker","options":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-4, B-1, C-3, D-2"],"answer":1,"explanation":"Perfect competitors cannot influence price; a monopolist faces no rival; monopolistic competitors compete through branding and product differences; oligopolists react to each other's moves.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO","questionHi":"बाजार रूप का उसकी विशेषता से मिलान कीजिए। A. पूर्ण प्रतिस्पर्धा  B. एकाधिकार  C. एकाधिकारी प्रतिस्पर्धा  D. अल्पाधिकार; 1. टूथपेस्ट ब्रांडों जैसे विभेदित उत्पादों के कई विक्रेता  2. कुछ परस्पर निर्भर विक्रेता  3. कोई निकट स्थानापन्न न रखने वाला एकमात्र विक्रेता  4. समरूप उत्पाद के कई विक्रेता, जिनमें प्रत्येक कीमत स्वीकारक है","optionsHi":["A-4, B-3, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-4, B-1, C-3, D-2"],"explanationHi":"पूर्ण प्रतिस्पर्धी कीमत को प्रभावित नहीं कर सकते; एकाधिकारी का कोई प्रतिद्वंद्वी नहीं होता; एकाधिकारी प्रतिस्पर्धी ब्रांडिंग और उत्पाद-भिन्नता के माध्यम से प्रतिस्पर्धा करते हैं; अल्पाधिकारी एक-दूसरे की चालों पर प्रतिक्रिया देते हैं।"},
  {"id":"eco-basics-129","question":"How many of these statements about public goods are correct? I. One person's use does not reduce what is available to others (non-rival). II. It is hard to stop non-payers from using them (non-excludable). III. The free-rider problem means markets tend to under-supply them. IV. A public good must be produced by a government-owned enterprise.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct; national defence and street lighting are classic examples. Governments usually fund or arrange public goods, but private firms can produce them under contract, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सार्वजनिक वस्तुओं के बारे में इनमें से कितने कथन सही हैं? I. एक व्यक्ति के उपयोग से दूसरों के लिए उपलब्धता कम नहीं होती (अप्रतिद्वंद्वी)। II. भुगतान न करने वालों को उनका उपयोग करने से रोकना कठिन होता है (अबहिष्करणीय)। III. मुफ्तखोरी (free-rider) की समस्या के कारण बाजार प्रायः इनकी आपूर्ति कम करते हैं। IV. सार्वजनिक वस्तु का उत्पादन सरकारी स्वामित्व वाले उद्यम द्वारा ही होना चाहिए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं; राष्ट्रीय रक्षा और सड़क की बत्तियाँ इसके उत्कृष्ट उदाहरण हैं। सरकारें प्रायः सार्वजनिक वस्तुओं का वित्तपोषण या प्रबंध करती हैं, पर निजी फर्में अनुबंध पर इनका उत्पादन कर सकती हैं, इसलिए IV गलत है।"},
  {"id":"eco-basics-130","question":"Assertion (A): A rising GDP does not necessarily mean rising economic welfare. Reason (R): GDP leaves out unpaid household work and does not subtract environmental damage, and it says nothing about how income is distributed.","options":["A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"These gaps are exactly why GDP can grow while welfare stagnates, and why measures such as the HDI and green accounting were developed.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): GDP का बढ़ना आवश्यक रूप से आर्थिक कल्याण के बढ़ने का अर्थ नहीं है। कारण (R): GDP में अवैतनिक घरेलू कार्य छूट जाता है, पर्यावरणीय क्षति घटाई नहीं जाती, और यह आय के वितरण के बारे में कुछ नहीं बताता।","optionsHi":["A सत्य है, परंतु R असत्य है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A असत्य है, परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"ये कमियाँ ही कारण हैं कि कल्याण के ठहरे रहने पर भी GDP बढ़ सकता है, और इसीलिए HDI तथा हरित लेखांकन जैसे माप विकसित किए गए।"},
  {"id":"eco-basics-131","question":"How many of these are correctly treated in India's GDP? I. The sale of a used car is excluded, except for the dealer's commission. II. Buying shares on the stock exchange is excluded. III. An imputed rent for owner-occupied houses is included. IV. Interest the government pays on its past borrowing is included as factor income.","options":["Only one","Only three","Only two","All four"],"answer":1,"explanation":"I, II and III are correct. Interest on public debt, much of it raised for consumption or war, is treated as a transfer payment rather than income from current production, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO","questionHi":"भारत के GDP में इनमें से कितनी बातों का सही ढंग से व्यवहार होता है? I. प्रयुक्त कार की बिक्री शामिल नहीं होती, केवल डीलर का कमीशन गिना जाता है। II. शेयर बाजार में शेयर खरीदना शामिल नहीं होता। III. स्वामी-आवासित मकानों का आरोपित किराया शामिल होता है। IV. सरकार द्वारा अपनी पिछली उधारी पर चुकाया गया ब्याज साधन आय के रूप में शामिल होता है।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। सार्वजनिक ऋण पर ब्याज, जिसका बहुत-सा भाग उपभोग या युद्ध के लिए जुटाया गया था, चालू उत्पादन से आय के बजाय अंतरण भुगतान माना जाता है, इसलिए IV गलत है।"},
  {"id":"eco-basics-132","question":"Match the cost concept with an example or definition. A. Fixed cost  B. Variable cost  C. Marginal cost  D. Average cost; 1. Extra cost of producing one more unit  2. Total cost divided by the number of units  3. Rent of a factory that stays the same whatever the output  4. Raw materials, which rise as output rises","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Fixed costs must be paid even at zero output; variable costs change with output; marginal cost is the addition from one more unit; average cost spreads the total over all units.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"लागत की अवधारणा का उसके उदाहरण या परिभाषा से मिलान कीजिए। A. स्थिर लागत  B. परिवर्ती लागत  C. सीमांत लागत  D. औसत लागत; 1. उत्पादन की एक और इकाई की अतिरिक्त लागत  2. कुल लागत को इकाइयों की संख्या से भाग देना  3. कारखाने का किराया जो उत्पादन चाहे जो हो, समान रहता है  4. कच्चा माल, जो उत्पादन बढ़ने पर बढ़ता है","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"स्थिर लागत शून्य उत्पादन पर भी चुकानी पड़ती है; परिवर्ती लागत उत्पादन के साथ बदलती है; सीमांत लागत एक और इकाई से होने वाली वृद्धि है; औसत लागत कुल लागत को सभी इकाइयों में बाँटती है।"},
  {"id":"eco-basics-133","question":"For an economy where depreciation is positive, net indirect taxes are positive, and net factor income from abroad is positive but smaller than net indirect taxes, arrange these in decreasing order: 1. GNP at market prices  2. NNP at factor cost  3. GDP at market prices  4. NDP at market prices","options":["1-3-4-2","3-1-4-2","1-3-2-4","1-4-3-2"],"answer":0,"explanation":"GNP(MP) = GDP(MP) + NFIA, so 1 > 3; NDP(MP) = GDP(MP) − depreciation, so 3 > 4; NNP(FC) = NDP(MP) + NFIA − net indirect taxes, which is below NDP(MP) because NFIA is smaller than net indirect taxes.","difficulty":"very-hard","source":"UPSC Prelims · IBPS PO","questionHi":"ऐसी अर्थव्यवस्था में जहाँ मूल्यह्रास धनात्मक है, शुद्ध अप्रत्यक्ष कर धनात्मक हैं, और विदेशों से शुद्ध साधन आय धनात्मक है पर शुद्ध अप्रत्यक्ष करों से कम है, इन्हें घटते क्रम में व्यवस्थित कीजिए: 1. बाजार कीमतों पर GNP  2. साधन लागत पर NNP  3. बाजार कीमतों पर GDP  4. बाजार कीमतों पर NDP","optionsHi":["1-3-4-2","3-1-4-2","1-3-2-4","1-4-3-2"],"explanationHi":"GNP(MP) = GDP(MP) + NFIA, इसलिए 1 > 3; NDP(MP) = GDP(MP) − मूल्यह्रास, इसलिए 3 > 4; NNP(FC) = NDP(MP) + NFIA − शुद्ध अप्रत्यक्ष कर, जो NDP(MP) से कम है क्योंकि NFIA शुद्ध अप्रत्यक्ष करों से कम है।"},
  {"id":"eco-basics-134","question":"An economy's output at basic prices is ₹1,000 crore and intermediate consumption is ₹600 crore. Product taxes are ₹50 crore and product subsidies ₹10 crore. Its GDP is:","options":["₹400 crore","₹440 crore","₹460 crore","₹450 crore"],"answer":1,"explanation":"GVA at basic prices = 1,000 − 600 = ₹400 crore; GDP = GVA at basic prices + product taxes − product subsidies = 400 + 50 − 10 = ₹440 crore. Adding the subsidies instead of subtracting gives ₹460 crore.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"किसी अर्थव्यवस्था का मूल कीमतों पर उत्पादन ₹1,000 करोड़ और मध्यवर्ती उपभोग ₹600 करोड़ है। उत्पाद कर ₹50 करोड़ और उत्पाद सब्सिडी ₹10 करोड़ हैं। उसका GDP है:","optionsHi":["₹400 करोड़","₹440 करोड़","₹460 करोड़","₹450 करोड़"],"explanationHi":"मूल कीमतों पर GVA = 1,000 − 600 = ₹400 करोड़; GDP = मूल कीमतों पर GVA + उत्पाद कर − उत्पाद सब्सिडी = 400 + 50 − 10 = ₹440 करोड़। सब्सिडी को घटाने के बजाय जोड़ने पर ₹460 करोड़ आता है।"},
  {"id":"eco-basics-135","question":"How many of these statements about India's national accounts (2011–12 series) are correct? I. GVA at basic prices = GVA at factor cost + production taxes − production subsidies. II. GDP = GVA at basic prices + product taxes − product subsidies. III. Land revenue and stamp duties are treated as production taxes, levied whatever the volume of output. IV. GST is treated as a production tax.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. GST is levied per unit of product sold, so it is a product tax that is added to GVA at basic prices to reach GDP; IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"भारत के राष्ट्रीय लेखों (2011–12 श्रृंखला) के बारे में इनमें से कितने कथन सही हैं? I. मूल कीमतों पर GVA = साधन लागत पर GVA + उत्पादन कर − उत्पादन सब्सिडी। II. GDP = मूल कीमतों पर GVA + उत्पाद कर − उत्पाद सब्सिडी। III. भू-राजस्व और स्टाम्प शुल्क को उत्पादन कर माना जाता है, जो उत्पादन की मात्रा चाहे जो हो, लगाए जाते हैं। IV. GST को उत्पादन कर माना जाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। GST बेची गई प्रति इकाई उत्पाद पर लगता है, इसलिए यह उत्पाद कर है जिसे GDP तक पहुँचने के लिए मूल कीमतों पर GVA में जोड़ा जाता है; IV गलत है।"},
  {"id":"eco-basics-136","question":"In a year, compensation of employees is ₹300 crore, operating surplus ₹150 crore, mixed income of the self-employed ₹100 crore and net factor income from abroad −₹10 crore. National income (NNP at factor cost) is:","options":["₹550 crore","₹560 crore","₹540 crore","₹640 crore"],"answer":2,"explanation":"Adding the factor incomes earned at home gives NDP at factor cost = 300 + 150 + 100 = ₹550 crore. Adding net factor income from abroad gives NNP at factor cost = 550 − 10 = ₹540 crore.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"एक वर्ष में कर्मचारियों का पारिश्रमिक ₹300 करोड़, परिचालन अधिशेष ₹150 करोड़, स्वनियोजितों की मिश्रित आय ₹100 करोड़ और विदेशों से शुद्ध साधन आय −₹10 करोड़ है। राष्ट्रीय आय (साधन लागत पर NNP) है:","optionsHi":["₹550 करोड़","₹560 करोड़","₹540 करोड़","₹640 करोड़"],"explanationHi":"देश में अर्जित साधन आयों को जोड़ने पर साधन लागत पर NDP = 300 + 150 + 100 = ₹550 करोड़। विदेशों से शुद्ध साधन आय जोड़ने पर साधन लागत पर NNP = 550 − 10 = ₹540 करोड़।"},
  {"id":"eco-basics-137","question":"In an open economy the marginal propensity to consume out of disposable income is 0.8, the proportional tax rate is 25% and the marginal propensity to import is 0.1. The investment multiplier is:","options":["2.5","3.33","5.0","2.0"],"answer":3,"explanation":"k = 1/[1 − b(1 − t) + m] = 1/[1 − 0.8 × 0.75 + 0.1] = 1/0.5 = 2. Ignoring imports gives 2.5, ignoring taxes gives 3.33, and the closed-economy, no-tax multiplier is 5.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"एक खुली अर्थव्यवस्था में प्रयोज्य आय में से सीमांत उपभोग प्रवृत्ति 0.8 है, आनुपातिक कर दर 25% है और सीमांत आयात प्रवृत्ति 0.1 है। निवेश गुणक है:","optionsHi":["2.5","3.33","5.0","2.0"],"explanationHi":"k = 1/[1 − b(1 − t) + m] = 1/[1 − 0.8 × 0.75 + 0.1] = 1/0.5 = 2। आयात की उपेक्षा करने पर 2.5 आता है, कर की उपेक्षा करने पर 3.33, और बंद अर्थव्यवस्था, बिना कर का गुणक 5 है।"},
  {"id":"eco-basics-138","question":"In a simple Keynesian model with an MPC of 0.75 and lump-sum taxes, the government raises both its spending and its taxes by ₹100 crore. Equilibrium income rises by:","options":["₹100 crore","Zero","₹400 crore","₹300 crore"],"answer":0,"explanation":"The spending multiplier is 1/0.25 = 4 (+₹400 crore) and the tax multiplier is −0.75/0.25 = −3 (−₹300 crore), so income rises by ₹100 crore: the balanced budget multiplier is 1.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"MPC 0.75 वाले और एकमुश्त करों वाले सरल कीन्सीय मॉडल में सरकार अपना व्यय और कर दोनों ₹100 करोड़ बढ़ाती है। संतुलन आय में कितनी वृद्धि होती है?","optionsHi":["₹100 करोड़","शून्य","₹400 करोड़","₹300 करोड़"],"explanationHi":"व्यय गुणक 1/0.25 = 4 है (+₹400 करोड़) और कर गुणक −0.75/0.25 = −3 है (−₹300 करोड़), इसलिए आय ₹100 करोड़ बढ़ती है: संतुलित बजट गुणक 1 है।"},
  {"id":"eco-basics-139","question":"With an MPC of 0.75, the government cuts lump-sum taxes by ₹40 crore while keeping spending unchanged. Equilibrium income rises by:","options":["₹160 crore","₹120 crore","₹40 crore","₹30 crore"],"answer":1,"explanation":"The tax multiplier is −b/(1 − b) = −3, so a ₹40 crore tax cut raises income by ₹120 crore. It is smaller than the spending multiplier (4) because part of the tax cut is saved, not spent.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"MPC 0.75 होने पर, सरकार व्यय अपरिवर्तित रखते हुए एकमुश्त करों में ₹40 करोड़ की कटौती करती है। संतुलन आय में कितनी वृद्धि होती है?","optionsHi":["₹160 करोड़","₹120 करोड़","₹40 करोड़","₹30 करोड़"],"explanationHi":"कर गुणक −b/(1 − b) = −3 है, इसलिए ₹40 करोड़ की कर कटौती आय को ₹120 करोड़ बढ़ाती है। यह व्यय गुणक (4) से छोटा है क्योंकि कर कटौती का एक भाग खर्च नहीं, बचाया जाता है।"},
  {"id":"eco-basics-140","question":"The consumption function is C = 60 + 0.75Y (₹ crore). At what level of income is saving exactly zero?","options":["₹80 crore","₹60 crore","₹240 crore","₹180 crore"],"answer":2,"explanation":"Saving S = Y − C = −60 + 0.25Y, which is zero when Y = 60/0.25 = ₹240 crore, where APC = 1. Dividing 60 by the MPC (0.75) gives ₹80 crore, ₹60 crore is only autonomous consumption, and ₹180 crore is 0.75 × 240, the induced part of consumption.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"उपभोग फलन C = 60 + 0.75Y (₹ करोड़) है। आय के किस स्तर पर बचत ठीक शून्य होती है?","optionsHi":["₹80 करोड़","₹60 करोड़","₹240 करोड़","₹180 करोड़"],"explanationHi":"बचत S = Y − C = −60 + 0.25Y, जो Y = 60/0.25 = ₹240 करोड़ पर शून्य होती है, जहाँ APC = 1। 60 को MPC (0.75) से भाग देने पर ₹80 करोड़ आता है, ₹60 करोड़ केवल स्वायत्त उपभोग है, और ₹180 करोड़ 0.75 × 240 है, जो उपभोग का प्रेरित भाग है।"},
  {"id":"eco-basics-141","question":"An industry needs ₹3 of capital for every ₹1 of annual output. If its output rises from ₹500 crore to ₹550 crore, the induced net investment according to the accelerator principle is:","options":["₹1,650 crore","₹16.7 crore","₹50 crore","₹150 crore"],"answer":3,"explanation":"Net investment = capital-output ratio × change in output = 3 × 50 = ₹150 crore. Multiplying the whole output (550) by 3 gives the total capital stock, not new investment.","difficulty":"moderate","source":"RBI Grade B Phase 2","questionHi":"किसी उद्योग को वार्षिक उत्पादन के प्रत्येक ₹1 के लिए ₹3 की पूँजी चाहिए। यदि उसका उत्पादन ₹500 करोड़ से बढ़कर ₹550 करोड़ हो जाता है, तो त्वरक सिद्धांत के अनुसार प्रेरित शुद्ध निवेश है:","optionsHi":["₹1,650 करोड़","₹16.7 करोड़","₹50 करोड़","₹150 करोड़"],"explanationHi":"शुद्ध निवेश = पूँजी-उत्पाद अनुपात × उत्पादन में परिवर्तन = 3 × 50 = ₹150 करोड़। पूरे उत्पादन (550) को 3 से गुणा करने पर कुल पूँजी स्टॉक मिलता है, नया निवेश नहीं।"},
  {"id":"eco-basics-142","question":"The price of a good rises from ₹10 to ₹12 and the quantity demanded falls from 100 to 80 units. Using the midpoint (arc) method, the price elasticity of demand (absolute value) is about:","options":["1.22","1.00","0.82","2.00"],"answer":0,"explanation":"Midpoint method: (20/90)/(2/11) ≈ 0.222/0.182 ≈ 1.22. Using the initial values instead gives (20/100)/(2/10) = 1.0, which is why the arc method is preferred for large changes.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"किसी वस्तु की कीमत ₹10 से बढ़कर ₹12 हो जाती है और माँगी गई मात्रा 100 से घटकर 80 इकाई रह जाती है। मध्य-बिंदु (चाप) विधि से माँग की कीमत लोच (निरपेक्ष मान) लगभग है:","optionsHi":["1.22","1.00","0.82","2.00"],"explanationHi":"मध्य-बिंदु विधि: (20/90)/(2/11) ≈ 0.222/0.182 ≈ 1.22। प्रारंभिक मानों का उपयोग करने पर (20/100)/(2/10) = 1.0 आता है, इसीलिए बड़े परिवर्तनों के लिए चाप विधि को प्राथमिकता दी जाती है।"},
  {"id":"eco-basics-143","question":"The price elasticity of demand for a firm's product is 0.5 (absolute). If the firm raises its price by 10%, its total revenue will:","options":["Fall by about 5%","Rise by about 4.5%","Rise by about 10%","Fall by about 4.5%"],"answer":1,"explanation":"Quantity falls by 0.5 × 10% = 5%, so revenue becomes 1.10 × 0.95 = 1.045 times: a rise of about 4.5%. With inelastic demand, price and total revenue move in the same direction.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"किसी फर्म के उत्पाद की माँग की कीमत लोच 0.5 (निरपेक्ष) है। यदि फर्म अपनी कीमत 10% बढ़ाती है, तो उसका कुल राजस्व:","optionsHi":["लगभग 5% घटेगा","लगभग 4.5% बढ़ेगा","लगभग 10% बढ़ेगा","लगभग 4.5% घटेगा"],"explanationHi":"मात्रा 0.5 × 10% = 5% घटती है, इसलिए राजस्व 1.10 × 0.95 = 1.045 गुना हो जाता है: लगभग 4.5% की वृद्धि। बेलोचदार माँग में कीमत और कुल राजस्व एक ही दिशा में चलते हैं।"},
  {"id":"eco-basics-144","question":"When household incomes rise by 20%, the quantity demanded of good X falls by 5%. The income elasticity of demand and the type of good are:","options":["+0.25; a normal good (necessity)","−4.0; a Giffen good","−0.25; an inferior good","+4.0; a luxury good"],"answer":2,"explanation":"Income elasticity = −5/20 = −0.25. A negative income elasticity marks an inferior good; it would be a Giffen good only if demand also rose with its own price, which the data do not show.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"जब परिवारों की आय 20% बढ़ती है, तो वस्तु X की माँगी गई मात्रा 5% घटती है। माँग की आय लोच और वस्तु का प्रकार हैं:","optionsHi":["+0.25; सामान्य वस्तु (अनिवार्य वस्तु)","−4.0; गिफिन वस्तु","−0.25; निकृष्ट वस्तु","+4.0; विलासिता की वस्तु"],"explanationHi":"आय लोच = −5/20 = −0.25। ऋणात्मक आय लोच निकृष्ट वस्तु को दर्शाती है; यह गिफिन वस्तु तभी होती जब माँग उसकी अपनी कीमत के साथ भी बढ़ती, जो आँकड़ों में नहीं दिखता।"},
  {"id":"eco-basics-145","question":"A consumer is willing to pay at most ₹50 for the first unit of a good, ₹40 for the second, ₹30 for the third and ₹20 for the fourth. The market price is ₹30 and she buys three units. Her consumer surplus is:","options":["₹120","₹90","₹20","₹30"],"answer":3,"explanation":"Consumer surplus = (50 − 30) + (40 − 30) + (30 − 30) = ₹30. ₹120 is her total willingness to pay and ₹90 her spending; buying the fourth unit would have cut the surplus to ₹20.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक उपभोक्ता किसी वस्तु की पहली इकाई के लिए अधिकतम ₹50, दूसरी के लिए ₹40, तीसरी के लिए ₹30 और चौथी के लिए ₹20 देने को तैयार है। बाजार कीमत ₹30 है और वह तीन इकाइयाँ खरीदती है। उसका उपभोक्ता अधिशेष है:","optionsHi":["₹120","₹90","₹20","₹30"],"explanationHi":"उपभोक्ता अधिशेष = (50 − 30) + (40 − 30) + (30 − 30) = ₹30। ₹120 उसकी कुल भुगतान की इच्छा है और ₹90 उसका व्यय; चौथी इकाई खरीदने पर अधिशेष घटकर ₹20 रह जाता।"},
  {"id":"eco-basics-146","question":"If the supply of a good is perfectly inelastic, a per-unit tax on it is borne:","options":["Entirely by sellers","Entirely by buyers","Equally by buyers and sellers","By whichever side pays it to the government"],"answer":0,"explanation":"Sellers cannot cut quantity, so the price buyers pay does not change and sellers absorb the whole tax. In general, the less elastic side bears more of the tax, whoever legally pays it.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"यदि किसी वस्तु की पूर्ति पूर्णतः बेलोचदार है, तो उस पर लगे प्रति इकाई कर का भार वहन किया जाता है:","optionsHi":["पूरी तरह विक्रेताओं द्वारा","पूरी तरह क्रेताओं द्वारा","क्रेताओं और विक्रेताओं द्वारा समान रूप से","उस पक्ष द्वारा जो इसे सरकार को चुकाता है"],"explanationHi":"विक्रेता मात्रा नहीं घटा सकते, इसलिए क्रेताओं द्वारा चुकाई जाने वाली कीमत नहीं बदलती और विक्रेता पूरा कर सोख लेते हैं। सामान्यतः, कम लोचदार पक्ष कर का अधिक भार वहन करता है, चाहे कानूनी रूप से कर कोई भी चुकाए।"},
  {"id":"eco-basics-147","question":"A firm in a perfectly competitive market finds that, at its best output, price is ₹40, average variable cost is ₹45 and average total cost is ₹55. In the short run it should:","options":["Keep producing, since the price covers part of the fixed cost","Shut down, since price is below average variable cost","Keep producing, as long as the price is above marginal cost","Raise its price to ₹55 so that it covers all of its costs"],"answer":1,"explanation":"If price is below AVC, every unit produced adds to losses; shutting down limits the loss to the fixed cost. A competitive firm is a price taker, so it cannot raise its price.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"पूर्ण प्रतिस्पर्धी बाजार की एक फर्म पाती है कि उसके सर्वोत्तम उत्पादन पर कीमत ₹40, औसत परिवर्ती लागत ₹45 और औसत कुल लागत ₹55 है। अल्पकाल में उसे:","optionsHi":["उत्पादन जारी रखना चाहिए, क्योंकि कीमत स्थिर लागत के एक भाग को पूरा करती है","बंद कर देना चाहिए, क्योंकि कीमत औसत परिवर्ती लागत से कम है","उत्पादन जारी रखना चाहिए, जब तक कीमत सीमांत लागत से ऊपर है","कीमत बढ़ाकर ₹55 कर देनी चाहिए ताकि वह अपनी सभी लागतें पूरी कर सके"],"explanationHi":"यदि कीमत AVC से कम है, तो उत्पादित प्रत्येक इकाई हानि को बढ़ाती है; बंद करने से हानि स्थिर लागत तक सीमित हो जाती है। प्रतिस्पर्धी फर्म कीमत स्वीकारक होती है, इसलिए वह अपनी कीमत नहीं बढ़ा सकती।"},
  {"id":"eco-basics-148","question":"At its profit-maximising output a firm charges ₹50 while its marginal cost is ₹30. Its Lerner index of market power and the implied price elasticity of demand are:","options":["0.6 and 1.67","0.4 and 0.4","0.67 and 1.5","0.4 and 2.5"],"answer":3,"explanation":"Lerner index = (P − MC)/P = 20/50 = 0.4, and at profit maximum it equals 1/|e|, so |e| = 2.5. Dividing by MC instead of price gives 0.67.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"अपने लाभ-अधिकतम उत्पादन पर एक फर्म ₹50 कीमत लेती है जबकि उसकी सीमांत लागत ₹30 है। बाजार शक्ति का उसका लर्नर सूचकांक और निहित माँग की कीमत लोच हैं:","optionsHi":["0.6 और 1.67","0.4 और 0.4","0.67 और 1.5","0.4 और 2.5"],"explanationHi":"लर्नर सूचकांक = (P − MC)/P = 20/50 = 0.4, और लाभ-अधिकतम बिंदु पर यह 1/|e| के बराबर होता है, इसलिए |e| = 2.5। कीमत के बजाय MC से भाग देने पर 0.67 आता है।"},
  {"id":"eco-basics-149","question":"The kinked demand curve model of oligopoly (Sweezy) is mainly used to explain:","options":["Why prices stay rigid even when costs change within a range","Why price wars break out as soon as one firm cuts its price","Why firms form cartels to fix output quotas and share profits","Why a dominant firm sets the price and smaller rivals follow it"],"answer":0,"explanation":"Rivals follow a price cut but not a rise, so demand is elastic above the current price and inelastic below it; the resulting gap in MR lets costs shift without changing the profit-maximising price.","difficulty":"hard","source":"RBI Grade B Phase 2","questionHi":"अल्पाधिकार का विकुंचित माँग वक्र मॉडल (स्वीजी) मुख्यतः किसे समझाने के लिए प्रयुक्त होता है?","optionsHi":["एक सीमा के भीतर लागतें बदलने पर भी कीमतें अनम्य क्यों रहती हैं","जैसे ही एक फर्म कीमत घटाती है, कीमत युद्ध क्यों छिड़ जाते हैं","फर्में उत्पादन कोटा तय करने और लाभ बाँटने के लिए कार्टेल क्यों बनाती हैं","प्रभावी फर्म कीमत क्यों तय करती है और छोटे प्रतिद्वंद्वी उसका अनुसरण क्यों करते हैं"],"explanationHi":"प्रतिद्वंद्वी कीमत में कटौती का अनुसरण करते हैं पर वृद्धि का नहीं, इसलिए माँग वर्तमान कीमत से ऊपर लोचदार और नीचे बेलोचदार होती है; MR में बना अंतराल लागतों को लाभ-अधिकतम कीमत बदले बिना खिसकने देता है।"},
  {"id":"eco-basics-150","question":"Two firms each choose a 'high' or 'low' price. Whatever its rival does, each firm earns more by choosing the low price, yet both would earn more if both chose high. Without an enforceable agreement, the likely outcome is that:","options":["Both choose the high price, since it maximises their joint profit","Both choose the low price, which leaves both worse off","One firm chooses high and the other low, taking turns each period","No stable outcome exists, since each keeps changing its choice"],"answer":1,"explanation":"Low price is each firm's dominant strategy, so (low, low) is the Nash equilibrium even though (high, high) is better for both: the prisoner's dilemma, which is why cartels are unstable.","difficulty":"very-hard","source":"RBI Grade B Phase 2 · CAT","questionHi":"दो फर्मों में से प्रत्येक ‘ऊँची’ या ‘नीची’ कीमत चुनती है। प्रतिद्वंद्वी जो भी करे, प्रत्येक फर्म नीची कीमत चुनकर अधिक कमाती है, फिर भी यदि दोनों ऊँची कीमत चुनें तो दोनों अधिक कमाएँगी। बिना किसी प्रवर्तनीय समझौते के, संभावित परिणाम यह है कि:","optionsHi":["दोनों ऊँची कीमत चुनती हैं, क्योंकि वह उनका संयुक्त लाभ अधिकतम करती है","दोनों नीची कीमत चुनती हैं, जिससे दोनों की स्थिति बदतर हो जाती है","एक फर्म ऊँची और दूसरी नीची कीमत चुनती है, हर अवधि में बारी-बारी से","कोई स्थिर परिणाम नहीं होता, क्योंकि प्रत्येक अपना चयन बदलती रहती है"],"explanationHi":"नीची कीमत प्रत्येक फर्म की प्रभावी रणनीति है, इसलिए (नीची, नीची) नैश संतुलन है, भले ही (ऊँची, ऊँची) दोनों के लिए बेहतर हो: यह कैदी की दुविधा है, और इसीलिए कार्टेल अस्थिर होते हैं।"},
  {"id":"eco-basics-151","question":"In long-run equilibrium under monopolistic competition, a typical firm:","options":["Earns supernormal profit protected by brand loyalty","Produces at minimum average cost like a competitive firm","Earns normal profit but produces with excess capacity","Faces a perfectly elastic demand curve at the market price"],"answer":2,"explanation":"Free entry removes supernormal profit, so price equals AC; but the firm's demand curve slopes down, so it touches AC to the left of its minimum, leaving unused capacity.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"एकाधिकारी प्रतिस्पर्धा के दीर्घकालिक संतुलन में एक सामान्य फर्म:","optionsHi":["ब्रांड निष्ठा से सुरक्षित असामान्य लाभ कमाती है","प्रतिस्पर्धी फर्म की तरह न्यूनतम औसत लागत पर उत्पादन करती है","सामान्य लाभ कमाती है परंतु अतिरिक्त क्षमता के साथ उत्पादन करती है","बाजार कीमत पर पूर्णतः लोचदार माँग वक्र का सामना करती है"],"explanationHi":"स्वतंत्र प्रवेश असामान्य लाभ को समाप्त कर देता है, इसलिए कीमत AC के बराबर होती है; पर फर्म का माँग वक्र नीचे की ओर ढलान वाला होता है, इसलिए वह AC को उसके न्यूनतम बिंदु के बाईं ओर स्पर्श करता है, जिससे क्षमता अप्रयुक्त रह जाती है।"},
  {"id":"eco-basics-152","question":"Under the law of variable proportions, a rational producer chooses to operate in the stage where:","options":["The average product of the variable input is still rising","The marginal product of the variable input has turned negative","Total product falls as more of the variable input is added","Both AP and MP are falling but MP is still positive"],"answer":3,"explanation":"In Stage I the fixed factor is under-used, so adding the variable input raises its average product; in Stage III MP is negative. The rational stage is Stage II, where AP and MP fall but MP is positive.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"परिवर्ती अनुपातों के नियम के अंतर्गत, एक विवेकशील उत्पादक उस अवस्था में संचालन चुनता है जहाँ:","optionsHi":["परिवर्ती आगत का औसत उत्पाद अभी भी बढ़ रहा हो","परिवर्ती आगत का सीमांत उत्पाद ऋणात्मक हो गया हो","परिवर्ती आगत और जोड़ने पर कुल उत्पाद घटता हो","AP और MP दोनों घट रहे हों पर MP अभी भी धनात्मक हो"],"explanationHi":"अवस्था I में स्थिर साधन का कम उपयोग होता है, इसलिए परिवर्ती आगत जोड़ने से उसका औसत उत्पाद बढ़ता है; अवस्था III में MP ऋणात्मक होता है। विवेकपूर्ण अवस्था अवस्था II है, जहाँ AP और MP घटते हैं पर MP धनात्मक होता है।"},
  {"id":"eco-basics-153","question":"A firm's production function is Q = 5L^0.6 K^0.5. If it doubles both labour and capital, its output:","options":["Rises about 2.14 times: increasing returns to scale","Exactly doubles: constant returns to scale","Rises about 1.52 times: decreasing returns to scale","Rises about 1.1 times: decreasing returns to scale"],"answer":0,"explanation":"Output rises by 2^(0.6+0.5) = 2^1.1 ≈ 2.14 times. Since the exponents sum to more than 1, there are increasing returns to scale; 1.52 is 2^0.6, the effect of doubling labour alone.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"किसी फर्म का उत्पादन फलन Q = 5L^0.6 K^0.5 है। यदि वह श्रम और पूँजी दोनों को दोगुना कर दे, तो उसका उत्पादन:","optionsHi":["लगभग 2.14 गुना बढ़ता है: पैमाने के वर्धमान प्रतिफल","ठीक दोगुना होता है: पैमाने के स्थिर प्रतिफल","लगभग 1.52 गुना बढ़ता है: पैमाने के ह्रासमान प्रतिफल","लगभग 1.1 गुना बढ़ता है: पैमाने के ह्रासमान प्रतिफल"],"explanationHi":"उत्पादन 2^(0.6+0.5) = 2^1.1 ≈ 2.14 गुना बढ़ता है। चूँकि घातांकों का योग 1 से अधिक है, इसलिए पैमाने के वर्धमान प्रतिफल हैं; 1.52 = 2^0.6 है, जो केवल श्रम को दोगुना करने का प्रभाव है।"},
  {"id":"eco-basics-154","question":"A production possibility curve is concave (bowed out) to the origin mainly because:","options":["The economy's resources and technology stay fixed along the curve","The opportunity cost of a good rises as more of it is produced","All resources are fully and efficiently employed along the curve","The economy can produce only two goods with its available resources"],"answer":1,"explanation":"Resources are not equally suited to both goods, so shifting more of them to one good means giving up ever larger amounts of the other. The other options are assumptions behind any PPC, not the reason for its shape.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"उत्पादन संभावना वक्र मूल बिंदु की ओर अवतल (बाहर की ओर उभरा) मुख्यतः इसलिए होता है क्योंकि:","optionsHi":["वक्र के साथ-साथ अर्थव्यवस्था के संसाधन और तकनीक स्थिर रहते हैं","किसी वस्तु का अधिक उत्पादन करने पर उसकी अवसर लागत बढ़ती जाती है","वक्र के साथ-साथ सभी संसाधन पूर्णतः और कुशलता से नियोजित होते हैं","अर्थव्यवस्था अपने उपलब्ध संसाधनों से केवल दो वस्तुएँ ही उत्पादित कर सकती है"],"explanationHi":"संसाधन दोनों वस्तुओं के लिए समान रूप से उपयुक्त नहीं होते, इसलिए उनमें से अधिक को एक वस्तु की ओर ले जाने का अर्थ है दूसरी वस्तु की निरंतर बड़ी मात्रा छोड़ना। अन्य विकल्प किसी भी PPC की मान्यताएँ हैं, उसके आकार का कारण नहीं।"},
  {"id":"eco-basics-155","question":"Two indifference curves of the same consumer cannot intersect because that would violate:","options":["The diminishing marginal rate of substitution along each curve","The completeness of the consumer's preferences","Transitivity, given that more is preferred to less","The convexity of the consumer's budget set"],"answer":2,"explanation":"If two curves crossed, the common point would be equally good as two bundles of which one has more of both goods; by transitivity they would be equal, contradicting the assumption that more is preferred.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक ही उपभोक्ता के दो उदासीनता वक्र एक-दूसरे को नहीं काट सकते क्योंकि ऐसा करना किसका उल्लंघन होगा?","optionsHi":["प्रत्येक वक्र के साथ घटती सीमांत प्रतिस्थापन दर का","उपभोक्ता की अधिमान्यताओं की पूर्णता का","संक्रामिता का, यह मानते हुए कि अधिक को कम की तुलना में वरीयता दी जाती है","उपभोक्ता के बजट समुच्चय की उत्तलता का"],"explanationHi":"यदि दो वक्र कटते, तो उभयनिष्ठ बिंदु दो बंडलों के बराबर अच्छा होता जिनमें से एक में दोनों वस्तुएँ अधिक हैं; संक्रामिता के अनुसार वे बराबर होते, जो इस मान्यता का खंडन करता है कि अधिक को वरीयता दी जाती है।"},
  {"id":"eco-basics-156","question":"A consumer has ₹600 to spend; good X costs ₹20 and good Y costs ₹30 (X on the horizontal axis). If the price of X doubles while income and the price of Y stay the same, the budget line:","options":["Shifts inward in parallel, with both intercepts halved","Pivots inward around the X-intercept, its slope becoming −1/3","Pivots outward around the Y-intercept, its slope becoming −1/3","Pivots inward around the Y-intercept, its slope becoming −4/3"],"answer":3,"explanation":"The Y-intercept stays at 600/30 = 20, while the X-intercept falls from 30 to 15. The slope −Px/Py changes from −2/3 to −40/30 = −4/3.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक उपभोक्ता के पास खर्च करने के लिए ₹600 हैं; वस्तु X की कीमत ₹20 और वस्तु Y की कीमत ₹30 है (X क्षैतिज अक्ष पर)। यदि आय और Y की कीमत समान रहते हुए X की कीमत दोगुनी हो जाए, तो बजट रेखा:","optionsHi":["समानांतर भीतर की ओर खिसकती है, दोनों अंतःखंड आधे हो जाते हैं","X-अंतःखंड के चारों ओर भीतर की ओर घूमती है, उसकी ढलान −1/3 हो जाती है","Y-अंतःखंड के चारों ओर बाहर की ओर घूमती है, उसकी ढलान −1/3 हो जाती है","Y-अंतःखंड के चारों ओर भीतर की ओर घूमती है, उसकी ढलान −4/3 हो जाती है"],"explanationHi":"Y-अंतःखंड 600/30 = 20 पर बना रहता है, जबकि X-अंतःखंड 30 से घटकर 15 हो जाता है। ढलान −Px/Py −2/3 से बदलकर −40/30 = −4/3 हो जाती है।"},
  {"id":"eco-basics-157","question":"An allocation of resources is said to be Pareto efficient when:","options":["No one can be made better off without making someone else worse off","Income and wealth are shared equally among all the members of society","Total output is the largest possible, whatever its distribution among people","Every single person is at least as well off as in the previous allocation"],"answer":0,"explanation":"Pareto efficiency only rules out waste: no reallocation can help someone without hurting another. A highly unequal allocation can still be Pareto efficient, so it says nothing about fairness.","difficulty":"moderate","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"संसाधनों का कोई आवंटन पैरेटो कुशल तब कहा जाता है जब:","optionsHi":["किसी दूसरे को बदतर स्थिति में डाले बिना किसी को भी बेहतर स्थिति में न लाया जा सके","आय और संपत्ति समाज के सभी सदस्यों में समान रूप से बँटी हो","कुल उत्पादन सर्वाधिक संभव हो, चाहे लोगों में उसका वितरण कैसा भी हो","प्रत्येक व्यक्ति कम से कम उतना ही संपन्न हो जितना पिछले आवंटन में था"],"explanationHi":"पैरेटो कुशलता केवल अपव्यय को अस्वीकार करती है: कोई भी पुनर्आवंटन किसी को हानि पहुँचाए बिना किसी की मदद नहीं कर सकता। अत्यंत असमान आवंटन भी पैरेटो कुशल हो सकता है, इसलिए यह निष्पक्षता के बारे में कुछ नहीं बताता।"},
  {"id":"eco-basics-158","question":"A monopolist sells at a price of ₹100, where the price elasticity of demand is 2 (absolute). Its marginal revenue at this point is:","options":["₹200","₹100","₹150","₹50"],"answer":3,"explanation":"MR = P(1 − 1/|e|) = 100 × (1 − 0.5) = ₹50. MR equals price only under perfect competition; a monopolist never produces where demand is inelastic, since MR would be negative there.","difficulty":"hard","source":"RBI Grade B Phase 2","questionHi":"एक एकाधिकारी ₹100 की कीमत पर बेचता है, जहाँ माँग की कीमत लोच 2 (निरपेक्ष) है। इस बिंदु पर उसका सीमांत राजस्व है:","optionsHi":["₹200","₹100","₹150","₹50"],"explanationHi":"MR = P(1 − 1/|e|) = 100 × (1 − 0.5) = ₹50। MR केवल पूर्ण प्रतिस्पर्धा में कीमत के बराबर होता है; एकाधिकारी कभी वहाँ उत्पादन नहीं करता जहाँ माँग बेलोचदार हो, क्योंकि वहाँ MR ऋणात्मक होगा।"},
  {"id":"eco-basics-159","question":"Government debt is 60% of GDP, the primary deficit is 2% of GDP, the nominal interest rate on debt is 7% and nominal GDP grows at 10%. Using Δd = pd + d(r − g)/(1 + g), the debt ratio over the year changes by about:","options":["+0.36 percentage points","+3.80 percentage points","−1.64 percentage points","+2.00 percentage points"],"answer":0,"explanation":"Δd = 2 + 60 × (0.07 − 0.10)/1.10 ≈ 2 − 1.64 = +0.36 points. Because growth exceeds the interest rate, the debt ratio rises far less than the primary deficit alone suggests.","difficulty":"very-hard","source":"RBI Grade B Phase 2 · UPSC Prelims","questionHi":"सरकारी ऋण GDP का 60% है, प्राथमिक घाटा GDP का 2% है, ऋण पर सांकेतिक ब्याज दर 7% है और सांकेतिक GDP 10% की दर से बढ़ता है। Δd = pd + d(r − g)/(1 + g) का उपयोग करने पर, वर्ष के दौरान ऋण अनुपात लगभग कितना बदलता है?","optionsHi":["+0.36 प्रतिशत अंक","+3.80 प्रतिशत अंक","−1.64 प्रतिशत अंक","+2.00 प्रतिशत अंक"],"explanationHi":"Δd = 2 + 60 × (0.07 − 0.10)/1.10 ≈ 2 − 1.64 = +0.36 अंक। चूँकि वृद्धि दर ब्याज दर से अधिक है, ऋण अनुपात उतना नहीं बढ़ता जितना अकेले प्राथमिक घाटे से लगता है।"},
  {"id":"eco-basics-160","question":"In a year, tax revenue grows by 15% while nominal GDP grows by 10%; part of the extra revenue came from new tax rates announced in the budget. Which statement is correct?","options":["Tax elasticity is 1.5, and buoyancy would exclude the effect of the new rates","Tax buoyancy is 1.5; elasticity would exclude the effect of the new rates","Both tax buoyancy and tax elasticity are 0.67 in this case","Tax buoyancy is 0.67, since revenue grew more slowly than GDP"],"answer":1,"explanation":"Buoyancy = 15/10 = 1.5 and includes revenue from discretionary changes in rates and base. Elasticity measures the automatic response of revenue to income with the tax structure unchanged.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"एक वर्ष में कर राजस्व 15% बढ़ता है जबकि सांकेतिक GDP 10% बढ़ता है; अतिरिक्त राजस्व का एक भाग बजट में घोषित नई कर दरों से आया। कौन-सा कथन सही है?","optionsHi":["कर लोच 1.5 है, और उछाल (बुओयेन्सी) नई दरों के प्रभाव को शामिल नहीं करेगा","कर उछाल 1.5 है; लोच नई दरों के प्रभाव को शामिल नहीं करेगी","इस मामले में कर उछाल और कर लोच दोनों 0.67 हैं","कर उछाल 0.67 है, क्योंकि राजस्व GDP से धीमी गति से बढ़ा"],"explanationHi":"उछाल = 15/10 = 1.5 और इसमें दरों तथा आधार में विवेकाधीन परिवर्तनों से प्राप्त राजस्व शामिल होता है। लोच कर संरचना को अपरिवर्तित रखते हुए आय के प्रति राजस्व की स्वचालित प्रतिक्रिया को मापती है।"},
  {"id":"eco-basics-161","question":"The Laffer curve suggests that:","options":["Higher tax rates always raise total revenue for the government","Tax revenue depends only on the tax base, not on the tax rates","Beyond some point, higher tax rates can reduce total revenue","Indirect taxes collect more revenue than direct taxes at any rate"],"answer":2,"explanation":"At zero and at 100% tax rates revenue is zero, so revenue peaks at some rate in between; above it, higher rates shrink or drive away the tax base enough to lower revenue.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"लैफर वक्र सुझाता है कि:","optionsHi":["ऊँची कर दरें सदैव सरकार के कुल राजस्व को बढ़ाती हैं","कर राजस्व केवल कर आधार पर निर्भर करता है, कर दरों पर नहीं","एक बिंदु के बाद ऊँची कर दरें कुल राजस्व घटा सकती हैं","अप्रत्यक्ष कर किसी भी दर पर प्रत्यक्ष करों से अधिक राजस्व जुटाते हैं"],"explanationHi":"शून्य और 100% कर दरों पर राजस्व शून्य होता है, इसलिए राजस्व बीच की किसी दर पर अधिकतम होता है; उससे ऊपर ऊँची दरें कर आधार को इतना सिकोड़ देती हैं या भगा देती हैं कि राजस्व घट जाता है।"},
  {"id":"eco-basics-162","question":"A manufacturer sells goods worth ₹1,000 plus 18% GST to a retailer. The retailer adds value of ₹500 and sells them for ₹1,500 plus 18% GST to a consumer. The retailer's net GST payment in cash, and the total GST collected by the government, are:","options":["₹270 and ₹450","₹90 and ₹180","₹270 and ₹270","₹90 and ₹270"],"answer":3,"explanation":"The retailer owes 18% of ₹1,500 = ₹270 but claims credit for the ₹180 paid on purchases, paying ₹90. Total tax = 180 + 90 = ₹270, i.e. 18% of the final price: input tax credit removes the cascading effect.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"एक विनिर्माता एक खुदरा विक्रेता को ₹1,000 की वस्तुएँ और उस पर 18% GST के साथ बेचता है। खुदरा विक्रेता ₹500 का मूल्य वर्धन करता है और उन्हें एक उपभोक्ता को ₹1,500 और उस पर 18% GST के साथ बेचता है। खुदरा विक्रेता का नकद में शुद्ध GST भुगतान और सरकार द्वारा वसूला गया कुल GST हैं:","optionsHi":["₹270 और ₹450","₹90 और ₹180","₹270 और ₹270","₹90 और ₹270"],"explanationHi":"खुदरा विक्रेता पर ₹1,500 का 18% = ₹270 बनता है, पर वह खरीद पर चुकाए गए ₹180 का क्रेडिट लेता है, इसलिए ₹90 चुकाता है। कुल कर = 180 + 90 = ₹270, यानी अंतिम कीमत का 18%: आगत कर क्रेडिट कर-पर-कर (कैस्केडिंग) प्रभाव को समाप्त कर देता है।"},
  {"id":"eco-basics-163","question":"Match: 1. Consolidated Fund of India 2. Contingency Fund of India 3. Public Account of India 4. Annual Financial Statement; a. Article 112 b. Article 266(1) c. Article 266(2) d. Article 267","options":["1-c, 2-d, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-b, 2-a, 3-c, 4-d","1-d, 2-b, 3-c, 4-a"],"answer":1,"explanation":"Article 266(1) creates the Consolidated Fund, 266(2) the Public Account, Article 267 the Contingency Fund, and Article 112 requires the Annual Financial Statement (the budget).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मिलान कीजिए: 1. भारत की संचित निधि 2. भारत की आकस्मिकता निधि 3. भारत का लोक लेखा 4. वार्षिक वित्तीय विवरण; a. अनुच्छेद 112 b. अनुच्छेद 266(1) c. अनुच्छेद 266(2) d. अनुच्छेद 267","optionsHi":["1-c, 2-d, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-b, 2-a, 3-c, 4-d","1-d, 2-b, 3-c, 4-a"],"explanationHi":"अनुच्छेद 266(1) संचित निधि बनाता है, 266(2) लोक लेखा, अनुच्छेद 267 आकस्मिकता निधि, और अनुच्छेद 112 वार्षिक वित्तीय विवरण (बजट) अनिवार्य करता है।"},
  {"id":"eco-basics-164","question":"Which of these is NOT charged on the Consolidated Fund of India, and so must be voted by the Lok Sabha?","options":["Salary and allowances of the President","Salaries and allowances of Supreme Court judges","Interest and other charges on the debt of the Union","Salaries and allowances of Union ministers"],"answer":3,"explanation":"Article 112(3) lists charged items such as the President's emoluments, Supreme Court judges' salaries, the CAG's salary and debt charges; these are discussed but not voted. Ministers' salaries are voted expenditure.","difficulty":"hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-सा भारत की संचित निधि पर भारित नहीं है, और इसलिए लोकसभा द्वारा मतदान से पारित किया जाना आवश्यक है?","optionsHi":["राष्ट्रपति का वेतन और भत्ते","सर्वोच्च न्यायालय के न्यायाधीशों के वेतन और भत्ते","संघ के ऋण पर ब्याज और अन्य भार","संघ के मंत्रियों के वेतन और भत्ते"],"explanationHi":"अनुच्छेद 112(3) में राष्ट्रपति की परिलब्धियाँ, सर्वोच्च न्यायालय के न्यायाधीशों के वेतन, CAG का वेतन और ऋण भार जैसी भारित मदें सूचीबद्ध हैं; इन पर चर्चा होती है पर मतदान नहीं। मंत्रियों के वेतन मतदेय व्यय हैं।"},
  {"id":"eco-basics-165","question":"Match the cut motion with its form: 1. Policy cut 2. Economy cut 3. Token cut; a. Reduce the demand by ₹100 to voice a specific grievance b. Reduce the demand to ₹1, signalling disapproval of the policy behind it c. Reduce the demand by a stated amount that represents a possible saving","options":["1-a, 2-c, 3-b","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a"],"answer":2,"explanation":"A policy cut reduces the demand to ₹1, an economy cut reduces it by a specified amount, and a token cut reduces it by ₹100 to air a particular grievance.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कटौती प्रस्ताव का उसके रूप से मिलान कीजिए: 1. नीति कटौती 2. मितव्ययिता कटौती 3. सांकेतिक कटौती; a. किसी विशिष्ट शिकायत को उठाने के लिए माँग में ₹100 की कमी करना b. माँग को घटाकर ₹1 करना, जो उसके पीछे की नीति के प्रति असहमति का संकेत है c. माँग में एक निर्दिष्ट राशि की कमी करना जो संभावित बचत को दर्शाती है","optionsHi":["1-a, 2-c, 3-b","1-b, 2-a, 3-c","1-b, 2-c, 3-a","1-c, 2-b, 3-a"],"explanationHi":"नीति कटौती माँग को घटाकर ₹1 कर देती है, मितव्ययिता कटौती उसे एक निर्दिष्ट राशि से घटाती है, और सांकेतिक कटौती किसी विशेष शिकायत को उठाने के लिए उसे ₹100 घटाती है।"},
  {"id":"eco-basics-166","question":"A 'vote on account' allows the government to:","options":["Withdraw funds for part of the year before the budget is passed","Spend from the Contingency Fund without any later approval from Parliament","Pass all remaining demands for grants together without discussing them","Change tax rates during the year without bringing a fresh Finance Bill"],"answer":0,"explanation":"Under Article 116, the Lok Sabha can grant an advance for part of the year so that spending can continue before the full budget is passed. Putting all remaining demands to vote together is the guillotine.","difficulty":"hard","source":"UPSC Prelims","questionHi":"‘लेखानुदान’ सरकार को अनुमति देता है कि वह:","optionsHi":["बजट पारित होने से पहले वर्ष के एक भाग के लिए निधि निकाल सके","संसद की बाद की किसी स्वीकृति के बिना आकस्मिकता निधि से व्यय कर सके","शेष सभी अनुदान माँगों को बिना चर्चा के एक साथ पारित कर सके","नया वित्त विधेयक लाए बिना वर्ष के दौरान कर दरें बदल सके"],"explanationHi":"अनुच्छेद 116 के अंतर्गत लोकसभा वर्ष के एक भाग के लिए अग्रिम अनुदान दे सकती है ताकि पूरा बजट पारित होने से पहले व्यय जारी रह सके। शेष सभी माँगों को एक साथ मतदान के लिए रखना गिलोटिन है।"},
  {"id":"eco-basics-167","question":"How many of these statements about Union Budget reforms are correct? I. The Railway Budget was merged with the Union Budget from 2017–18. II. The date of presenting the Union Budget was advanced to 1 February from 2017. III. The distinction between plan and non-plan expenditure was removed from 2017–18. IV. An Outcome Budget was first presented in 2005–06.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The 2017 reforms merged the rail budget, advanced the budget to 1 February and replaced plan/non-plan with revenue/capital classification; outcome budgeting began in 2005–06.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"केंद्रीय बजट सुधारों के बारे में इनमें से कितने कथन सही हैं? I. रेल बजट को 2017–18 से केंद्रीय बजट में मिला दिया गया। II. केंद्रीय बजट प्रस्तुत करने की तिथि 2017 से 1 फरवरी कर दी गई। III. 2017–18 से योजना और गैर-योजना व्यय का भेद समाप्त कर दिया गया। IV. परिणाम बजट पहली बार 2005–06 में प्रस्तुत किया गया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। 2017 के सुधारों ने रेल बजट को मिलाया, बजट को 1 फरवरी तक आगे किया और योजना/गैर-योजना की जगह राजस्व/पूँजीगत वर्गीकरण लागू किया; परिणाम बजटिंग 2005–06 में शुरू हुई।"},
  {"id":"eco-basics-168","question":"In the Fifteenth Finance Commission's formula for sharing the divisible pool among States, which criterion carried the highest weight?","options":["Population (2011 Census)","Income distance","Area","Demographic performance"],"answer":1,"explanation":"Income distance carried 45%, favouring poorer States; population and area had 15% each, forest and ecology 10%, demographic performance 12.5% and tax effort 2.5%.","difficulty":"hard","source":"UPSC Prelims","questionHi":"राज्यों के बीच विभाज्य पूल के बँटवारे के पंद्रहवें वित्त आयोग के सूत्र में किस मापदंड को सबसे अधिक भार दिया गया?","optionsHi":["जनसंख्या (2011 की जनगणना)","आय अंतर","क्षेत्रफल","जनांकिकीय प्रदर्शन"],"explanationHi":"आय अंतर को 45% भार मिला, जो गरीब राज्यों के पक्ष में है; जनसंख्या और क्षेत्रफल को 15%-15%, वन और पारिस्थितिकी को 10%, जनांकिकीय प्रदर्शन को 12.5% और कर प्रयास को 2.5%।"},
  {"id":"eco-basics-169","question":"Assertion (A): States get no share of the cesses and surcharges levied by the Union Government. Reason (R): Cesses and surcharges are excluded from the divisible pool of central taxes under Article 270.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Only taxes in the divisible pool are shared according to the Finance Commission's award; cesses and surcharges lie outside it, so their growing share reduces what States receive.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"अभिकथन (A): केंद्र सरकार द्वारा लगाए गए उपकरों और अधिभारों में राज्यों को कोई हिस्सा नहीं मिलता। कारण (R): अनुच्छेद 270 के अंतर्गत उपकर और अधिभार केंद्रीय करों के विभाज्य पूल से बाहर रखे जाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"केवल विभाज्य पूल में शामिल कर ही वित्त आयोग के निर्णय के अनुसार बाँटे जाते हैं; उपकर और अधिभार उसके बाहर हैं, इसलिए उनका बढ़ता हिस्सा राज्यों को मिलने वाली राशि को घटाता है।"},
  {"id":"eco-basics-170","question":"Match the Article with its subject: 1. Article 270 2. Article 275 3. Article 282 4. Article 293; a. Borrowing by States b. Grants for any public purpose, even outside the Union's legislative field c. Statutory grants-in-aid to States in need of help d. Taxes levied by the Union and shared with States","options":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"Article 270 covers sharing of Union taxes, 275 statutory grants on Finance Commission advice, 282 discretionary grants for any public purpose, and 293 borrowing by States.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद का उसके विषय से मिलान कीजिए: 1. अनुच्छेद 270 2. अनुच्छेद 275 3. अनुच्छेद 282 4. अनुच्छेद 293; a. राज्यों द्वारा उधार लेना b. किसी भी सार्वजनिक प्रयोजन के लिए अनुदान, चाहे वह संघ के विधायी क्षेत्र के बाहर हो c. सहायता की आवश्यकता वाले राज्यों को सांविधिक सहायता अनुदान d. संघ द्वारा लगाए गए और राज्यों के साथ साझा किए जाने वाले कर","optionsHi":["1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a"],"explanationHi":"अनुच्छेद 270 संघ के करों के बँटवारे से संबंधित है, 275 वित्त आयोग की सलाह पर सांविधिक अनुदान, 282 किसी भी सार्वजनिक प्रयोजन के लिए विवेकाधीन अनुदान, और 293 राज्यों द्वारा उधार लेने से।"},
  {"id":"eco-basics-171","question":"A government's revenue deficit is 3.5% of GDP, and grants it gives for the creation of capital assets are 1.2% of GDP. Its effective revenue deficit is:","options":["4.7% of GDP","1.2% of GDP","2.3% of GDP","3.5% of GDP"],"answer":2,"explanation":"Effective revenue deficit = revenue deficit − grants for creation of capital assets = 3.5 − 1.2 = 2.3% of GDP. Such grants are revenue spending on paper but create assets, so they are taken out.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"किसी सरकार का राजस्व घाटा GDP का 3.5% है, और पूँजीगत परिसंपत्तियों के सृजन के लिए दिए गए उसके अनुदान GDP के 1.2% हैं। उसका प्रभावी राजस्व घाटा है:","optionsHi":["GDP का 4.7%","GDP का 1.2%","GDP का 2.3%","GDP का 3.5%"],"explanationHi":"प्रभावी राजस्व घाटा = राजस्व घाटा − पूँजीगत परिसंपत्तियों के सृजन के लिए अनुदान = 3.5 − 1.2 = GDP का 2.3%। ऐसे अनुदान कागज पर राजस्व व्यय हैं पर परिसंपत्तियाँ बनाते हैं, इसलिए उन्हें घटा दिया जाता है।"},
  {"id":"eco-basics-172","question":"A tax takes ₹10,000 from an income of ₹1 lakh and ₹30,000 from an income of ₹2 lakh. This tax is:","options":["Progressive, as the average tax rate rises with income","Proportional, as the tax paid rises along with income","Regressive, as the marginal tax rate falls with income","Proportional, as the marginal tax rate stays constant"],"answer":0,"explanation":"The average rate rises from 10% to 15%, so the tax is progressive; the marginal rate on the extra ₹1 lakh is 20%. A tax that merely rises in rupees with income can still be proportional or regressive.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"एक कर ₹1 लाख की आय में से ₹10,000 और ₹2 लाख की आय में से ₹30,000 लेता है। यह कर है:","optionsHi":["प्रगतिशील, क्योंकि आय के साथ औसत कर दर बढ़ती है","आनुपातिक, क्योंकि आय के साथ चुकाया गया कर बढ़ता है","प्रतिगामी, क्योंकि आय के साथ सीमांत कर दर घटती है","आनुपातिक, क्योंकि सीमांत कर दर स्थिर रहती है"],"explanationHi":"औसत दर 10% से बढ़कर 15% हो जाती है, इसलिए कर प्रगतिशील है; अतिरिक्त ₹1 लाख पर सीमांत दर 20% है। जो कर केवल रुपयों में आय के साथ बढ़ता है, वह फिर भी आनुपातिक या प्रतिगामी हो सकता है।"},
  {"id":"eco-basics-173","question":"Under a hypothetical slab system, income up to ₹3 lakh is tax-free, income from ₹3 lakh to ₹6 lakh is taxed at 5% and income from ₹6 lakh to ₹9 lakh at 10%. For an income of ₹8 lakh, the tax, average rate and marginal rate are:","options":["₹80,000; average 10%; marginal 10%","₹35,000; average 4.4%; marginal 10%","₹50,000; average 6.3%; marginal 10%","₹35,000; average 10%; marginal 4.4%"],"answer":1,"explanation":"Tax = 5% of ₹3 lakh + 10% of ₹2 lakh = 15,000 + 20,000 = ₹35,000, an average rate of 35,000/8,00,000 ≈ 4.4%. The marginal rate is the rate on the last rupee, 10%; charging 10% on all of it is the common slab error.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक काल्पनिक स्लैब प्रणाली में ₹3 लाख तक की आय कर-मुक्त है, ₹3 लाख से ₹6 लाख तक की आय पर 5% और ₹6 लाख से ₹9 लाख तक की आय पर 10% कर लगता है। ₹8 लाख की आय के लिए कर, औसत दर और सीमांत दर हैं:","optionsHi":["₹80,000; औसत 10%; सीमांत 10%","₹35,000; औसत 4.4%; सीमांत 10%","₹50,000; औसत 6.3%; सीमांत 10%","₹35,000; औसत 10%; सीमांत 4.4%"],"explanationHi":"कर = ₹3 लाख का 5% + ₹2 लाख का 10% = 15,000 + 20,000 = ₹35,000, यानी औसत दर 35,000/8,00,000 ≈ 4.4%। सीमांत दर अंतिम रुपये पर लगने वाली दर है, 10%; पूरी आय पर 10% लगा देना सामान्य स्लैब त्रुटि है।"},
  {"id":"eco-basics-174","question":"Zero-based budgeting requires that:","options":["Every department's budget is kept at zero growth in nominal terms","The budget is balanced, with total spending equal to total receipts","Every item of spending is justified afresh from a zero base","Spending on any scheme with zero outcomes in the past is stopped"],"answer":2,"explanation":"Incremental budgeting takes last year's allocation as given and argues only about the increase; zero-based budgeting starts from zero and makes each activity justify its whole cost.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"शून्य-आधारित बजटिंग के लिए आवश्यक है कि:","optionsHi":["प्रत्येक विभाग का बजट सांकेतिक रूप में शून्य वृद्धि पर रखा जाए","बजट संतुलित हो, कुल व्यय कुल प्राप्तियों के बराबर हो","व्यय की प्रत्येक मद को शून्य आधार से नए सिरे से उचित ठहराया जाए","अतीत में शून्य परिणाम देने वाली किसी भी योजना पर व्यय रोक दिया जाए"],"explanationHi":"वृद्धिशील बजटिंग में पिछले वर्ष का आवंटन मान लिया जाता है और केवल वृद्धि पर बहस होती है; शून्य-आधारित बजटिंग शून्य से शुरू होती है और प्रत्येक गतिविधि से अपनी पूरी लागत उचित ठहराने को कहती है।"},
  {"id":"eco-basics-175","question":"According to the Ricardian equivalence proposition, a tax cut financed by government borrowing, with spending unchanged:","options":["Raises consumption by the full amount of the tax cut","Leaves consumption unchanged, as people save for future taxes","Raises interest rates and crowds out private investment","Raises consumption by the tax cut multiplied by the spending multiplier"],"answer":1,"explanation":"Forward-looking households see that today's borrowing means higher taxes later, so they save the whole tax cut; private saving rises exactly as public saving falls, and demand is unchanged.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"रिकार्डियन तुल्यता प्रस्थापना के अनुसार, सरकारी उधारी से वित्तपोषित और व्यय अपरिवर्तित रहते हुए किया गया कर कटौती:","optionsHi":["उपभोग को कर कटौती की पूरी राशि से बढ़ाती है","उपभोग को अपरिवर्तित रखती है, क्योंकि लोग भविष्य के करों के लिए बचत करते हैं","ब्याज दरें बढ़ाती है और निजी निवेश को बाहर कर देती है","उपभोग को कर कटौती गुणा व्यय गुणक से बढ़ाती है"],"explanationHi":"दूरदर्शी परिवार देखते हैं कि आज की उधारी का अर्थ बाद में ऊँचे कर हैं, इसलिए वे पूरी कर कटौती बचा लेते हैं; निजी बचत ठीक उतनी बढ़ती है जितनी सार्वजनिक बचत घटती है, और माँग अपरिवर्तित रहती है।"},
  {"id":"eco-basics-176","question":"Assertion (A): A government can run a fiscal deficit in the same year that it runs a primary surplus. Reason (R): The fiscal deficit equals the primary deficit plus interest payments.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"If interest payments exceed the primary surplus, the fiscal deficit is positive: for example, a primary surplus of 1% of GDP with interest of 3% of GDP gives a fiscal deficit of 2%.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"अभिकथन (A): कोई सरकार उसी वर्ष राजकोषीय घाटा चला सकती है जिस वर्ष वह प्राथमिक अधिशेष चला रही हो। कारण (R): राजकोषीय घाटा प्राथमिक घाटे और ब्याज भुगतान के योग के बराबर होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"यदि ब्याज भुगतान प्राथमिक अधिशेष से अधिक है, तो राजकोषीय घाटा धनात्मक होता है: उदाहरण के लिए, GDP के 1% का प्राथमिक अधिशेष और GDP के 3% का ब्याज 2% का राजकोषीय घाटा देता है।"},
  {"id":"eco-basics-177","question":"The Coase theorem states that, if property rights are clearly defined and bargaining costs are negligible:","options":["The government must impose a tax equal to the external cost","The polluter must always be made to pay for the damage caused","Private bargaining reaches efficiency, whoever holds the rights","An externality can be removed only by setting up a public enterprise"],"answer":2,"explanation":"With costless bargaining, the parties will trade until the efficient level of the activity is reached; the assignment of rights affects who pays whom, not the efficient outcome. A tax equal to marginal external cost is the Pigouvian solution.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"कोज़ प्रमेय कहता है कि, यदि संपत्ति अधिकार स्पष्ट रूप से परिभाषित हों और मोल-भाव की लागत नगण्य हो:","optionsHi":["सरकार को बाह्य लागत के बराबर कर लगाना ही होगा","प्रदूषक को सदैव हुई क्षति की कीमत चुकानी ही होगी","निजी मोल-भाव कुशलता तक पहुँच जाता है, अधिकार चाहे किसी के पास हों","बाह्यता को केवल सार्वजनिक उद्यम स्थापित करके ही हटाया जा सकता है"],"explanationHi":"बिना लागत वाले मोल-भाव में पक्षकार तब तक व्यापार करेंगे जब तक गतिविधि का कुशल स्तर न आ जाए; अधिकारों का आवंटन यह प्रभावित करता है कि कौन किसे भुगतान करता है, कुशल परिणाम को नहीं। सीमांत बाह्य लागत के बराबर कर पिगू समाधान है।"},
  {"id":"eco-basics-178","question":"Fish in the open sea, which anyone may catch and whose stock is depleted by each catch, are an example of goods that are:","options":["Non-rival and non-excludable, i.e. public goods","Excludable but non-rival, i.e. club goods","Rival but non-excludable, i.e. common resources","Rival and excludable, i.e. private goods"],"answer":2,"explanation":"One person's catch leaves less for others (rival), but no one can easily be kept out (non-excludable). Such common resources tend to be over-used: the tragedy of the commons.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"खुले समुद्र की मछलियाँ, जिन्हें कोई भी पकड़ सकता है और जिनका भंडार प्रत्येक पकड़ से घटता है, किस प्रकार की वस्तुओं का उदाहरण हैं?","optionsHi":["अप्रतिद्वंद्वी और अबहिष्करणीय, अर्थात सार्वजनिक वस्तुएँ","बहिष्करणीय परंतु अप्रतिद्वंद्वी, अर्थात क्लब वस्तुएँ","प्रतिद्वंद्वी परंतु अबहिष्करणीय, अर्थात साझा संसाधन","प्रतिद्वंद्वी और बहिष्करणीय, अर्थात निजी वस्तुएँ"],"explanationHi":"एक व्यक्ति की पकड़ दूसरों के लिए कम छोड़ती है (प्रतिद्वंद्वी), पर किसी को आसानी से रोका नहीं जा सकता (अबहिष्करणीय)। ऐसे साझा संसाधनों का अत्यधिक उपयोग होने की प्रवृत्ति होती है: साझे की त्रासदी।"},
  {"id":"eco-basics-179","question":"After buying a comprehensive car insurance policy, a driver starts parking carelessly in unsafe places. Economists call this:","options":["Adverse selection","Free riding","Signalling","Moral hazard"],"answer":3,"explanation":"Moral hazard is a change in behaviour after a contract, because the insured no longer bears the full cost of risk. Adverse selection arises before the contract, when riskier people are more likely to buy insurance.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"एक व्यापक कार बीमा पॉलिसी खरीदने के बाद एक चालक असुरक्षित स्थानों पर लापरवाही से कार खड़ी करने लगता है। अर्थशास्त्री इसे कहते हैं:","optionsHi":["प्रतिकूल चयन","मुफ्तखोरी","संकेतन","नैतिक जोखिम"],"explanationHi":"नैतिक जोखिम अनुबंध के बाद व्यवहार में परिवर्तन है, क्योंकि बीमित व्यक्ति अब जोखिम की पूरी लागत वहन नहीं करता। प्रतिकूल चयन अनुबंध से पहले उत्पन्न होता है, जब अधिक जोखिम वाले लोगों के बीमा खरीदने की संभावना अधिक होती है।"},
  {"id":"eco-basics-180","question":"In the Union Budget, which of these is NOT shown as a source of financing the fiscal deficit?","options":["Market borrowings through dated securities","Disinvestment proceeds from public sector firms","Securities issued against small savings","Net external assistance from bilateral and multilateral lenders"],"answer":1,"explanation":"Disinvestment is a non-debt capital receipt counted above the line, so it reduces the fiscal deficit; the deficit itself is financed by borrowing from the market, small savings, external sources and similar items.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"केंद्रीय बजट में इनमें से कौन-सा राजकोषीय घाटे के वित्तपोषण के स्रोत के रूप में नहीं दिखाया जाता?","optionsHi":["दिनांकित प्रतिभूतियों के माध्यम से बाजार उधारियाँ","सार्वजनिक क्षेत्र की फर्मों से विनिवेश की आय","लघु बचतों के बदले जारी प्रतिभूतियाँ","द्विपक्षीय और बहुपक्षीय ऋणदाताओं से शुद्ध बाह्य सहायता"],"explanationHi":"विनिवेश एक गैर-ऋण पूँजीगत प्राप्ति है जिसे रेखा के ऊपर गिना जाता है, इसलिए वह राजकोषीय घाटे को घटाता है; घाटे का वित्तपोषण स्वयं बाजार से उधारी, लघु बचत, बाह्य स्रोतों और ऐसी ही मदों से होता है।"},
  {"id":"eco-basics-181","question":"The FRBM Review Committee (2017), chaired by N. K. Singh, recommended which variable as the primary anchor of fiscal policy?","options":["The general government debt-to-GDP ratio","The Centre's fiscal deficit as a share of GDP","The revenue deficit as a share of GDP","The primary deficit as a share of GDP"],"answer":0,"explanation":"The committee proposed a general government debt ceiling of 60% of GDP (40% Centre, 20% States) as the anchor, with the fiscal deficit as the operational target to reach it.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"एन. के. सिंह की अध्यक्षता वाली FRBM समीक्षा समिति (2017) ने राजकोषीय नीति के प्राथमिक आधार के रूप में किस चर की अनुशंसा की?","optionsHi":["सामान्य सरकार का ऋण-GDP अनुपात","GDP के हिस्से के रूप में केंद्र का राजकोषीय घाटा","GDP के हिस्से के रूप में राजस्व घाटा","GDP के हिस्से के रूप में प्राथमिक घाटा"],"explanationHi":"समिति ने आधार के रूप में GDP के 60% की सामान्य सरकार ऋण सीमा (40% केंद्र, 20% राज्य) प्रस्तावित की, और उसे प्राप्त करने के लिए राजकोषीय घाटे को परिचालन लक्ष्य रखा।"},
  {"id":"eco-basics-182","question":"An economy produces only apples and oranges. Year 1: 10 kg of apples at ₹5 and 20 kg of oranges at ₹2. Year 2: 12 kg of apples at ₹6 and 25 kg of oranges at ₹3. With Year 1 as the base, real GDP growth in Year 2 is about:","options":["63.3%","10.0%","22.2%","33.6%"],"answer":2,"explanation":"Real GDP in Year 2 at Year 1 prices = 12×5 + 25×2 = ₹110, against ₹90 in Year 1, a growth of 22.2%. Nominal GDP grew 147/90 − 1 = 63.3%, and the deflator rose about 33.6%.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक अर्थव्यवस्था केवल सेब और संतरे उत्पादित करती है। वर्ष 1: ₹5 पर 10 kg सेब और ₹2 पर 20 kg संतरे। वर्ष 2: ₹6 पर 12 kg सेब और ₹3 पर 25 kg संतरे। वर्ष 1 को आधार मानने पर, वर्ष 2 में वास्तविक GDP वृद्धि लगभग है:","optionsHi":["63.3%","10.0%","22.2%","33.6%"],"explanationHi":"वर्ष 1 की कीमतों पर वर्ष 2 का वास्तविक GDP = 12×5 + 25×2 = ₹110, जबकि वर्ष 1 में ₹90, यानी 22.2% की वृद्धि। सांकेतिक GDP 147/90 − 1 = 63.3% बढ़ा, और अपस्फीतिकारक लगभग 33.6% बढ़ा।"},
  {"id":"eco-basics-183","question":"An economy invests 30% of its GDP and its incremental capital-output ratio (ICOR) is 4. By the Harrod–Domar relation, its growth rate is, and to grow at 9% with the same ICOR it would need an investment rate of:","options":["7.5%; 36%","7.5%; 40.5%","12.0%; 36%","7.5%; 33%"],"answer":0,"explanation":"g = s/ICOR = 30/4 = 7.5%. To grow at 9%, investment must be 9 × 4 = 36% of GDP. Multiplying by 4.5 or adding the growth gap to 30% are the usual slips.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"एक अर्थव्यवस्था अपने GDP का 30% निवेश करती है और उसका वृद्धिशील पूँजी-उत्पाद अनुपात (ICOR) 4 है। हैरोड–डोमर संबंध से उसकी वृद्धि दर कितनी है, और उसी ICOR के साथ 9% की दर से बढ़ने के लिए उसे कितनी निवेश दर चाहिए?","optionsHi":["7.5%; 36%","7.5%; 40.5%","12.0%; 36%","7.5%; 33%"],"explanationHi":"g = s/ICOR = 30/4 = 7.5%। 9% की दर से बढ़ने के लिए निवेश GDP का 9 × 4 = 36% होना चाहिए। 4.5 से गुणा करना या वृद्धि के अंतर को 30% में जोड़ देना सामान्य चूकें हैं।"},
  {"id":"eco-basics-184","question":"A country's GDP grows at 5.5% a year and its population at 2% a year. Using the rule of 70, its per capita income will double in about:","options":["13 years","20 years","35 years","10 years"],"answer":1,"explanation":"Per capita income grows at about 5.5 − 2 = 3.5% a year, so it doubles in roughly 70/3.5 = 20 years. Using total GDP growth gives 13 years, which ignores population growth.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"किसी देश का GDP प्रति वर्ष 5.5% की दर से और जनसंख्या प्रति वर्ष 2% की दर से बढ़ती है। 70 के नियम से उसकी प्रति व्यक्ति आय लगभग कितने वर्षों में दोगुनी हो जाएगी?","optionsHi":["13 वर्ष","20 वर्ष","35 वर्ष","10 वर्ष"],"explanationHi":"प्रति व्यक्ति आय लगभग 5.5 − 2 = 3.5% प्रति वर्ष की दर से बढ़ती है, इसलिए यह लगभग 70/3.5 = 20 वर्षों में दोगुनी होती है। कुल GDP वृद्धि का उपयोग करने पर 13 वर्ष आता है, जो जनसंख्या वृद्धि की उपेक्षा करता है।"},
  {"id":"eco-basics-185","question":"A population has 300 people aged 0–14, 600 aged 15–64 and 100 aged 65 and above. Its total dependency ratio is:","options":["40.0%","50.0%","16.7%","66.7%"],"answer":3,"explanation":"Dependency ratio = (0–14 + 65+)/(15–64) = 400/600 ≈ 66.7%. 50% is only the young-age ratio and 16.7% the old-age ratio; 40% wrongly divides by the whole population.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"एक जनसंख्या में 0–14 आयु के 300 लोग, 15–64 आयु के 600 और 65 तथा उससे अधिक आयु के 100 लोग हैं। इसका कुल निर्भरता अनुपात है:","optionsHi":["40.0%","50.0%","16.7%","66.7%"],"explanationHi":"निर्भरता अनुपात = (0–14 + 65+)/(15–64) = 400/600 ≈ 66.7%। 50% केवल बाल-आयु अनुपात है और 16.7% वृद्ध-आयु अनुपात; 40% गलती से पूरी जनसंख्या से भाग देता है।"},
  {"id":"eco-basics-186","question":"Of 1,000 persons aged 15 and above, 470 are working and 30 are not working but are seeking or available for work. The labour force participation rate, worker population ratio and unemployment rate are:","options":["50%, 47% and 6%","50%, 47% and 3%","47%, 50% and 6%","50%, 44% and 6.4%"],"answer":0,"explanation":"Labour force = 470 + 30 = 500, so LFPR = 50% and WPR = 470/1,000 = 47%. The unemployment rate is measured against the labour force: 30/500 = 6%, not 30/1,000 = 3%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"15 वर्ष और उससे अधिक आयु के 1,000 व्यक्तियों में से 470 काम कर रहे हैं और 30 काम नहीं कर रहे पर काम की तलाश में या उपलब्ध हैं। श्रम बल भागीदारी दर, कार्यकर्ता जनसंख्या अनुपात और बेरोजगारी दर हैं:","optionsHi":["50%, 47% और 6%","50%, 47% और 3%","47%, 50% और 6%","50%, 44% और 6.4%"],"explanationHi":"श्रम बल = 470 + 30 = 500, इसलिए LFPR = 50% और WPR = 470/1,000 = 47%। बेरोजगारी दर श्रम बल के सापेक्ष मापी जाती है: 30/500 = 6%, न कि 30/1,000 = 3%।"},
  {"id":"eco-basics-187","question":"Among the activity status approaches used in India's Periodic Labour Force Survey, which usually gives the HIGHEST unemployment rate?","options":["Usual status (principal plus subsidiary)","Current weekly status","Current daily status","Usual principal status alone"],"answer":2,"explanation":"Current daily status counts person-days of unemployment over the reference week, capturing intermittent joblessness; usual status counts anyone with work for a sizeable part of the year as employed, so its rate is the lowest.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत के आवधिक श्रम बल सर्वेक्षण में प्रयुक्त गतिविधि स्थिति दृष्टिकोणों में से कौन-सा सामान्यतः सर्वाधिक बेरोजगारी दर देता है?","optionsHi":["सामान्य स्थिति (मुख्य तथा सहायक)","चालू साप्ताहिक स्थिति","चालू दैनिक स्थिति","केवल सामान्य मुख्य स्थिति"],"explanationHi":"चालू दैनिक स्थिति संदर्भ सप्ताह में बेरोजगारी के व्यक्ति-दिवस गिनती है, जिससे रुक-रुक कर होने वाली बेरोजगारी पकड़ में आती है; सामान्य स्थिति में वर्ष के पर्याप्त भाग में काम पाने वाले को नियोजित गिना जाता है, इसलिए इसकी दर सबसे कम होती है।"},
  {"id":"eco-basics-188","question":"On a Lorenz diagram, the area between the line of equality and the Lorenz curve is 0.15, while the total area under the line of equality is 0.5. The Gini coefficient is:","options":["0.15","0.30","0.35","0.70"],"answer":1,"explanation":"Gini = area between the line and the curve ÷ total area under the line = 0.15/0.5 = 0.30. 0.35 is the area under the Lorenz curve, not an inequality measure.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"लॉरेंज आरेख पर, समानता रेखा और लॉरेंज वक्र के बीच का क्षेत्रफल 0.15 है, जबकि समानता रेखा के नीचे का कुल क्षेत्रफल 0.5 है। गिनी गुणांक है:","optionsHi":["0.15","0.30","0.35","0.70"],"explanationHi":"गिनी = रेखा और वक्र के बीच का क्षेत्रफल ÷ रेखा के नीचे का कुल क्षेत्रफल = 0.15/0.5 = 0.30। 0.35 लॉरेंज वक्र के नीचे का क्षेत्रफल है, जो असमानता का माप नहीं है।"},
  {"id":"eco-basics-189","question":"A country's HDI dimension indices are: health 0.8, education 0.6 and income 0.5. Using the UNDP's current method, its HDI is about:","options":["0.633","0.621","0.240","0.650"],"answer":1,"explanation":"Since 2010 the HDI is the geometric mean of the three indices: (0.8 × 0.6 × 0.5)^(1/3) = 0.24^(1/3) ≈ 0.621. The arithmetic mean, 0.633, was the older method; 0.24 is the product before taking the cube root.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"किसी देश के HDI आयाम सूचकांक हैं: स्वास्थ्य 0.8, शिक्षा 0.6 और आय 0.5। UNDP की वर्तमान विधि से उसका HDI लगभग है:","optionsHi":["0.633","0.621","0.240","0.650"],"explanationHi":"2010 से HDI तीनों सूचकांकों का गुणोत्तर माध्य है: (0.8 × 0.6 × 0.5)^(1/3) = 0.24^(1/3) ≈ 0.621। समांतर माध्य, 0.633, पुरानी विधि थी; 0.24 घनमूल लेने से पहले का गुणनफल है।"},
  {"id":"eco-basics-190","question":"How many of these statements about the global Multidimensional Poverty Index (UNDP–OPHI) are correct? I. It uses the Alkire–Foster method. II. Its dimensions are health, education and standard of living. III. A person deprived in at least one-third of the weighted indicators is counted as multidimensionally poor. IV. It is based only on household income below a poverty line.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The MPI measures overlapping deprivations such as nutrition, schooling, sanitation and cooking fuel; it does not use income at all, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वैश्विक बहुआयामी गरीबी सूचकांक (UNDP–OPHI) के बारे में इनमें से कितने कथन सही हैं? I. यह एल्काइर–फोस्टर विधि का उपयोग करता है। II. इसके आयाम स्वास्थ्य, शिक्षा और जीवन स्तर हैं। III. भारित संकेतकों के कम से कम एक-तिहाई में वंचित व्यक्ति को बहुआयामी रूप से गरीब गिना जाता है। IV. यह केवल गरीबी रेखा से नीचे की पारिवारिक आय पर आधारित है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। MPI पोषण, स्कूली शिक्षा, स्वच्छता और खाना पकाने के ईंधन जैसी अतिव्यापी वंचनाओं को मापता है; यह आय का बिल्कुल उपयोग नहीं करता, इसलिए IV गलत है।"},
  {"id":"eco-basics-191","question":"Arrange these Indian poverty estimation panels in chronological order: 1. Tendulkar Expert Group 2. Alagh Task Force 3. Rangarajan Expert Group 4. Lakdawala Expert Group","options":["2, 4, 3, 1","4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3"],"answer":3,"explanation":"Alagh Task Force (1979) set calorie-based poverty lines, Lakdawala (1993) moved to state-specific lines, Tendulkar (2009) shifted away from calories, and Rangarajan (2014) revised the Tendulkar lines.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत के इन गरीबी आकलन पैनलों को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. तेंदुलकर विशेषज्ञ समूह 2. अलघ कार्यबल 3. रंगराजन विशेषज्ञ समूह 4. लकड़ावाला विशेषज्ञ समूह","optionsHi":["2, 4, 3, 1","4, 2, 1, 3","2, 1, 4, 3","2, 4, 1, 3"],"explanationHi":"अलघ कार्यबल (1979) ने कैलोरी-आधारित गरीबी रेखाएँ तय कीं, लकड़ावाला (1993) ने राज्य-विशिष्ट रेखाओं की ओर कदम बढ़ाया, तेंदुलकर (2009) कैलोरी से हटे, और रंगराजन (2014) ने तेंदुलकर रेखाओं को संशोधित किया।"},
  {"id":"eco-basics-192","question":"In W. Arthur Lewis's dual-sector model of development, growth proceeds as:","options":["Surplus farm labour moves to industry at a near-constant wage until it runs out","Industry grows first through exports, and agriculture modernises only much later","Capital flows from rich to poor countries until returns are equal everywhere","Population growth slows as income rises, which frees up savings for investment"],"answer":0,"explanation":"With surplus labour in subsistence farming, industry can hire at a wage just above subsistence; profits are reinvested and expansion continues until the surplus is absorbed (the Lewis turning point).","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"डब्ल्यू. आर्थर लुईस के द्वि-क्षेत्रीय विकास मॉडल में, वृद्धि इस प्रकार होती है:","optionsHi":["अधिशेष कृषि श्रम लगभग स्थिर मजदूरी पर उद्योग में जाता है जब तक कि वह समाप्त न हो जाए","उद्योग पहले निर्यात के माध्यम से बढ़ता है, और कृषि का आधुनिकीकरण बहुत बाद में होता है","पूँजी अमीर से गरीब देशों में तब तक प्रवाहित होती है जब तक प्रतिफल हर जगह बराबर न हो जाएँ","आय बढ़ने पर जनसंख्या वृद्धि धीमी होती है, जो निवेश के लिए बचत मुक्त करती है"],"explanationHi":"निर्वाह कृषि में अधिशेष श्रम होने पर उद्योग निर्वाह से थोड़ी ऊपर मजदूरी पर श्रमिक रख सकता है; लाभ का पुनर्निवेश होता है और विस्तार तब तक चलता है जब तक अधिशेष खप न जाए (लुईस मोड़ बिंदु)।"},
  {"id":"eco-basics-193","question":"In W. W. Rostow's stages of economic growth, which stage comes immediately after the 'take-off'?","options":["Preconditions for take-off","Drive to maturity","Age of high mass consumption","Traditional society"],"answer":1,"explanation":"Rostow's sequence is traditional society, preconditions for take-off, take-off, drive to maturity and the age of high mass consumption.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"डब्ल्यू. डब्ल्यू. रोस्टो के आर्थिक वृद्धि के चरणों में, ‘प्रस्थान’ के ठीक बाद कौन-सा चरण आता है?","optionsHi":["प्रस्थान की पूर्व शर्तें","परिपक्वता की ओर अग्रसर","उच्च जन उपभोग का युग","पारंपरिक समाज"],"explanationHi":"रोस्टो का क्रम है: पारंपरिक समाज, प्रस्थान की पूर्व शर्तें, प्रस्थान, परिपक्वता की ओर अग्रसर और उच्च जन उपभोग का युग।"},
  {"id":"eco-basics-194","question":"The Kuznets curve hypothesis holds that, as per capita income grows, income inequality:","options":["Rises steadily without limit","Falls steadily from the start","Stays the same at all incomes","First rises and then falls"],"answer":3,"explanation":"Kuznets argued that early industrialisation widens gaps between the modern and traditional sectors, but as more people move into the modern sector inequality declines, giving an inverted-U.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"कुज़नेट्स वक्र परिकल्पना के अनुसार, जैसे-जैसे प्रति व्यक्ति आय बढ़ती है, आय असमानता:","optionsHi":["बिना सीमा के लगातार बढ़ती रहती है","शुरू से ही लगातार घटती है","सभी आय स्तरों पर समान रहती है","पहले बढ़ती है और फिर घटती है"],"explanationHi":"कुज़नेट्स ने तर्क दिया कि प्रारंभिक औद्योगीकरण आधुनिक और पारंपरिक क्षेत्रों के बीच अंतर बढ़ाता है, परंतु जैसे-जैसे अधिक लोग आधुनिक क्षेत्र में जाते हैं, असमानता घटती है, जिससे उलटे-U का आकार बनता है।"},
  {"id":"eco-basics-195","question":"In one hour of labour, a worker in India can make 4 shirts or 2 kg of rice; a worker in Bangladesh can make 3 shirts or 1 kg of rice. According to comparative advantage:","options":["India should export both goods, as it is better at both","Bangladesh should export rice and India should export shirts","India should export rice and Bangladesh should export shirts","There are no gains from trade, as India is better at both"],"answer":2,"explanation":"A shirt costs India 0.5 kg of rice but Bangladesh only 0.33 kg, so Bangladesh has the comparative advantage in shirts and India in rice, even though India has an absolute advantage in both.","difficulty":"very-hard","source":"RBI Grade B · UPSC Prelims","questionHi":"एक घंटे के श्रम में, भारत का एक श्रमिक 4 कमीजें या 2 kg चावल बना सकता है; बांग्लादेश का एक श्रमिक 3 कमीजें या 1 kg चावल बना सकता है। तुलनात्मक लाभ के अनुसार:","optionsHi":["भारत को दोनों वस्तुएँ निर्यात करनी चाहिए, क्योंकि वह दोनों में बेहतर है","बांग्लादेश को चावल और भारत को कमीजें निर्यात करनी चाहिए","भारत को चावल और बांग्लादेश को कमीजें निर्यात करनी चाहिए","व्यापार से कोई लाभ नहीं है, क्योंकि भारत दोनों में बेहतर है"],"explanationHi":"भारत के लिए एक कमीज की लागत 0.5 kg चावल है पर बांग्लादेश के लिए केवल 0.33 kg, इसलिए कमीजों में तुलनात्मक लाभ बांग्लादेश का और चावल में भारत का है, भले ही दोनों में भारत का निरपेक्ष लाभ है।"},
  {"id":"eco-basics-196","question":"A country's export price index is 120, its import price index is 150 and its export volume index is 125 (all with the same base = 100). Its net barter terms of trade and income terms of trade are:","options":["80 and 100","125 and 100","80 and 150","125 and 156"],"answer":0,"explanation":"Net barter terms = Px/Pm × 100 = 120/150 × 100 = 80. Income terms = (Px/Pm) × export volume = 0.8 × 125 = 100: worse prices, but enough extra exports to keep import capacity unchanged.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"किसी देश का निर्यात कीमत सूचकांक 120, आयात कीमत सूचकांक 150 और निर्यात मात्रा सूचकांक 125 है (सभी का आधार समान = 100)। उसकी शुद्ध वस्तु विनिमय व्यापार शर्तें और आय व्यापार शर्तें हैं:","optionsHi":["80 और 100","125 और 100","80 और 150","125 और 156"],"explanationHi":"शुद्ध वस्तु विनिमय शर्तें = Px/Pm × 100 = 120/150 × 100 = 80। आय शर्तें = (Px/Pm) × निर्यात मात्रा = 0.8 × 125 = 100: कीमतें बदतर, पर इतना अतिरिक्त निर्यात कि आयात क्षमता अपरिवर्तित रहती है।"},
  {"id":"eco-basics-197","question":"Which of these is INCLUDED in India's GDP?","options":["Lottery winnings of a household","Purchase of a second-hand flat","Old-age pension paid by the government","Imputed rent of owner-occupied houses"],"answer":3,"explanation":"Owner-occupiers are treated as renting the house to themselves, so an imputed rent is counted as a service produced. Lottery wins and pensions are transfers, and a second-hand flat was produced in an earlier year.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"इनमें से क्या भारत के GDP में शामिल है?","optionsHi":["किसी परिवार की लॉटरी की जीत","प्रयुक्त (सेकेंड-हैंड) फ्लैट की खरीद","सरकार द्वारा दी गई वृद्धावस्था पेंशन","स्वामी-आवासित मकानों का आरोपित किराया"],"explanationHi":"स्वामी-निवासियों को ऐसा माना जाता है मानो वे मकान को स्वयं को किराए पर दे रहे हों, इसलिए आरोपित किराया उत्पादित सेवा के रूप में गिना जाता है। लॉटरी की जीत और पेंशन अंतरण हैं, और प्रयुक्त फ्लैट पहले के वर्ष में उत्पादित हुआ था।"},
  {"id":"eco-basics-198","question":"By Okun's law with a coefficient of 2, if the actual unemployment rate is 7% and the natural rate is 5%, actual output is about:","options":["4% below potential","2% below potential","1% below potential","7% below potential"],"answer":0,"explanation":"Output gap ≈ −2 × (7 − 5) = −4%, so output is about 4% below potential. Dividing the 2-point unemployment gap by the coefficient gives the wrong 1%.","difficulty":"hard","source":"RBI Grade B Phase 2","questionHi":"गुणांक 2 के साथ ओकुन के नियम से, यदि वास्तविक बेरोजगारी दर 7% और प्राकृतिक दर 5% है, तो वास्तविक उत्पादन लगभग है:","optionsHi":["संभावित से 4% कम","संभावित से 2% कम","संभावित से 1% कम","संभावित से 7% कम"],"explanationHi":"उत्पादन अंतराल ≈ −2 × (7 − 5) = −4%, इसलिए उत्पादन संभावित से लगभग 4% कम है। बेरोजगारी के 2 अंकों के अंतर को गुणांक से भाग देने पर गलत 1% आता है।"},
  {"id":"eco-basics-199","question":"How many commercial banks were nationalised in India in the two rounds of bank nationalisation?","options":["6 in 1969 and 14 in 1980","14 in 1969 and 7 in 1980","20 in 1969, with none in 1980","14 in 1969 and 6 in 1980"],"answer":3,"explanation":"Fourteen major banks with deposits above ₹50 crore were nationalised in July 1969, and six more in April 1980, bringing 20 banks into the public sector.","difficulty":"hard","source":"UPSC Prelims · IBPS PO Mains","questionHi":"बैंक राष्ट्रीयकरण के दो दौरों में भारत में कितने वाणिज्यिक बैंकों का राष्ट्रीयकरण हुआ?","optionsHi":["6 बैंक 1969 में और 14 बैंक 1980 में","14 बैंक 1969 में और 7 बैंक 1980 में","20 बैंक 1969 में, 1980 में कोई नहीं","14 बैंक 1969 में और 6 बैंक 1980 में"],"explanationHi":"₹50 करोड़ से अधिक जमा वाले चौदह प्रमुख बैंकों का राष्ट्रीयकरण जुलाई 1969 में हुआ, और छह और का अप्रैल 1980 में, जिससे 20 बैंक सार्वजनिक क्षेत्र में आ गए।"},
  {"id":"eco-basics-200","question":"The idea of a 'rolling plan', adopted by the Janata Government for 1978–80, is associated with:","options":["Gunnar Myrdal","P. C. Mahalanobis","W. Arthur Lewis","D. R. Gadgil"],"answer":0,"explanation":"Gunnar Myrdal proposed rolling plans, in which targets and allocations are revised every year and a new year is added; Mahalanobis designed the Second Plan and Gadgil the formula for central assistance to States.","difficulty":"hard","source":"UPSC Prelims","questionHi":"जनता सरकार द्वारा 1978–80 के लिए अपनाई गई ‘अनवरत योजना’ का विचार किससे जुड़ा है?","optionsHi":["गुन्नार मिर्डल","पी. सी. महालनोबिस","डब्ल्यू. आर्थर लुईस","डी. आर. गाडगिल"],"explanationHi":"गुन्नार मिर्डल ने अनवरत योजनाओं का प्रस्ताव रखा, जिनमें लक्ष्य और आवंटन हर वर्ष संशोधित होते हैं और एक नया वर्ष जोड़ा जाता है; महालनोबिस ने द्वितीय योजना और गाडगिल ने राज्यों को केंद्रीय सहायता का सूत्र तैयार किया।"},
  {"id":"eco-basics-201","question":"Goods produced this year but still unsold with the producer at the end of the year are:","options":["Excluded from GDP until the year in which they are sold","Included in this year's GDP as a change in inventories","Included in GDP only if they happen to be capital goods","Excluded from GDP but added to the nation's stock of wealth"],"answer":1,"explanation":"GDP measures production, not sales, so unsold output counts as investment in inventories this year. When it is sold next year, inventories fall by the same amount, avoiding double counting.","difficulty":"hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"इस वर्ष उत्पादित परंतु वर्ष के अंत में उत्पादक के पास बिना बिके पड़ी वस्तुएँ:","optionsHi":["उस वर्ष तक GDP से बाहर रहती हैं जिसमें वे बिकती हैं","इस वर्ष के GDP में स्टॉक में परिवर्तन के रूप में शामिल होती हैं","GDP में केवल तभी शामिल होती हैं जब वे पूँजीगत माल हों","GDP से बाहर रहती हैं पर राष्ट्र की संपत्ति के भंडार में जुड़ जाती हैं"],"explanationHi":"GDP उत्पादन को मापता है, बिक्री को नहीं, इसलिए बिना बिका उत्पादन इस वर्ष स्टॉक में निवेश के रूप में गिना जाता है। जब वह अगले वर्ष बिकता है, तो स्टॉक उतना ही घटता है, जिससे दोहरी गणना से बचाव होता है।"},
  {"id":"eco-basics-202","question":"How many of these statements are correct? I. Dadabhai Naoroji made one of the earliest estimates of India's per capita income, for 1867–68. II. V. K. R. V. Rao estimated national income for 1931–32 using a mix of the income and output methods. III. The National Income Committee of 1949 was chaired by P. C. Mahalanobis. IV. The Central Statistical Organisation prepared India's first official national income estimates in 1935.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The CSO was set up only in 1951, after independence; official national income estimates began after the National Income Committee's work, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. दादाभाई नौरोजी ने 1867–68 के लिए भारत की प्रति व्यक्ति आय के सबसे पहले अनुमानों में से एक लगाया। II. वी. के. आर. वी. राव ने आय और उत्पादन विधियों के मिश्रण से 1931–32 की राष्ट्रीय आय का अनुमान लगाया। III. 1949 की राष्ट्रीय आय समिति की अध्यक्षता पी. सी. महालनोबिस ने की। IV. केंद्रीय सांख्यिकी संगठन ने 1935 में भारत के पहले आधिकारिक राष्ट्रीय आय अनुमान तैयार किए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। CSO की स्थापना स्वतंत्रता के बाद 1951 में ही हुई; आधिकारिक राष्ट्रीय आय अनुमान राष्ट्रीय आय समिति के कार्य के बाद शुरू हुए, इसलिए IV गलत है।"},
  {"id":"eco-basics-203","question":"Match the pre-independence or early plan with its author: 1. Bombay Plan 2. Gandhian Plan 3. People's Plan 4. Sarvodaya Plan; a. Jayaprakash Narayan b. M. N. Roy c. Shriman Narayan Agarwal d. A group of leading industrialists","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"answer":3,"explanation":"The Bombay Plan (1944) came from industrialists such as J. R. D. Tata and G. D. Birla; the Gandhian Plan from S. N. Agarwal; the People's Plan from M. N. Roy; and the Sarvodaya Plan (1950) from Jayaprakash Narayan.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"स्वतंत्रता-पूर्व या प्रारंभिक योजना का उसके रचयिता से मिलान कीजिए: 1. बॉम्बे योजना 2. गांधीवादी योजना 3. जन योजना 4. सर्वोदय योजना; a. जयप्रकाश नारायण b. एम. एन. रॉय c. श्रीमन नारायण अग्रवाल d. प्रमुख उद्योगपतियों का एक समूह","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a"],"explanationHi":"बॉम्बे योजना (1944) जे. आर. डी. टाटा और जी. डी. बिड़ला जैसे उद्योगपतियों की थी; गांधीवादी योजना एस. एन. अग्रवाल की; जन योजना एम. एन. रॉय की; और सर्वोदय योजना (1950) जयप्रकाश नारायण की।"},
  {"id":"eco-basics-204","question":"Demand for a good is Qd = 100 − 2P and supply is Qs = 20 + 2P. If the government fixes a minimum price of ₹25, the resulting surplus is:","options":["20 units","10 units","50 units","70 units"],"answer":0,"explanation":"Equilibrium is P = 20, Q = 60. At ₹25, Qd = 50 and Qs = 70, so 20 units remain unsold. 50 and 70 are the separate quantities, not the surplus.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"किसी वस्तु की माँग Qd = 100 − 2P है और पूर्ति Qs = 20 + 2P है। यदि सरकार ₹25 की न्यूनतम कीमत तय करती है, तो परिणामी अधिशेष है:","optionsHi":["20 इकाई","10 इकाई","50 इकाई","70 इकाई"],"explanationHi":"संतुलन P = 20, Q = 60 पर है। ₹25 पर Qd = 50 और Qs = 70, इसलिए 20 इकाइयाँ बिना बिके रह जाती हैं। 50 और 70 अलग-अलग मात्राएँ हैं, अधिशेष नहीं।"},
  {"id":"eco-basics-205","question":"Demand is Qd = 100 − 2P and supply is Qs = 20 + 2P. The government levies a tax of ₹4 per unit, collected from sellers. In the new equilibrium:","options":["Buyers pay ₹24; sellers get ₹20","Buyers pay ₹22; sellers get ₹18","Buyers pay ₹20; sellers get ₹16","Buyers pay ₹21; sellers get ₹17"],"answer":1,"explanation":"Supply becomes Qs = 20 + 2(P − 4); setting 100 − 2P = 12 + 2P gives P = ₹22, so sellers keep ₹18. With equally sloped curves the ₹4 burden is split equally, whoever pays it legally.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"माँग Qd = 100 − 2P है और पूर्ति Qs = 20 + 2P है। सरकार विक्रेताओं से वसूल किया जाने वाला ₹4 प्रति इकाई का कर लगाती है। नए संतुलन में:","optionsHi":["क्रेता ₹24 चुकाते हैं; विक्रेताओं को ₹20 मिलते हैं","क्रेता ₹22 चुकाते हैं; विक्रेताओं को ₹18 मिलते हैं","क्रेता ₹20 चुकाते हैं; विक्रेताओं को ₹16 मिलते हैं","क्रेता ₹21 चुकाते हैं; विक्रेताओं को ₹17 मिलते हैं"],"explanationHi":"पूर्ति Qs = 20 + 2(P − 4) हो जाती है; 100 − 2P = 12 + 2P रखने पर P = ₹22 आता है, इसलिए विक्रेता ₹18 रखते हैं। समान ढलान वाले वक्रों में ₹4 का भार बराबर बँटता है, चाहे कानूनी रूप से इसे कोई भी चुकाए।"},
  {"id":"eco-basics-206","question":"In a market where demand is Qd = 100 − 2P and supply Qs = 20 + 2P, a ₹4 per-unit tax cuts the quantity traded from 60 to 56. The deadweight loss of the tax is:","options":["₹16","₹224","₹8","₹4"],"answer":2,"explanation":"Deadweight loss = ½ × tax × fall in quantity = ½ × 4 × 4 = ₹8. ₹224 (4 × 56) is the revenue collected, which is a transfer rather than a loss.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"जिस बाजार में माँग Qd = 100 − 2P और पूर्ति Qs = 20 + 2P है, वहाँ ₹4 प्रति इकाई का कर व्यापारित मात्रा को 60 से घटाकर 56 कर देता है। कर की भार-हानि (डेडवेट लॉस) है:","optionsHi":["₹16","₹224","₹8","₹4"],"explanationHi":"भार-हानि = ½ × कर × मात्रा में कमी = ½ × 4 × 4 = ₹8। ₹224 (4 × 56) वसूला गया राजस्व है, जो हानि नहीं बल्कि अंतरण है।"},
  {"id":"eco-basics-207","question":"For the demand curve Q = 100 − 2P, the price elasticity of demand (absolute) at a price of ₹20 is:","options":["1.50","0.40","2.00","0.67"],"answer":3,"explanation":"Point elasticity = (dQ/dP) × P/Q = 2 × 20/60 ≈ 0.67. Elasticity changes along a straight-line demand curve; it equals 1 only at the midpoint (P = 25).","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"माँग वक्र Q = 100 − 2P के लिए, ₹20 की कीमत पर माँग की कीमत लोच (निरपेक्ष) है:","optionsHi":["1.50","0.40","2.00","0.67"],"explanationHi":"बिंदु लोच = (dQ/dP) × P/Q = 2 × 20/60 ≈ 0.67। सरल रेखीय माँग वक्र के साथ लोच बदलती है; यह केवल मध्य बिंदु (P = 25) पर 1 होती है।"},
  {"id":"eco-basics-208","question":"A firm's total cost is TC = 100 + 10Q + Q². At what output is its average total cost lowest, and what is that minimum?","options":["Q = 10; ATC = ₹30","Q = 5; ATC = ₹35","Q = 10; ATC = ₹20","Q = 20; ATC = ₹35"],"answer":0,"explanation":"ATC = 100/Q + 10 + Q is lowest where MC = ATC: 10 + 2Q = 100/Q + 10 + Q gives Q = 10, and ATC = 10 + 10 + 10 = ₹30. ₹20 forgets the fixed cost per unit.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"किसी फर्म की कुल लागत TC = 100 + 10Q + Q² है। किस उत्पादन पर उसकी औसत कुल लागत सबसे कम है, और वह न्यूनतम क्या है?","optionsHi":["Q = 10; ATC = ₹30","Q = 5; ATC = ₹35","Q = 10; ATC = ₹20","Q = 20; ATC = ₹35"],"explanationHi":"ATC = 100/Q + 10 + Q वहाँ न्यूनतम है जहाँ MC = ATC: 10 + 2Q = 100/Q + 10 + Q से Q = 10 आता है, और ATC = 10 + 10 + 10 = ₹30। ₹20 प्रति इकाई स्थिर लागत को भूल जाता है।"},
  {"id":"eco-basics-209","question":"A competitive firm with total cost TC = 100 + 10Q + Q² can sell any quantity at ₹50. Its profit-maximising output and profit are:","options":["Q = 25; profit ₹275","Q = 20; profit ₹300","Q = 20; profit ₹400","Q = 40; loss of ₹100"],"answer":1,"explanation":"Set P = MC: 50 = 10 + 2Q, so Q = 20. Profit = 50 × 20 − (100 + 200 + 400) = ₹300. ₹400 forgets the fixed cost of ₹100.","difficulty":"hard","source":"RBI Grade B Phase 2 · SSC CGL Tier 2","questionHi":"कुल लागत TC = 100 + 10Q + Q² वाली एक प्रतिस्पर्धी फर्म किसी भी मात्रा को ₹50 पर बेच सकती है। उसका लाभ-अधिकतम उत्पादन और लाभ हैं:","optionsHi":["Q = 25; लाभ ₹275","Q = 20; लाभ ₹300","Q = 20; लाभ ₹400","Q = 40; ₹100 की हानि"],"explanationHi":"P = MC रखें: 50 = 10 + 2Q, इसलिए Q = 20। लाभ = 50 × 20 − (100 + 200 + 400) = ₹300। ₹400 में ₹100 की स्थिर लागत भूल जाया जाता है।"},
  {"id":"eco-basics-210","question":"A shop owner reports an accounting profit of ₹5 lakh. To run the shop she gave up a salaried job paying ₹6 lakh, and her own capital in the shop could have earned ₹1 lakh elsewhere. Her economic profit is:","options":["₹5 lakh","−₹1 lakh","−₹2 lakh","₹12 lakh"],"answer":2,"explanation":"Economic profit = accounting profit − implicit costs = 5 − 6 − 1 = −₹2 lakh. Counting only the forgone salary gives −₹1 lakh; economically she would be better off in the job.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"एक दुकान मालकिन ₹5 लाख का लेखांकन लाभ बताती है। दुकान चलाने के लिए उसने ₹6 लाख वेतन वाली नौकरी छोड़ी, और दुकान में उसकी अपनी पूँजी कहीं और ₹1 लाख कमा सकती थी। उसका आर्थिक लाभ है:","optionsHi":["₹5 लाख","−₹1 लाख","−₹2 लाख","₹12 लाख"],"explanationHi":"आर्थिक लाभ = लेखांकन लाभ − अंतर्निहित लागतें = 5 − 6 − 1 = −₹2 लाख। केवल छोड़े गए वेतन को गिनने पर −₹1 लाख आता है; आर्थिक दृष्टि से वह नौकरी में बेहतर होती।"},
  {"id":"eco-basics-211","question":"A firm has fixed costs of ₹10,000, sells its product at ₹50 and has an average variable cost of ₹30. Its break-even output is:","options":["200 units","333 units","250 units","500 units"],"answer":3,"explanation":"Each unit contributes 50 − 30 = ₹20 towards fixed costs, so break-even output = 10,000/20 = 500 units. Dividing by the price (200) ignores variable costs.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"एक फर्म की स्थिर लागत ₹10,000 है, वह अपना उत्पाद ₹50 पर बेचती है और उसकी औसत परिवर्ती लागत ₹30 है। उसका सम-विच्छेद उत्पादन है:","optionsHi":["200 इकाई","333 इकाई","250 इकाई","500 इकाई"],"explanationHi":"प्रत्येक इकाई स्थिर लागत में 50 − 30 = ₹20 का योगदान देती है, इसलिए सम-विच्छेद उत्पादन = 10,000/20 = 500 इकाई। कीमत से भाग देने (200) पर परिवर्ती लागतों की उपेक्षा हो जाती है।"},
  {"id":"eco-basics-212","question":"For the last unit bought, good X (price ₹10) gives a marginal utility of 40 and good Y (price ₹20) gives 60. With the same budget, to raise her total utility the consumer should:","options":["Buy more Y and less X, since Y gives more satisfaction per unit","Keep the same bundle, since both goods give positive marginal utility","Buy less X and more Y, since Y has the higher marginal utility","Buy more X and less Y, since X gives more utility per rupee"],"answer":3,"explanation":"MU per rupee is 40/10 = 4 for X and 60/20 = 3 for Y. Shifting spending towards X raises utility until MUx/Px = MUy/Py (the equi-marginal principle).","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"खरीदी गई अंतिम इकाई के लिए, वस्तु X (कीमत ₹10) 40 की सीमांत उपयोगिता देती है और वस्तु Y (कीमत ₹20) 60 देती है। उसी बजट के साथ, अपनी कुल उपयोगिता बढ़ाने के लिए उपभोक्ता को:","optionsHi":["Y अधिक और X कम खरीदना चाहिए, क्योंकि Y प्रति इकाई अधिक संतुष्टि देती है","वही बंडल रखना चाहिए, क्योंकि दोनों वस्तुएँ धनात्मक सीमांत उपयोगिता देती हैं","X कम और Y अधिक खरीदना चाहिए, क्योंकि Y की सीमांत उपयोगिता अधिक है","X अधिक और Y कम खरीदना चाहिए, क्योंकि X प्रति रुपया अधिक उपयोगिता देती है"],"explanationHi":"प्रति रुपया MU X के लिए 40/10 = 4 और Y के लिए 60/20 = 3 है। व्यय को X की ओर खिसकाने से उपयोगिता तब तक बढ़ती है जब तक MUx/Px = MUy/Py न हो जाए (सम-सीमांत सिद्धांत)।"},
  {"id":"eco-basics-213","question":"Assertion (A): Every Giffen good is an inferior good, but not every inferior good is a Giffen good. Reason (R): For a Giffen good, the negative income effect of a price change is strong enough to outweigh the substitution effect.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"For most inferior goods the substitution effect dominates and demand still falls when price rises. Only when the perverse income effect is large enough does demand rise with price, making the good a Giffen good.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"अभिकथन (A): प्रत्येक गिफिन वस्तु निकृष्ट वस्तु होती है, पर प्रत्येक निकृष्ट वस्तु गिफिन वस्तु नहीं होती। कारण (R): गिफिन वस्तु के लिए, कीमत परिवर्तन का ऋणात्मक आय प्रभाव प्रतिस्थापन प्रभाव को पछाड़ने के लिए पर्याप्त प्रबल होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"अधिकांश निकृष्ट वस्तुओं में प्रतिस्थापन प्रभाव हावी रहता है और कीमत बढ़ने पर भी माँग घटती है। केवल जब विपरीत आय प्रभाव पर्याप्त बड़ा हो, तभी माँग कीमत के साथ बढ़ती है, जिससे वस्तु गिफिन वस्तु बनती है।"},
  {"id":"eco-basics-214","question":"Under the RBI's framework for early recognition of stress, a term loan whose instalment has been overdue for 75 days is classified as:","options":["SMA-1","SMA-2","Sub-standard asset (NPA)","SMA-0"],"answer":1,"explanation":"Special Mention Accounts are SMA-0 (up to 30 days overdue), SMA-1 (31–60 days) and SMA-2 (61–90 days). An account becomes an NPA only when overdue for more than 90 days.","difficulty":"very-hard","source":"RBI Grade B · IBPS PO Mains","questionHi":"तनाव की शीघ्र पहचान के RBI के ढाँचे के अंतर्गत, ऐसा सावधि ऋण जिसकी किस्त 75 दिनों से अतिदेय है, वर्गीकृत किया जाता है:","optionsHi":["SMA-1","SMA-2","अवमानक परिसंपत्ति (NPA)","SMA-0"],"explanationHi":"विशेष उल्लेख खाते SMA-0 (30 दिन तक अतिदेय), SMA-1 (31–60 दिन) और SMA-2 (61–90 दिन) हैं। कोई खाता NPA तभी बनता है जब वह 90 दिन से अधिक अतिदेय हो।"},
  {"id":"eco-basics-215","question":"Under the Insolvency and Bankruptcy Code, 2016, as amended in 2019, the corporate insolvency resolution process must ordinarily be completed within:","options":["90 days, extendable by 90 days, with an outer limit of 270 days","270 days, with no extension allowed under any circumstances","180 days, extendable by 90 days, with an outer limit of 330 days","365 days, extendable by 180 days, with an outer limit of 545 days"],"answer":2,"explanation":"The Code allows 180 days plus a one-time extension of up to 90 days; the 2019 amendment set an outer limit of 330 days including time spent in litigation.","difficulty":"hard","source":"RBI Grade B · UPSC Prelims","questionHi":"दिवाला और शोधन अक्षमता संहिता, 2016 के अंतर्गत, जैसा 2019 में संशोधित हुआ, कॉर्पोरेट दिवाला समाधान प्रक्रिया सामान्यतः कितने समय में पूरी होनी चाहिए?","optionsHi":["90 दिन, 90 दिन तक बढ़ाने योग्य, अधिकतम सीमा 270 दिन के साथ","270 दिन, किसी भी परिस्थिति में विस्तार की अनुमति नहीं","180 दिन, 90 दिन तक बढ़ाने योग्य, अधिकतम सीमा 330 दिन के साथ","365 दिन, 180 दिन तक बढ़ाने योग्य, अधिकतम सीमा 545 दिन के साथ"],"explanationHi":"संहिता 180 दिन और 90 दिन तक के एक बार के विस्तार की अनुमति देती है; 2019 के संशोधन ने मुकदमेबाजी में लगे समय सहित 330 दिन की अधिकतम सीमा तय की।"},
  {"id":"eco-basics-216","question":"Domestic scheduled commercial banks must lend at least what share of their adjusted net bank credit (or credit equivalent of off-balance-sheet exposure, whichever is higher) to the priority sector?","options":["40%","18%","32%","50%"],"answer":0,"explanation":"The overall priority sector target for domestic banks is 40%. 18% is the sub-target for agriculture, a common trap.","difficulty":"hard","source":"RBI Grade B · IBPS PO Mains","questionHi":"घरेलू अनुसूचित वाणिज्यिक बैंकों को अपने समायोजित शुद्ध बैंक ऋण (या तुलन-पत्र-बाह्य जोखिम के ऋण समतुल्य, जो भी अधिक हो) का कम से कम कितना हिस्सा प्राथमिकता क्षेत्र को उधार देना होता है?","optionsHi":["40%","18%","32%","50%"],"explanationHi":"घरेलू बैंकों के लिए कुल प्राथमिकता क्षेत्र लक्ष्य 40% है। 18% कृषि के लिए उप-लक्ष्य है, जो आम जाल है।"},
  {"id":"eco-basics-217","question":"Since 2018–19, the Government has fixed Minimum Support Prices for notified kharif crops at no less than:","options":["1.5 times the C2 cost","1.5 times the A2+FL cost","1.25 times the A2+FL cost","2 times the A2 cost"],"answer":1,"explanation":"The 2018–19 Budget committed to MSP of at least one and a half times the cost of production, which CACP measures as A2+FL (paid-out costs plus imputed family labour). The Swaminathan Commission had sought 1.5 times the fuller C2 cost.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2018–19 से सरकार ने अधिसूचित खरीफ फसलों के लिए न्यूनतम समर्थन मूल्य कम से कम कितने पर तय किए हैं?","optionsHi":["1.5 गुना C2 लागत","1.5 गुना A2+FL लागत","1.25 गुना A2+FL लागत","2 गुना A2 लागत"],"explanationHi":"2018–19 के बजट में उत्पादन लागत के कम से कम डेढ़ गुना MSP का वादा किया गया, जिसे CACP A2+FL (चुकाई गई लागतें और आरोपित पारिवारिक श्रम) के रूप में मापता है। स्वामीनाथन आयोग ने अधिक व्यापक C2 लागत का 1.5 गुना माँगा था।"},
  {"id":"eco-basics-218","question":"How many of these statements about the National Food Security Act, 2013 are correct? I. It covers up to 75% of the rural and 50% of the urban population. II. Priority households are entitled to 5 kg of foodgrains per person per month. III. Antyodaya Anna Yojana households are entitled to 35 kg per household per month. IV. Entitlements are given only to families below the Tendulkar poverty line.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Beneficiaries are identified by States within the coverage ceilings, which are far wider than the Tendulkar poverty line, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"राष्ट्रीय खाद्य सुरक्षा अधिनियम, 2013 के बारे में इनमें से कितने कथन सही हैं? I. यह ग्रामीण जनसंख्या के 75% और शहरी जनसंख्या के 50% तक को कवर करता है। II. प्राथमिकता वाले परिवार प्रति व्यक्ति प्रति माह 5 kg खाद्यान्न के हकदार हैं। III. अंत्योदय अन्न योजना के परिवार प्रति परिवार प्रति माह 35 kg के हकदार हैं। IV. हक केवल तेंदुलकर गरीबी रेखा से नीचे के परिवारों को दिए जाते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। लाभार्थियों की पहचान राज्य कवरेज की सीमाओं के भीतर करते हैं, जो तेंदुलकर गरीबी रेखा से कहीं अधिक व्यापक हैं, इसलिए IV गलत है।"},
  {"id":"eco-basics-219","question":"Match the WTO domestic support category with its description: 1. Amber box 2. Blue box 3. Green box; a. Support with minimal trade distortion, such as research and extension b. Trade-distorting support that is subject to reduction commitments c. Direct payments under programmes that limit production","options":["1-a, 2-c, 3-b","1-c, 2-b, 3-a","1-b, 2-a, 3-c","1-b, 2-c, 3-a"],"answer":3,"explanation":"Amber box support such as price support distorts trade and must be capped; blue box payments are tied to production-limiting schemes; green box measures are exempt as they cause little distortion.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"WTO की घरेलू सहायता श्रेणी का उसके विवरण से मिलान कीजिए: 1. एम्बर बॉक्स 2. ब्लू बॉक्स 3. ग्रीन बॉक्स; a. न्यूनतम व्यापार विकृति वाली सहायता, जैसे अनुसंधान और प्रसार b. व्यापार को विकृत करने वाली सहायता जो कटौती प्रतिबद्धताओं के अधीन है c. उत्पादन सीमित करने वाले कार्यक्रमों के अंतर्गत प्रत्यक्ष भुगतान","optionsHi":["1-a, 2-c, 3-b","1-c, 2-b, 3-a","1-b, 2-a, 3-c","1-b, 2-c, 3-a"],"explanationHi":"मूल्य समर्थन जैसी एम्बर बॉक्स सहायता व्यापार को विकृत करती है और उस पर सीमा लगानी होती है; ब्लू बॉक्स भुगतान उत्पादन-सीमित करने वाली योजनाओं से जुड़े होते हैं; ग्रीन बॉक्स उपाय छूट प्राप्त हैं क्योंकि वे बहुत कम विकृति उत्पन्न करते हैं।"},
  {"id":"eco-basics-220","question":"Match the trade remedy with the situation it addresses: 1. Anti-dumping duty 2. Countervailing duty 3. Safeguard duty; a. A sudden surge of imports seriously injuring domestic industry, even if trade is fair b. Imports priced below their normal value in the exporter's home market c. Imports that benefit from subsidies in the exporting country","options":["1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b","1-b, 2-a, 3-c"],"answer":0,"explanation":"Anti-dumping duty offsets unfairly low pricing, countervailing duty offsets foreign subsidies, and a safeguard duty gives temporary relief from an import surge without any finding of unfair trade.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"व्यापार उपचार का उस स्थिति से मिलान कीजिए जिसका वह समाधान करता है: 1. पाटनरोधी शुल्क 2. प्रतिशुल्क (काउंटरवेलिंग ड्यूटी) 3. रक्षोपाय शुल्क; a. आयात में अचानक उछाल जो घरेलू उद्योग को गंभीर क्षति पहुँचाए, भले ही व्यापार उचित हो b. निर्यातक के अपने देश के बाजार में उनके सामान्य मूल्य से कम कीमत पर आयात c. निर्यातक देश में सब्सिडी से लाभान्वित आयात","optionsHi":["1-b, 2-c, 3-a","1-c, 2-b, 3-a","1-a, 2-c, 3-b","1-b, 2-a, 3-c"],"explanationHi":"पाटनरोधी शुल्क अनुचित रूप से कम कीमत का प्रतिकार करता है, प्रतिशुल्क विदेशी सब्सिडी का प्रतिकार करता है, और रक्षोपाय शुल्क अनुचित व्यापार का कोई निष्कर्ष निकले बिना आयात में उछाल से अस्थायी राहत देता है।"},
  {"id":"eco-basics-221","question":"Under free trade a final good sells for ₹100 and uses imported inputs worth ₹60. India now levies a 20% tariff on the final good and a 10% tariff on the input. The effective rate of protection for the domestic producer is:","options":["20%","54%","35%","10%"],"answer":2,"explanation":"Value added rises from 100 − 60 = ₹40 to 120 − 66 = ₹54, so effective protection = 14/40 = 35%. It exceeds the 20% nominal tariff because inputs are taxed less than the output.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"मुक्त व्यापार में एक अंतिम वस्तु ₹100 में बिकती है और ₹60 के आयातित आगत का उपयोग करती है। भारत अब अंतिम वस्तु पर 20% और आगत पर 10% का प्रशुल्क लगाता है। घरेलू उत्पादक के लिए प्रभावी संरक्षण दर है:","optionsHi":["20%","54%","35%","10%"],"explanationHi":"मूल्य वर्धन ₹40 (100 − 60) से बढ़कर 120 − 66 = ₹54 हो जाता है, इसलिए प्रभावी संरक्षण = 14/40 = 35%। यह 20% नाममात्र प्रशुल्क से अधिक है क्योंकि आगतों पर निर्गत की तुलना में कम कर लगता है।"},
  {"id":"eco-basics-222","question":"The 'infant industry' argument in trade policy is used to justify:","options":["Permanent tariffs on all manufactured imports to save foreign exchange","Temporary protection for a new industry until it gains scale and skills","Export subsidies for industries that are already mature and competitive","A ban on foreign investment in all industries of strategic importance"],"answer":1,"explanation":"A young industry may have high costs at first; temporary protection lets it learn and grow to an efficient size, after which protection should be withdrawn.","difficulty":"moderate","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"व्यापार नीति में ‘शिशु उद्योग’ तर्क का उपयोग किसे उचित ठहराने के लिए किया जाता है?","optionsHi":["विदेशी मुद्रा बचाने के लिए सभी विनिर्मित आयातों पर स्थायी प्रशुल्क","किसी नए उद्योग को पैमाना और कौशल प्राप्त होने तक अस्थायी संरक्षण","पहले से परिपक्व और प्रतिस्पर्धी उद्योगों के लिए निर्यात सब्सिडी","सामरिक महत्व के सभी उद्योगों में विदेशी निवेश पर प्रतिबंध"],"explanationHi":"किसी नए उद्योग की लागत शुरू में ऊँची हो सकती है; अस्थायी संरक्षण उसे सीखने और कुशल आकार तक बढ़ने देता है, जिसके बाद संरक्षण हटा लेना चाहिए।"},
  {"id":"eco-basics-223","question":"When the price of tea rises by 10%, the quantity of coffee demanded rises by 5%. The cross-price elasticity and the relationship between the goods are:","options":["−0.5; complements","+2.0; substitutes","−2.0; complements","+0.5; substitutes"],"answer":3,"explanation":"Cross elasticity = % change in coffee demand ÷ % change in tea price = 5/10 = +0.5. A positive value means the goods are substitutes; 2.0 inverts the ratio.","difficulty":"hard","source":"SSC CGL Tier 2","questionHi":"जब चाय की कीमत 10% बढ़ती है, तो कॉफी की माँगी गई मात्रा 5% बढ़ती है। आड़ी कीमत लोच और वस्तुओं के बीच संबंध हैं:","optionsHi":["−0.5; पूरक","+2.0; स्थानापन्न","−2.0; पूरक","+0.5; स्थानापन्न"],"explanationHi":"आड़ी लोच = कॉफी की माँग में % परिवर्तन ÷ चाय की कीमत में % परिवर्तन = 5/10 = +0.5। धनात्मक मान का अर्थ है कि वस्तुएँ स्थानापन्न हैं; 2.0 अनुपात को उलट देता है।"},
  {"id":"eco-basics-224","question":"Match the institution with its headquarters: 1. Asian Infrastructure Investment Bank 2. New Development Bank 3. Asian Development Bank 4. International Monetary Fund; a. Washington, D.C. b. Manila c. Shanghai d. Beijing","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":2,"explanation":"The AIIB is in Beijing, the BRICS-led New Development Bank in Shanghai, the ADB in Manila and the IMF in Washington, D.C.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"संस्था का उसके मुख्यालय से मिलान कीजिए: 1. एशियाई अवसंरचना निवेश बैंक 2. न्यू डेवलपमेंट बैंक 3. एशियाई विकास बैंक 4. अंतर्राष्ट्रीय मुद्रा कोष; a. वाशिंगटन, डी.सी. b. मनीला c. शंघाई d. बीजिंग","optionsHi":["1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b"],"explanationHi":"AIIB बीजिंग में है, BRICS के नेतृत्व वाला न्यू डेवलपमेंट बैंक शंघाई में, ADB मनीला में और IMF वाशिंगटन, डी.सी. में।"},
  {"id":"eco-basics-225","question":"Match the committee with its subject: 1. Narasimham Committee (1991) 2. Tarapore Committee (1997) 3. Nachiket Mor Committee (2013) 4. Kelkar Task Forces (2002); a. Direct and indirect tax reform b. Capital account convertibility c. Comprehensive financial services for small businesses and low-income households d. Reform of the financial system","options":["1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-a, 2-b, 3-c, 4-d"],"answer":1,"explanation":"Narasimham (1991) recommended financial sector reforms, Tarapore a road map to capital account convertibility, Nachiket Mor financial inclusion, and the Kelkar task forces reform of direct and indirect taxes.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"समिति का उसके विषय से मिलान कीजिए: 1. नरसिम्हम समिति (1991) 2. तारापोर समिति (1997) 3. नचिकेत मोर समिति (2013) 4. केलकर कार्यबल (2002); a. प्रत्यक्ष और अप्रत्यक्ष कर सुधार b. पूँजी खाता परिवर्तनीयता c. छोटे व्यवसायों और कम आय वाले परिवारों के लिए व्यापक वित्तीय सेवाएँ d. वित्तीय प्रणाली का सुधार","optionsHi":["1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-a, 2-b, 3-c, 4-d"],"explanationHi":"नरसिम्हम (1991) ने वित्तीय क्षेत्र सुधारों की अनुशंसा की, तारापोर ने पूँजी खाता परिवर्तनीयता की रूपरेखा, नचिकेत मोर ने वित्तीय समावेशन, और केलकर कार्यबल ने प्रत्यक्ष और अप्रत्यक्ष करों के सुधार की।"},
  {"id":"eco-basics-226","question":"Say's law, which Keynes rejected, states that:","options":["Supply creates its own demand, so a general glut cannot last","Demand creates its own supply, so output always follows spending","Saving and investment are equalised only by changes in income","Wages are rigid downwards, so unemployment can persist for long"],"answer":0,"explanation":"Say argued that producing goods generates the income to buy them, so a general glut is impossible. Keynes showed that saving can leak out of spending and leave demand short, so unemployment can persist.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"सेय का नियम, जिसे कीन्स ने अस्वीकार किया, कहता है कि:","optionsHi":["पूर्ति अपनी माँग स्वयं उत्पन्न करती है, इसलिए सामान्य अति-आपूर्ति टिक नहीं सकती","माँग अपनी पूर्ति स्वयं उत्पन्न करती है, इसलिए उत्पादन सदैव व्यय का अनुसरण करता है","बचत और निवेश केवल आय में परिवर्तन से ही बराबर होते हैं","मजदूरी नीचे की ओर अनम्य होती है, इसलिए बेरोजगारी लंबे समय तक बनी रह सकती है"],"explanationHi":"सेय ने तर्क दिया कि वस्तुओं का उत्पादन उन्हें खरीदने की आय उत्पन्न करता है, इसलिए सामान्य अति-आपूर्ति असंभव है। कीन्स ने दिखाया कि बचत व्यय से बाहर रिस सकती है और माँग को कम छोड़ सकती है, इसलिए बेरोजगारी बनी रह सकती है।"},
  {"id":"eco-basics-227","question":"In Keynes's General Theory, the level of employment in the short run is determined by:","options":["The real wage fixed in a competitive labour market","The quantity of money circulating in the economy","The interest rate set by the supply of savings","Effective demand for goods and services"],"answer":3,"explanation":"Keynes argued that firms hire as many workers as needed to meet effective demand, the point where aggregate demand equals aggregate supply, which can be below full employment.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"कीन्स की जनरल थ्योरी में, अल्पकाल में रोजगार का स्तर किससे निर्धारित होता है?","optionsHi":["प्रतिस्पर्धी श्रम बाजार में तय वास्तविक मजदूरी","अर्थव्यवस्था में चलन में मुद्रा की मात्रा","बचत की पूर्ति द्वारा निर्धारित ब्याज दर","वस्तुओं और सेवाओं की प्रभावी माँग"],"explanationHi":"कीन्स ने तर्क दिया कि फर्में उतने श्रमिक रखती हैं जितने प्रभावी माँग, यानी वह बिंदु जहाँ समग्र माँग समग्र पूर्ति के बराबर हो, को पूरा करने के लिए चाहिए, जो पूर्ण रोजगार से कम हो सकता है।"},
  {"id":"eco-basics-228","question":"National income is ₹1,000 crore. Undistributed corporate profits are ₹50 crore, corporation tax ₹40 crore, transfer payments to households ₹60 crore and personal direct taxes ₹70 crore. Ignoring other items, personal disposable income is:","options":["₹900 crore","₹970 crore","₹1,040 crore","₹840 crore"],"answer":0,"explanation":"Personal income = 1,000 − 50 − 40 + 60 = ₹970 crore; personal disposable income = 970 − 70 = ₹900 crore. ₹970 crore forgets personal taxes, and ₹840 crore leaves out the transfer payments.","difficulty":"very-hard","source":"SSC CGL Tier 2 · UPSC Prelims","questionHi":"राष्ट्रीय आय ₹1,000 करोड़ है। अवितरित कंपनी लाभ ₹50 करोड़, निगम कर ₹40 करोड़, परिवारों को अंतरण भुगतान ₹60 करोड़ और व्यक्तिगत प्रत्यक्ष कर ₹70 करोड़ हैं। अन्य मदों की उपेक्षा करने पर, वैयक्तिक प्रयोज्य आय है:","optionsHi":["₹900 करोड़","₹970 करोड़","₹1,040 करोड़","₹840 करोड़"],"explanationHi":"वैयक्तिक आय = 1,000 − 50 − 40 + 60 = ₹970 करोड़; वैयक्तिक प्रयोज्य आय = 970 − 70 = ₹900 करोड़। ₹970 करोड़ में व्यक्तिगत कर भूल जाया जाता है, और ₹840 करोड़ में अंतरण भुगतान छूट जाते हैं।"},
  {"id":"eco-basics-229","question":"Full-employment income is ₹1,200 crore, but equilibrium income is only ₹1,000 crore. The marginal propensity to consume is 0.75. The deflationary gap is:","options":["₹200 crore","₹50 crore","₹800 crore","₹150 crore"],"answer":1,"explanation":"The deflationary gap is the shortfall of aggregate demand at full employment. With a multiplier of 1/(1 − 0.75) = 4, an income shortfall of ₹200 crore needs only 200/4 = ₹50 crore of extra demand.","difficulty":"very-hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"पूर्ण रोजगार आय ₹1,200 करोड़ है, परंतु संतुलन आय केवल ₹1,000 करोड़ है। सीमांत उपभोग प्रवृत्ति 0.75 है। अपस्फीतिकारी अंतराल है:","optionsHi":["₹200 करोड़","₹50 करोड़","₹800 करोड़","₹150 करोड़"],"explanationHi":"अपस्फीतिकारी अंतराल पूर्ण रोजगार पर समग्र माँग की कमी है। गुणक 1/(1 − 0.75) = 4 होने पर, ₹200 करोड़ की आय की कमी के लिए केवल 200/4 = ₹50 करोड़ की अतिरिक्त माँग चाहिए।"},
  {"id":"eco-basics-230","question":"Water is essential to life yet cheap, while diamonds are inessential yet very dear. The marginalist resolution of this 'paradox of value' is that:","options":["Price reflects total utility, which is higher for diamonds than for water","Price reflects only the labour used, which is far greater for diamonds","Water is a public good, so the market cannot put a price on it","Price reflects marginal utility, which is low for abundant water"],"answer":3,"explanation":"Total utility of water is huge, but because it is plentiful the last unit adds little satisfaction; scarce diamonds have high marginal utility. Prices follow marginal, not total, utility.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"जल जीवन के लिए अनिवार्य है फिर भी सस्ता है, जबकि हीरे अनावश्यक हैं फिर भी बहुत महँगे। ‘मूल्य के विरोधाभास’ का सीमांतवादी समाधान यह है कि:","optionsHi":["कीमत कुल उपयोगिता को दर्शाती है, जो जल की तुलना में हीरों के लिए अधिक है","कीमत केवल प्रयुक्त श्रम को दर्शाती है, जो हीरों में कहीं अधिक है","जल एक सार्वजनिक वस्तु है, इसलिए बाजार उस पर कीमत नहीं लगा सकता","कीमत सीमांत उपयोगिता को दर्शाती है, जो प्रचुर जल के लिए कम है"],"explanationHi":"जल की कुल उपयोगिता विशाल है, परंतु प्रचुर होने के कारण अंतिम इकाई बहुत कम संतुष्टि जोड़ती है; दुर्लभ हीरों की सीमांत उपयोगिता अधिक होती है। कीमतें कुल नहीं, सीमांत उपयोगिता का अनुसरण करती हैं।"},
  {"id":"eco-basics-231","question":"Assertion (A): A competitive firm earning zero economic profit in the long run is still covering its owner's opportunity costs. Reason (R): Normal profit is included in the firm's average cost curve.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Economic costs include the normal return the owner could earn elsewhere; when price equals average cost, that normal profit is earned, so zero economic profit is not a loss.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"अभिकथन (A): दीर्घकाल में शून्य आर्थिक लाभ कमाने वाली प्रतिस्पर्धी फर्म फिर भी अपने स्वामी की अवसर लागतों को पूरा कर रही होती है। कारण (R): सामान्य लाभ फर्म के औसत लागत वक्र में शामिल होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"आर्थिक लागतों में वह सामान्य प्रतिफल शामिल है जो स्वामी कहीं और कमा सकता था; जब कीमत औसत लागत के बराबर होती है, तो वह सामान्य लाभ कमाया जाता है, इसलिए शून्य आर्थिक लाभ हानि नहीं है।"},
  {"id":"eco-basics-232","question":"Which of these is an EXTERNAL economy of scale?","options":["Bulk-buying discounts on raw materials won by a single large firm","Use of large specialised machines inside one big plant","Hiring specialist managers once a firm grows large enough","A pool of skilled labour and suppliers in an industrial cluster"],"answer":3,"explanation":"External economies arise from the growth of the whole industry or region and lower costs for every firm in it, as in clusters like Tiruppur or Bengaluru. The others are internal economies of a single firm's size.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"इनमें से कौन-सी पैमाने की बाह्य बचत है?","optionsHi":["एक अकेली बड़ी फर्म द्वारा कच्चे माल पर थोक खरीद की छूट प्राप्त करना","एक बड़े संयंत्र के भीतर बड़ी विशिष्ट मशीनों का उपयोग","फर्म के पर्याप्त बड़ी होने पर विशेषज्ञ प्रबंधकों को रखना","औद्योगिक समूह में कुशल श्रम और आपूर्तिकर्ताओं का भंडार"],"explanationHi":"बाह्य बचतें पूरे उद्योग या क्षेत्र की वृद्धि से उत्पन्न होती हैं और उसकी प्रत्येक फर्म की लागत घटाती हैं, जैसे तिरुपुर या बेंगलुरु जैसे समूहों में। अन्य एक अकेली फर्म के आकार की आंतरिक बचतें हैं।"},
  {"id":"eco-basics-233","question":"A monopolist sells the same product in two separated markets. At its profit-maximising prices, the price elasticity of demand is 2 in market 1 and 4 in market 2 (absolute values). The ratio of the price in market 1 to the price in market 2 is:","options":["1.5","2.0","0.67","1.0"],"answer":0,"explanation":"Profit maximisation requires equal MR in both markets: P1(1 − 1/2) = P2(1 − 1/4), so P1/P2 = 0.75/0.5 = 1.5. The less elastic market pays more; the ratio is not simply 4/2.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"एक एकाधिकारी एक ही उत्पाद को दो अलग-अलग बाजारों में बेचता है। अपनी लाभ-अधिकतम कीमतों पर, बाजार 1 में माँग की कीमत लोच 2 और बाजार 2 में 4 है (निरपेक्ष मान)। बाजार 1 की कीमत और बाजार 2 की कीमत का अनुपात है:","optionsHi":["1.5","2.0","0.67","1.0"],"explanationHi":"लाभ अधिकतमीकरण के लिए दोनों बाजारों में MR बराबर होना चाहिए: P1(1 − 1/2) = P2(1 − 1/4), इसलिए P1/P2 = 0.75/0.5 = 1.5। कम लोचदार बाजार अधिक कीमत चुकाता है; अनुपात केवल 4/2 नहीं है।"},
  {"id":"eco-basics-234","question":"A 'natural monopoly' arises when:","options":["A government grants one firm a patent on a new product","Average cost falls over the whole range of market demand","A single firm owns the entire supply of a key natural resource","Rival firms agree to divide the market and fix a common price"],"answer":1,"explanation":"With huge fixed costs, as in power transmission or water pipelines, one firm can serve the whole market more cheaply than two. Patents and resource ownership are legal or resource barriers, and collusion is a cartel.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"‘प्राकृतिक एकाधिकार’ तब उत्पन्न होता है जब:","optionsHi":["सरकार किसी नए उत्पाद पर एक फर्म को पेटेंट देती है","औसत लागत बाजार माँग की पूरी सीमा में घटती है","एक अकेली फर्म किसी प्रमुख प्राकृतिक संसाधन की संपूर्ण आपूर्ति की स्वामी होती है","प्रतिद्वंद्वी फर्में बाजार बाँटने और एक समान कीमत तय करने पर सहमत होती हैं"],"explanationHi":"भारी स्थिर लागत के साथ, जैसे बिजली पारेषण या जल पाइपलाइन में, एक फर्म पूरे बाजार को दो फर्मों से अधिक सस्ते में सेवा दे सकती है। पेटेंट और संसाधन स्वामित्व कानूनी या संसाधन अवरोध हैं, और सांठगांठ कार्टेल है।"},
  {"id":"eco-basics-235","question":"A software engineer earns ₹50,000 a month; the best alternative job open to her pays ₹35,000. Her economic rent and transfer earnings are:","options":["₹35,000 and ₹15,000","₹50,000 and ₹35,000","₹15,000 and ₹50,000","₹15,000 and ₹35,000"],"answer":3,"explanation":"Transfer earnings are what she would get in her next best use (₹35,000); economic rent is the surplus above that, 50,000 − 35,000 = ₹15,000.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"एक सॉफ्टवेयर इंजीनियर ₹50,000 प्रति माह कमाती है; उसके लिए उपलब्ध सर्वोत्तम वैकल्पिक नौकरी ₹35,000 देती है। उसका आर्थिक लगान और अंतरण आय हैं:","optionsHi":["₹35,000 और ₹15,000","₹50,000 और ₹35,000","₹15,000 और ₹50,000","₹15,000 और ₹35,000"],"explanationHi":"अंतरण आय वह है जो उसे अपने अगले सर्वोत्तम उपयोग में मिलती (₹35,000); आर्थिक लगान उससे ऊपर का अधिशेष है, 50,000 − 35,000 = ₹15,000।"},
  {"id":"eco-basics-236","question":"Alfred Marshall's concept of 'quasi-rent' refers to:","options":["Rent paid to landlords for land of above-average fertility","The long-run surplus earned by any factor in fixed supply","Short-run earnings of fixed factors above variable costs","The excess of a worker's wage over the legal minimum wage"],"answer":2,"explanation":"In the short run machines and plant cannot be changed, so whatever revenue exceeds variable cost is a rent-like return to them; it disappears in the long run as capacity adjusts.","difficulty":"very-hard","source":"RBI Grade B Phase 2","questionHi":"अल्फ्रेड मार्शल की ‘अर्ध-लगान’ की अवधारणा किसे संदर्भित करती है?","optionsHi":["औसत से अधिक उर्वरता वाली भूमि के लिए भू-स्वामियों को चुकाया गया लगान","स्थिर पूर्ति वाले किसी भी साधन द्वारा कमाया गया दीर्घकालिक अधिशेष","स्थिर साधनों की परिवर्ती लागतों से अधिक अल्पकालिक कमाई","किसी श्रमिक की मजदूरी का वैधानिक न्यूनतम मजदूरी से अधिक होना"],"explanationHi":"अल्पकाल में मशीनें और संयंत्र बदले नहीं जा सकते, इसलिए परिवर्ती लागत से जितना भी राजस्व अधिक होता है, वह उनके लिए लगान जैसा प्रतिफल है; दीर्घकाल में क्षमता समायोजित होने पर यह समाप्त हो जाता है।"},
  {"id":"eco-basics-237","question":"In a competitive market a firm's 5th worker would add 8 units of output a day. The product sells for ₹50 a unit and the daily wage is ₹450. The firm should:","options":["Hire the worker, as the output of 8 units is positive","Hire the worker, as the wage is below the average product's value","Hire the worker, as total revenue still rises with more output","Not hire the worker, as MRP of ₹400 is below the ₹450 wage"],"answer":3,"explanation":"Marginal revenue product = 8 × 50 = ₹400, which is less than the ₹450 wage, so hiring would cut profit. A firm hires until MRP equals the wage.","difficulty":"very-hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"एक प्रतिस्पर्धी बाजार में किसी फर्म का 5वाँ श्रमिक प्रतिदिन 8 इकाई उत्पादन जोड़ेगा। उत्पाद ₹50 प्रति इकाई बिकता है और दैनिक मजदूरी ₹450 है। फर्म को:","optionsHi":["श्रमिक को रखना चाहिए, क्योंकि 8 इकाइयों का उत्पादन धनात्मक है","श्रमिक को रखना चाहिए, क्योंकि मजदूरी औसत उत्पाद के मूल्य से कम है","श्रमिक को रखना चाहिए, क्योंकि अधिक उत्पादन से कुल राजस्व अब भी बढ़ता है","श्रमिक को नहीं रखना चाहिए, क्योंकि ₹400 का MRP ₹450 की मजदूरी से कम है"],"explanationHi":"सीमांत राजस्व उत्पाद = 8 × 50 = ₹400, जो ₹450 की मजदूरी से कम है, इसलिए रखने से लाभ घटेगा। फर्म तब तक श्रमिक रखती है जब तक MRP मजदूरी के बराबर न हो जाए।"},
  {"id":"eco-basics-238","question":"How many of these statements about the Green Revolution in India are correct? I. It was centred at first on high-yielding varieties of wheat. II. Its early gains were concentrated in Punjab, Haryana and western Uttar Pradesh. III. It relied on assured irrigation, chemical fertilisers and HYV seeds. IV. Its largest early gains were in pulses and coarse grains.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Pulses and coarse grains gained little; the package favoured wheat and later rice in irrigated areas, so IV is wrong.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत में हरित क्रांति के बारे में इनमें से कितने कथन सही हैं? I. यह पहले गेहूँ की उच्च उपज किस्मों पर केंद्रित थी। II. इसके शुरुआती लाभ पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में केंद्रित थे। III. यह सुनिश्चित सिंचाई, रासायनिक उर्वरकों और HYV बीजों पर निर्भर थी। IV. इसके सबसे बड़े शुरुआती लाभ दलहन और मोटे अनाजों में थे।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। दलहन और मोटे अनाजों को बहुत कम लाभ हुआ; यह पैकेज सिंचित क्षेत्रों में गेहूँ और बाद में चावल के पक्ष में था, इसलिए IV गलत है।"},
  {"id":"eco-basics-239","question":"Operation Flood, launched in 1970, which made India a leading milk producer, was led by:","options":["M. S. Swaminathan, through the ICAR","Verghese Kurien, through the NDDB","Norman Borlaug, through CIMMYT","C. Subramaniam, through the FCI"],"answer":1,"explanation":"Verghese Kurien led Operation Flood through the National Dairy Development Board, spreading the Anand pattern of dairy cooperatives. Swaminathan, Borlaug and Subramaniam are linked with the Green Revolution.","difficulty":"moderate","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"1970 में शुरू किया गया ऑपरेशन फ्लड, जिसने भारत को अग्रणी दूध उत्पादक बनाया, का नेतृत्व किसने किया?","optionsHi":["एम. एस. स्वामीनाथन, ICAR के माध्यम से","वर्गीज कुरियन, NDDB के माध्यम से","नॉर्मन बोरलॉग, CIMMYT के माध्यम से","सी. सुब्रमण्यम, FCI के माध्यम से"],"explanationHi":"वर्गीज कुरियन ने राष्ट्रीय डेयरी विकास बोर्ड के माध्यम से ऑपरेशन फ्लड का नेतृत्व किया, जिसने डेयरी सहकारी समितियों के आणंद प्रतिरूप का प्रसार किया। स्वामीनाथन, बोरलॉग और सुब्रमण्यम हरित क्रांति से जुड़े हैं।"},
  {"id":"eco-basics-240","question":"Match the form of economic integration with its feature: 1. Free trade area 2. Customs union 3. Common market 4. Economic union; a. Free trade plus a common external tariff b. Members remove tariffs among themselves but keep their own external tariffs c. A common market plus harmonised economic policies, often with a common currency d. A customs union plus free movement of labour and capital","options":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-d, 4-c"],"answer":3,"explanation":"Each stage adds to the previous one: an FTA removes internal tariffs, a customs union adds a common external tariff, a common market adds factor mobility, and an economic union adds common policies.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"आर्थिक एकीकरण के रूप का उसकी विशेषता से मिलान कीजिए: 1. मुक्त व्यापार क्षेत्र 2. सीमा शुल्क संघ 3. साझा बाजार 4. आर्थिक संघ; a. मुक्त व्यापार और साझा बाह्य प्रशुल्क b. सदस्य आपस में प्रशुल्क हटा देते हैं पर अपने-अपने बाह्य प्रशुल्क रखते हैं c. साझा बाजार के साथ समन्वित आर्थिक नीतियाँ, प्रायः साझा मुद्रा के साथ d. सीमा शुल्क संघ के साथ श्रम और पूँजी की मुक्त आवाजाही","optionsHi":["1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d","1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-d, 4-c"],"explanationHi":"प्रत्येक चरण पिछले में कुछ जोड़ता है: FTA आंतरिक प्रशुल्क हटाता है, सीमा शुल्क संघ साझा बाह्य प्रशुल्क जोड़ता है, साझा बाजार साधनों की गतिशीलता जोड़ता है, और आर्थिक संघ साझा नीतियाँ जोड़ता है।"},
  {"id":"eco-basics-241","question":"The WTO's 'most-favoured-nation' principle requires a member to:","options":["Extend to all members any trade advantage it gives to one member","Treat imported goods like domestic goods once they enter its market","Give developing countries lower tariffs than developed countries","Remove all of its tariffs within an agreed number of years"],"answer":0,"explanation":"MFN means non-discrimination between trading partners: a concession to one must go to all, with exceptions such as free trade areas. Treating imports like domestic goods is the separate 'national treatment' principle.","difficulty":"hard","source":"UPSC Prelims","questionHi":"WTO का ‘सर्वाधिक तरजीही राष्ट्र’ सिद्धांत किसी सदस्य से अपेक्षा करता है कि वह:","optionsHi":["किसी एक सदस्य को दिया गया कोई भी व्यापारिक लाभ सभी सदस्यों को दे","आयातित वस्तुओं के अपने बाजार में प्रवेश करने पर उनके साथ घरेलू वस्तुओं जैसा व्यवहार करे","विकासशील देशों को विकसित देशों की तुलना में कम प्रशुल्क दे","एक सहमत संख्या के वर्षों में अपने सभी प्रशुल्क हटा दे"],"explanationHi":"MFN का अर्थ है व्यापारिक साझेदारों के बीच अभेदभाव: एक को दी गई रियायत सभी को देनी होगी, मुक्त व्यापार क्षेत्रों जैसे अपवादों के साथ। आयातों के साथ घरेलू वस्तुओं जैसा व्यवहार करना अलग ‘राष्ट्रीय व्यवहार’ सिद्धांत है।"},
  {"id":"eco-basics-242","question":"In the second stage of the demographic transition:","options":["Birth and death rates are both high, so population grows slowly","Death rates fall sharply but birth rates stay high, so growth is fast","Birth rates fall towards death rates, so population growth slows down","Birth and death rates are both low, so population is nearly stable"],"answer":1,"explanation":"Better health and food cut death rates first, while birth rates fall only later with social change; the gap causes a population explosion. The other options describe stages one, three and four.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"जनांकिकीय संक्रमण की द्वितीय अवस्था में:","optionsHi":["जन्म और मृत्यु दर दोनों ऊँची होती हैं, इसलिए जनसंख्या धीरे-धीरे बढ़ती है","मृत्यु दर तेजी से घटती है पर जन्म दर ऊँची रहती है, इसलिए वृद्धि तीव्र होती है","जन्म दर मृत्यु दर की ओर घटती है, इसलिए जनसंख्या वृद्धि धीमी पड़ती है","जन्म और मृत्यु दर दोनों नीची होती हैं, इसलिए जनसंख्या लगभग स्थिर रहती है"],"explanationHi":"बेहतर स्वास्थ्य और भोजन पहले मृत्यु दर घटाते हैं, जबकि जन्म दर सामाजिक परिवर्तन के साथ बाद में घटती है; यह अंतर जनसंख्या विस्फोट का कारण बनता है। अन्य विकल्प पहली, तीसरी और चौथी अवस्थाओं का वर्णन करते हैं।"},
  {"id":"eco-basics-243","question":"The Eleventh Five-Year Plan (2007–12) had as its theme:","options":["Faster, more inclusive and sustainable growth","Towards faster and more inclusive growth","Growth with social justice and equality","Removal of poverty and attainment of self-reliance"],"answer":1,"explanation":"The Eleventh Plan aimed at 'faster and more inclusive growth'; the Twelfth (2012–17) added 'sustainable'. Growth with social justice was the Ninth Plan's focus and removal of poverty the Fifth's.","difficulty":"hard","source":"UPSC Prelims","questionHi":"ग्यारहवीं पंचवर्षीय योजना (2007–12) का विषय था:","optionsHi":["तीव्रतर, अधिक समावेशी और सतत वृद्धि","तीव्रतर और अधिक समावेशी वृद्धि की ओर","सामाजिक न्याय और समानता के साथ वृद्धि","गरीबी हटाना और आत्मनिर्भरता प्राप्त करना"],"explanationHi":"ग्यारहवीं योजना का लक्ष्य ‘तीव्रतर और अधिक समावेशी वृद्धि’ था; बारहवीं (2012–17) ने ‘सतत’ जोड़ा। सामाजिक न्याय के साथ वृद्धि नौवीं योजना का और गरीबी हटाना पाँचवीं का केंद्र था।"},
  {"id":"eco-basics-244","question":"How many of these statements about a firm's short-run cost curves are correct? I. When marginal cost is below average cost, average cost is falling. II. The marginal cost curve cuts both the AVC and ATC curves at their minimum points. III. Average fixed cost falls continuously as output rises. IV. The vertical gap between ATC and AVC widens as output rises.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The gap between ATC and AVC is average fixed cost, which keeps falling, so the two curves get closer as output rises; IV is wrong.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"फर्म के अल्पकालिक लागत वक्रों के बारे में इनमें से कितने कथन सही हैं? I. जब सीमांत लागत औसत लागत से कम होती है, तो औसत लागत घट रही होती है। II. सीमांत लागत वक्र AVC और ATC दोनों वक्रों को उनके न्यूनतम बिंदुओं पर काटता है। III. उत्पादन बढ़ने के साथ औसत स्थिर लागत लगातार घटती है। IV. उत्पादन बढ़ने के साथ ATC और AVC के बीच का ऊर्ध्वाधर अंतर बढ़ता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। ATC और AVC के बीच का अंतर औसत स्थिर लागत है, जो लगातार घटती है, इसलिए उत्पादन बढ़ने पर दोनों वक्र निकट आते जाते हैं; IV गलत है।"},
  {"id":"eco-basics-245","question":"The Fifth Five-Year Plan (1974–79), which aimed at the removal of poverty and self-reliance, was:","options":["Completed in full and followed by a three-year 'Plan holiday'","Replaced midway by an action agenda prepared by NITI Aayog","Abandoned in its first year because of a war with Pakistan","Ended a year early, in 1978, by the Janata Government"],"answer":3,"explanation":"The Janata Government ended the Fifth Plan in 1978 and started a rolling plan for 1978–80. The Plan holiday (1966–69) followed the Third Plan, and NITI Aayog came only in 2015.","difficulty":"hard","source":"UPSC Prelims","questionHi":"पाँचवीं पंचवर्षीय योजना (1974–79), जिसका लक्ष्य गरीबी हटाना और आत्मनिर्भरता था:","optionsHi":["पूरी तरह पूर्ण हुई और उसके बाद तीन वर्ष का ‘योजना अवकाश’ आया","बीच में ही नीति आयोग द्वारा तैयार एक कार्य-एजेंडा से बदल दी गई","पाकिस्तान के साथ युद्ध के कारण पहले ही वर्ष में छोड़ दी गई","जनता सरकार द्वारा 1978 में एक वर्ष पहले ही समाप्त कर दी गई"],"explanationHi":"जनता सरकार ने पाँचवीं योजना को 1978 में समाप्त किया और 1978–80 के लिए अनवरत योजना शुरू की। योजना अवकाश (1966–69) तृतीय योजना के बाद आया, और नीति आयोग केवल 2015 में आया।"},
  {"id":"eco-basics-246","question":"How many of these statements are correct? I. The Planning Commission was set up in March 1950 by a resolution of the Union Cabinet. II. The Planning Commission was a constitutional body. III. The National Development Council was set up in 1952. IV. The Prime Minister was the ex officio chairman of the Planning Commission.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. The Planning Commission was created by executive resolution and had no constitutional or statutory basis, so II is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. योजना आयोग की स्थापना मार्च 1950 में केंद्रीय मंत्रिमंडल के एक प्रस्ताव द्वारा की गई थी। II. योजना आयोग एक संवैधानिक निकाय था। III. राष्ट्रीय विकास परिषद की स्थापना 1952 में हुई थी। IV. प्रधानमंत्री योजना आयोग के पदेन अध्यक्ष थे।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, III और IV सही हैं। योजना आयोग कार्यकारी प्रस्ताव द्वारा बनाया गया था और इसका कोई संवैधानिक या सांविधिक आधार नहीं था, इसलिए II गलत है।"},
  {"id":"eco-basics-247","question":"Which of these is a STOCK variable rather than a flow?","options":["The fiscal deficit for the year","Exports of goods in a quarter","Foreign exchange reserves","Gross fixed capital formation"],"answer":2,"explanation":"A stock is measured at a point in time, like reserves held on 31 March; flows are measured over a period, like a year's deficit, exports or investment. Deficits add to the stock of debt.","difficulty":"moderate","source":"SSC CGL Tier 2","questionHi":"इनमें से कौन-सा प्रवाह के बजाय स्टॉक चर है?","optionsHi":["वर्ष का राजकोषीय घाटा","एक तिमाही में वस्तुओं का निर्यात","विदेशी मुद्रा भंडार","सकल स्थिर पूँजी निर्माण"],"explanationHi":"स्टॉक किसी बिंदु-समय पर मापा जाता है, जैसे 31 मार्च को धारित भंडार; प्रवाह किसी अवधि में मापे जाते हैं, जैसे किसी वर्ष का घाटा, निर्यात या निवेश। घाटे ऋण के स्टॉक में जुड़ते हैं।"},
  {"id":"eco-basics-248","question":"In the four-sector model of the circular flow of income, which group consists only of leakages (withdrawals)?","options":["Saving, taxes and imports","Investment, government spending and exports","Saving, investment and exports","Taxes, transfer payments and imports"],"answer":0,"explanation":"Saving, taxes and imports take money out of the income–spending loop; investment, government spending and exports inject it. Transfer payments add to household income, so they are not withdrawals.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"आय के चार-क्षेत्रीय चक्रीय प्रवाह मॉडल में, कौन-सा समूह केवल रिसावों (निकासियों) से बना है?","optionsHi":["बचत, कर और आयात","निवेश, सरकारी व्यय और निर्यात","बचत, निवेश और निर्यात","कर, अंतरण भुगतान और आयात"],"explanationHi":"बचत, कर और आयात आय–व्यय चक्र से धन बाहर निकालते हैं; निवेश, सरकारी व्यय और निर्यात उसमें धन डालते हैं। अंतरण भुगतान परिवारों की आय में जुड़ते हैं, इसलिए वे निकासी नहीं हैं।"},
  {"id":"eco-basics-249","question":"Assertion (A): In a two-sector economy, realised (ex post) saving always equals realised investment. Reason (R): Unplanned changes in inventories make up any gap between planned saving and planned investment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"If households plan to save more than firms plan to invest, unsold goods pile up as unplanned inventory investment, so measured saving and investment are equal; the mismatch then drives income towards equilibrium.","difficulty":"hard","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"अभिकथन (A): द्वि-क्षेत्रीय अर्थव्यवस्था में, वास्तविक (पश्च) बचत सदैव वास्तविक निवेश के बराबर होती है। कारण (R): स्टॉक में अनियोजित परिवर्तन नियोजित बचत और नियोजित निवेश के बीच के किसी भी अंतर को पाट देते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"यदि परिवार फर्मों की नियोजित निवेश से अधिक बचत की योजना बनाते हैं, तो बिना बिके माल अनियोजित स्टॉक निवेश के रूप में जमा हो जाता है, इसलिए मापी गई बचत और निवेश बराबर होते हैं; यह असंतुलन फिर आय को संतुलन की ओर ले जाता है।"},
  {"id":"eco-basics-250","question":"Economies of scope exist when:","options":["Average cost falls as the output of a single product rises","Making two products together costs less than making them apart","Firms in a cluster gain from shared suppliers and skilled labour","Average cost rises as a firm grows too large to manage well"],"answer":1,"explanation":"Economies of scope come from sharing inputs across products, such as a bank selling loans and insurance through the same branches. The first option is economies of scale and the last diseconomies of scale.","difficulty":"hard","source":"RBI Grade B · SSC CGL Tier 2","questionHi":"विस्तार की मितव्ययिता (इकोनॉमीज़ ऑफ़ स्कोप) तब होती है जब:","optionsHi":["एक अकेले उत्पाद का उत्पादन बढ़ने पर औसत लागत घटती है","दो उत्पादों को साथ बनाना उन्हें अलग-अलग बनाने से सस्ता पड़ता है","किसी समूह की फर्मों को साझा आपूर्तिकर्ताओं और कुशल श्रम से लाभ होता है","फर्म के इतनी बड़ी हो जाने पर कि उसे ठीक से प्रबंधित न किया जा सके, औसत लागत बढ़ती है"],"explanationHi":"विस्तार की मितव्ययिता उत्पादों के बीच आगतों को साझा करने से आती है, जैसे कोई बैंक एक ही शाखाओं से ऋण और बीमा बेचता है। पहला विकल्प पैमाने की मितव्ययिता और अंतिम पैमाने की अमितव्ययिता है।"},
];

